import { BrowserRouter, Routes, Route, Link, useLocation, Navigate } from 'react-router-dom';
import { useState, useEffect, ReactNode } from 'react';
import {
    LayoutDashboard,
    Activity,
    Settings,
    Key,
    Server,
    Users,
    Bell,
    FileText,
    Rocket,
    Sun,
    Moon,
    Laptop,
    Radio,
    Brain,
    Network,
    Shield,
    Zap,
    CheckCircle,
    XCircle,
    UserCog
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

// Context
import { LanguageProvider, useLanguage } from './context/LanguageContext';
import { DemoProvider, useDemo } from './context/DemoContext';
import { ThemeProvider, useTheme } from './context/ThemeContext';
import { WebSocketProvider } from './context/WebSocketContext';
import { AttackStatusProvider, useAttackStatus } from './context/AttackStatusContext';
import { LiveModeProvider, useLiveMode } from './context/LiveModeContext';
import Logo from './components/Logo';
import { COMPANY_NAME_CN } from './config/branding';
import {
    fetchApiReadiness,
    fetchCurrentUserSession,
    fetchSystemBadges,
    isRequestAbortError
} from './services/api';

// Pages
import Dashboard from './pages/Dashboard';
import Sites from './pages/Sites';
import DeploymentWizard from './pages/DeploymentWizard';
import Scanner from './pages/Scanner';
import FixHistory from './pages/FixHistory';
import SettingsPage from './pages/Settings';
import SuperAdmin from './pages/SuperAdmin';
import AdminUsers from './pages/AdminUsers';
import Alerts from './pages/Alerts';
import Rules from './pages/Rules';
import Agents from './pages/Agents';
import Devices from './pages/Devices';
import AlertDetail from './pages/AlertDetail';
import AgentDetail from './pages/AgentDetail';
import AttackRunDetail from './pages/AttackRunDetail';
import Landing from './pages/Landing';
import Login from './pages/Login';
import BoardStatus from './pages/BoardStatus';
import AgentMonitor from './pages/AgentMonitor';
import FixHistoryDetail from './pages/FixHistoryDetail';
import ScannerRunDetail from './pages/ScannerRunDetail';
import SiteDetail from './pages/SiteDetail';
import TrafficInterceptor from './pages/TrafficInterceptor';
import TrafficSessionDetail from './pages/TrafficSessionDetail';
import AttackSimulator from './pages/AttackSimulator';
import PrivacyPolicy from './pages/PrivacyPolicy';
import TermsOfService from './pages/TermsOfService';
import Promo from './pages/Promo';
import PromoFilm from './pages/PromoFilm';

/**
 * SECURITY FIX CVE-2026-012: Authentication guard for protected routes
 * Improved cold start handling
 */
const PrivateRoute = ({ children }: { children: ReactNode }) => {
    const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
    const [backendReady, setBackendReady] = useState(false);

    useEffect(() => {
        // Check backend readiness first (lightweight health check)
        const checkBackend = async () => {
            try {
                const readiness = await fetchApiReadiness(AbortSignal.timeout(3000));
                if (readiness.ok) {
                    setBackendReady(true);
                    const user = await fetchCurrentUserSession(AbortSignal.timeout(5000));
                    setIsAuthenticated(Boolean(user));
                } else {
                    setBackendReady(true);
                    setIsAuthenticated(false);
                }
            } catch {
                // Backend not ready - don't block UI, show login
                setBackendReady(true); // Allow access to check auth
                setIsAuthenticated(false);
            }
        };
        checkBackend();
    }, []);

    // Show loading while checking backend and auth
    if (!backendReady || isAuthenticated === null) {
        return (
            <div className="flex items-center justify-center h-screen bg-background">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            </div>
        );
    }

    // Redirect to login if not authenticated
    if (!isAuthenticated) {
        return <Navigate to="/login" replace />;
    }

    return <>{children}</>;
};

/**
 * SECURITY FIX CVE-2026-012: Admin-only route guard
 * Improved cold start handling
 */
const AdminRoute = ({ children }: { children: ReactNode }) => {
    const [userRole, setUserRole] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const checkRole = async () => {
            try {
                const user = await fetchCurrentUserSession(AbortSignal.timeout(5000));
                setUserRole(user?.role || null);
            } catch {
                setUserRole(null);
            }
            setIsLoading(false);
        };
        checkRole();
    }, []);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-screen bg-background">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            </div>
        );
    }

    if (userRole !== 'admin') {
        return <Navigate to="/dashboard" replace />;
    }

    return <>{children}</>;
};

const Sidebar = () => {
    const location = useLocation();
    const { t } = useLanguage();
    const { status: attackStatus } = useAttackStatus();
    const { attackSimEnabled } = useDemo();
    const { liveModeEnabled } = useLiveMode();
    const [badges, setBadges] = useState({ agents: 0, alerts: 0, devices: 0, agentMonitor: 0, traffic: 0, scanner: 0 });
    const [profile, setProfile] = useState<{ name: string; role: string; initials: string; plan: string }>({
        name: 'Unknown User',
        role: 'N/A',
        initials: '??',
        plan: 'starter'
    });

    // Don't show sidebar on standalone public pages
    if (location.pathname === '/' || location.pathname === '/login' || location.pathname === '/privacy' || location.pathname === '/terms' || location.pathname === '/promo' || location.pathname === '/promo-film') return null;

    const platformItems = [
        { icon: LayoutDashboard, label: t('nav.dashboard'), path: '/dashboard' },
        { icon: Users, label: t('nav.agents'), path: '/agents', badge: badges.agents > 0 ? badges.agents : undefined },
        { icon: Brain, label: t('nav.agent_monitor'), path: '/agent-monitor', badge: badges.agentMonitor > 0 ? badges.agentMonitor : undefined },
        { icon: Network, label: t('nav.traffic_interceptor'), path: '/traffic', badge: badges.traffic > 0 ? badges.traffic : undefined },
        ...(attackSimEnabled ? [{ icon: Shield, label: t('nav.attack_simulator'), path: '/attack-sim' }] : []),
        { icon: Radio, label: t('nav.devices'), path: '/devices', badge: badges.devices > 0 ? badges.devices : undefined },
        { icon: Server, label: t('nav.sites'), path: '/sites' },
        { icon: Rocket, label: t('nav.deployment'), path: '/deploy' },
        { icon: Activity, label: t('nav.monitoring'), path: '/scanner', badge: badges.scanner > 0 ? badges.scanner : undefined },
        { icon: Settings, label: t('nav.settings'), path: '/settings' },
        { icon: Key, label: t('nav.keys'), path: '/admin' },
        ...(profile.role === 'admin' ? [{ icon: UserCog, label: t('nav.super_admin'), path: '/super-admin' }] : []),
    ];

    const navGroups = [
        {
            title: t('nav.platform'),
            items: platformItems
        },
        {
            title: t('nav.governance'),
            items: [
                { icon: FileText, label: t('nav.audit'), path: '/history' },
                ...(profile.role === 'admin' ? [{ icon: Shield, label: 'Rules', path: '/rules' }] : []),
                { icon: Bell, label: t('nav.alerts'), path: '/alerts', badge: badges.alerts > 0 ? badges.alerts : undefined },
            ]
        }
    ];

    const progressPercent = attackStatus.total > 0
        ? Math.round((attackStatus.completed / attackStatus.total) * 100)
        : 0;

    useEffect(() => {
        let disposed = false;
        let activeController: AbortController | null = null;

        const loadBadges = async () => {
            const controller = new AbortController();
            activeController?.abort();
            activeController = controller;

            try {
                const data = await fetchSystemBadges(controller.signal);
                if (disposed || controller.signal.aborted) {
                    return;
                }
                setBadges({
                    agents: data.agents || 0,
                    alerts: data.alerts || 0,
                    devices: data.devices || 0,
                    agentMonitor: data.agentMonitor || 0,
                    traffic: data.traffic || 0,
                    scanner: data.scanner || 0,
                });
            } catch (e) {
                if (!isRequestAbortError(e, controller.signal)) {
                    // ignore badge polling failures here; page-level fallbacks already handle empty badges
                }
            }
        };

        void loadBadges();
        if (!liveModeEnabled) {
            return () => {
                disposed = true;
                activeController?.abort();
            };
        }

        const badgeInterval = setInterval(() => {
            void loadBadges();
        }, 4000);

        return () => {
            disposed = true;
            activeController?.abort();
            clearInterval(badgeInterval);
        };
    }, [liveModeEnabled]);

    useEffect(() => {
        const controller = new AbortController();

        fetchCurrentUserSession(controller.signal)
            .then((user) => {
                if (controller.signal.aborted) {
                    return;
                }
                if (!user) {
                    throw new Error('FG-AUTH-ME-401');
                }
                const name = user.username || user.email || '未命名用户';
                const initials = String(name).split(/\s+/).map((x: string) => x[0] || '').join('').slice(0, 2).toUpperCase() || '??';
                setProfile({
                    name,
                    role: user.role || '未设置角色',
                    initials,
                    plan: user.plan || 'starter'
                });
            })
            .catch((error) => {
                if (isRequestAbortError(error, controller.signal)) {
                    return;
                }
                setProfile({ name: '未命名用户', role: '未设置角色', initials: '??', plan: 'starter' });
            });

        return () => controller.abort();
    }, []);

    return (
        <aside className="z-20 hidden w-64 flex-col justify-between border-r border-border bg-card md:flex">
            <div>
                {/* Logo */}
                <div className="border-b border-border/50 px-6 py-3">
                    <div className="space-y-1">
                        <Logo
                            tier={
                                profile.plan === 'pro' ? 'professional' :
                                    profile.plan === 'ultra' ? 'enterprise' :
                                        (profile.plan as any || 'starter')
                            }
                            showText={true}
                            className="origin-left scale-90"
                        />
                        <div className="pl-1 text-[11px] text-muted-foreground">{COMPANY_NAME_CN}</div>
                    </div>
                </div>

                {/* Nav Links */}
                <nav className="p-3 space-y-4">
                    {navGroups.map((group, idx) => (
                        <div key={idx}>
                            <div className="px-3 py-2 text-xxs font-medium tracking-wider text-muted-foreground uppercase">{group.title}</div>
                            <div className="space-y-0.5">
                                {group.items.map((item: any) => {
                                    const isActive = location.pathname === item.path;
                                    return (
                                        <Link
                                            key={item.path}
                                            to={item.path}
                                            className={`flex items-center gap-3 px-3 py-2 text-sm rounded-md transition-colors group ${isActive
                                                ? 'text-foreground bg-primary/10 border border-primary/20 shadow-sm'
                                                : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                                                }`}
                                        >
                                            <item.icon
                                                size={18}
                                                strokeWidth={1.5}
                                                className={isActive ? 'text-primary' : 'group-hover:text-foreground'}
                                            />
                                            <span className="font-normal">{item.label}</span>
                                            {item.path === '/scanner' && (
                                                <span className="ml-auto flex h-1.5 w-1.5 rounded-full bg-emerald-500"></span>
                                            )}
                                            {item.badge && (
                                                <span className="ml-auto text-xxs bg-red-500/10 text-red-400 px-1.5 py-0.5 rounded border border-red-500/20">{item.badge}</span>
                                            )}
                                        </Link>
                                    );
                                })}
                            </div>
                        </div>
                    ))}
                </nav>
            </div>

            <div className="p-4 border-t border-border/50 space-y-3">
                {/* Attack Status */}
                <AnimatePresence>
                    {attackSimEnabled && attackStatus.isRunning && (
                        <motion.div
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 'auto' }}
                            exit={{ opacity: 0, height: 0 }}
                            className="overflow-hidden"
                        >
                            <div className="rounded-lg border border-border bg-muted/20 p-3">
                                <div className="flex items-center gap-2 mb-2">
                                    <Zap className="h-4 w-4 text-amber-500" />
                                    <span className="text-xs font-medium text-foreground">{t('nav.attack_simulation')}</span>
                                </div>

                                <div className="space-y-2">
                                    <div className="flex justify-between text-xs">
                                        <span className="text-muted-foreground">{t('nav.attack_sim_progress')}</span>
                                        <span className="font-medium text-foreground">{attackStatus.completed}/{attackStatus.total}</span>
                                    </div>
                                    <div className="h-1.5 overflow-hidden rounded-full bg-muted">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${progressPercent}%` }}
                                            className="h-full rounded-full bg-amber-500"
                                        />
                                    </div>

                                    <div className="flex items-center justify-between pt-1">
                                        <div className="flex items-center gap-1">
                                            <CheckCircle className="h-3 w-3 text-emerald-500" />
                                            <span className="text-xs text-emerald-600 dark:text-emerald-400">{attackStatus.blocked}</span>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            <XCircle className="h-3 w-3 text-rose-500" />
                                            <span className="text-xs text-rose-600 dark:text-rose-400">{attackStatus.allowed}</span>
                                        </div>
                                    </div>

                                    {attackStatus.currentAttack && (
                                        <div className="truncate border-t border-border/60 pt-1 text-xs text-muted-foreground">
                                            {attackStatus.currentAttack}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* User Profile */}
                <Link to="/settings" className="flex items-center gap-3 px-2 py-2 text-sm hover:text-foreground transition-colors">
                    <div className="w-8 h-8 rounded-full bg-primary/20 border border-primary/30 flex items-center justify-center text-primary font-medium text-xs">
                        {profile.initials}
                    </div>
                    <div className="flex flex-col">
                        <span className="text-xs font-medium text-foreground">{profile.name}</span>
                        <span className="text-xxs text-muted-foreground">{profile.role}</span>
                    </div>
                    <Settings size={18} className="ml-auto hover:rotate-90 transition-transform duration-500 text-muted-foreground hover:text-foreground" />
                </Link>
            </div>
        </aside>
    );
}

const Header = () => {
    const { t, language, toggleLanguage } = useLanguage();
    const { isDemoMode, toggleDemoMode, isSwitchingDemoMode } = useDemo();
    const { theme, setTheme } = useTheme();
    const { liveModeEnabled, toggleLiveMode } = useLiveMode();
    const location = useLocation();

    // Don't show header on standalone public pages
    if (location.pathname === '/' || location.pathname === '/login' || location.pathname === '/privacy' || location.pathname === '/terms' || location.pathname === '/promo' || location.pathname === '/promo-film') return null;

    return (
        <header className="sticky top-0 z-10 flex h-16 items-center justify-between gap-3 border-b border-border/50 bg-background px-3 md:px-6">
            <div className="min-w-0 flex items-center gap-3 text-sm text-muted-foreground overflow-hidden">
                <span className="hover:text-foreground cursor-pointer transition-colors truncate">{t('header.overview')}</span>
                <span className="text-muted-foreground/50 shrink-0">/</span>
                <span className="text-foreground font-medium truncate">{t('nav.dashboard')}</span>
            </div>

            <div className="flex items-center gap-2 md:gap-4 shrink-0">
                {/* Status Indicator */}
                <div className="flex items-center gap-2 rounded-full border border-emerald-500/10 bg-emerald-500/5 px-3 py-1.5">
                    <span className="inline-flex h-2 w-2 rounded-full bg-emerald-500"></span>
                    <span className="hidden lg:inline text-xs font-medium text-emerald-500 tracking-tight">{t('header.system_healthy')}</span>
                </div>

                <div className="hidden sm:block h-8 w-px bg-border"></div>

                {/* Theme Toggle */}
                <div className="flex items-center gap-1 bg-muted border border-border rounded-full p-0.5">
                    <button
                        onClick={() => setTheme('light')}
                        className={`p-1 rounded-full transition-all ${theme === 'light' ? 'bg-background shadow text-primary' : 'text-muted-foreground hover:text-foreground'}`}
                        title="Light Mode"
                    >
                        <Sun size={14} />
                    </button>
                    <button
                        onClick={() => setTheme('system')}
                        className={`p-1 rounded-full transition-all ${theme === 'system' ? 'bg-background text-foreground shadow' : 'text-muted-foreground hover:text-foreground'}`}
                        title="System"
                    >
                        <Laptop size={14} />
                    </button>
                    <button
                        onClick={() => setTheme('dark')}
                        className={`p-1 rounded-full transition-all ${theme === 'dark' ? 'bg-background text-primary shadow' : 'text-muted-foreground hover:text-foreground'}`}
                        title="Dark Mode"
                    >
                        <Moon size={14} />
                    </button>
                </div>

                <div className="hidden sm:block h-8 w-px bg-border"></div>

                <button
                    type="button"
                    data-testid="demo-mode-toggle"
                    aria-pressed={isDemoMode}
                    onClick={toggleDemoMode}
                    disabled={isSwitchingDemoMode}
                    className={`flex items-center gap-2 group shrink-0 whitespace-nowrap ${isSwitchingDemoMode ? 'opacity-60 cursor-not-allowed' : 'cursor-pointer'}`}
                >
                    <span className={`text-xs font-medium transition-colors ${isDemoMode ? 'text-primary' : 'text-muted-foreground group-hover:text-foreground'}`}>{t('nav.demo_mode')}</span>
                    <div className={`w-8 h-4 rounded-full relative transition-colors border ${isDemoMode ? 'bg-primary/20 border-primary/50' : 'bg-muted border-border'}`}>
                        <div className={`absolute top-0.5 w-3 h-3 rounded-full shadow-sm transition-all ${isDemoMode ? 'right-0.5 bg-primary' : 'left-0.5 bg-muted-foreground'}`}></div>
                    </div>
                </button>

                <div className="hidden sm:block h-8 w-px bg-border"></div>

                {/* Language Toggle */}
                <div onClick={toggleLanguage} className="flex items-center gap-2 cursor-pointer group">
                    <span className={`text-xs font-medium transition-colors ${language === 'zh' ? 'text-muted-foreground' : 'text-foreground'}`}>EN</span>
                    <div className={`w-8 h-4 rounded-full relative transition-colors ${language === 'zh' ? 'bg-primary/20 border-primary/50' : 'bg-muted border-border'}`}>
                        <div className={`absolute top-0.5 w-3 h-3 rounded-full shadow-sm transition-all ${language === 'zh' ? 'right-0.5 bg-primary' : 'left-0.5 bg-muted-foreground'}`}></div>
                    </div>
                    <span className={`text-xs font-medium transition-colors ${language === 'zh' ? 'text-primary' : 'text-muted-foreground'}`}>中文</span>
                </div>

                <div className="h-8 w-px bg-border"></div>

                {/* Custom Switch (Auto Refresh) */}
                <button type="button" onClick={toggleLiveMode} className="flex items-center gap-2 group cursor-pointer">
                    <span className="text-xs font-medium group-hover:text-foreground transition-colors text-muted-foreground">{t('header.live')}</span>
                    <div className={`w-9 h-5 rounded-full border relative transition-colors ${liveModeEnabled ? 'bg-primary/20 border-primary/50' : 'bg-muted border-border group-hover:border-primary/50'}`}>
                        <div className={`absolute top-0.5 w-3.5 h-3.5 rounded-full shadow-sm transition-all ${liveModeEnabled ? 'right-0.5 bg-primary' : 'left-0.5 bg-muted-foreground'}`}></div>
                    </div>
                </button>
            </div>
        </header>
    )
}

const PageWrapper = ({ children }: { children: React.ReactNode }) => (
    <motion.div
        initial={{ opacity: 0, scale: 0.98 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.98 }}
        transition={{ duration: 0.2 }}
        className="h-full"
    >
        {children}
    </motion.div>
);

const AnimatedRoutes = () => {
    const location = useLocation();
    const { attackSimEnabled, modeResolved } = useDemo();

    return (
        <AnimatePresence mode="wait">
            <Routes location={location} key={location.pathname}>
                {/* Public routes */}
                <Route path="/" element={<PageWrapper><Landing /></PageWrapper>} />
                <Route path="/promo" element={<Promo />} />
                <Route path="/promo-film" element={<PromoFilm />} />
                <Route path="/login" element={<PageWrapper><Login /></PageWrapper>} />
                <Route path="/privacy" element={<PageWrapper><PrivacyPolicy /></PageWrapper>} />
                <Route path="/terms" element={<PageWrapper><TermsOfService /></PageWrapper>} />

                {/* SECURITY FIX CVE-2026-012: Protected routes require authentication */}
                <Route path="/dashboard" element={<PrivateRoute><PageWrapper><Dashboard /></PageWrapper></PrivateRoute>} />
                <Route path="/agents" element={<PrivateRoute><PageWrapper><Agents /></PageWrapper></PrivateRoute>} />
                <Route path="/agent-monitor" element={<PrivateRoute><PageWrapper><AgentMonitor /></PageWrapper></PrivateRoute>} />
                <Route path="/traffic" element={<PrivateRoute><PageWrapper><TrafficInterceptor /></PageWrapper></PrivateRoute>} />
                <Route
                    path="/attack-sim"
                    element={
                        !modeResolved
                            ? <PrivateRoute><PageWrapper><div className="p-8 text-muted-foreground">Loading mode...</div></PageWrapper></PrivateRoute>
                            : attackSimEnabled
                                ? <PrivateRoute><PageWrapper><AttackSimulator /></PageWrapper></PrivateRoute>
                                : <Navigate to="/dashboard" replace />
                    }
                />
                <Route path="/devices" element={<PrivateRoute><PageWrapper><Devices /></PageWrapper></PrivateRoute>} />
                <Route path="/sites" element={<PrivateRoute><PageWrapper><Sites /></PageWrapper></PrivateRoute>} />
                <Route path="/deploy" element={<PrivateRoute><PageWrapper><DeploymentWizard /></PageWrapper></PrivateRoute>} />
                <Route path="/scanner" element={<PrivateRoute><PageWrapper><Scanner /></PageWrapper></PrivateRoute>} />
                <Route path="/scanner/runs/:id" element={<PrivateRoute><PageWrapper><ScannerRunDetail /></PageWrapper></PrivateRoute>} />
                <Route path="/history" element={<PrivateRoute><PageWrapper><FixHistory /></PageWrapper></PrivateRoute>} />
                <Route path="/history/:id" element={<PrivateRoute><PageWrapper><FixHistoryDetail /></PageWrapper></PrivateRoute>} />
                <Route path="/settings" element={<PrivateRoute><PageWrapper><SettingsPage /></PageWrapper></PrivateRoute>} />
                <Route path="/alerts" element={<PrivateRoute><PageWrapper><Alerts /></PageWrapper></PrivateRoute>} />
                <Route path="/alerts/:id" element={<PrivateRoute><PageWrapper><AlertDetail /></PageWrapper></PrivateRoute>} />
                <Route path="/rules" element={<PrivateRoute><AdminRoute><PageWrapper><Rules /></PageWrapper></AdminRoute></PrivateRoute>} />
                <Route path="/agents/:id" element={<PrivateRoute><PageWrapper><AgentDetail /></PageWrapper></PrivateRoute>} />
                <Route path="/devices/board-status/:id" element={<PrivateRoute><PageWrapper><BoardStatus /></PageWrapper></PrivateRoute>} />
                <Route path="/sites/:id" element={<PrivateRoute><PageWrapper><SiteDetail /></PageWrapper></PrivateRoute>} />
                <Route path="/traffic/sessions/:id" element={<PrivateRoute><PageWrapper><TrafficSessionDetail /></PageWrapper></PrivateRoute>} />
                <Route path="/attack-sim/runs/:id" element={<PrivateRoute><PageWrapper><AttackRunDetail /></PageWrapper></PrivateRoute>} />

                {/* Admin-only routes */}
                <Route path="/admin" element={<PrivateRoute><AdminRoute><PageWrapper><SuperAdmin /></PageWrapper></AdminRoute></PrivateRoute>} />
                <Route path="/super-admin" element={<PrivateRoute><AdminRoute><PageWrapper><AdminUsers /></PageWrapper></AdminRoute></PrivateRoute>} />
            </Routes>
        </AnimatePresence>
    );
};

const Layout = ({ children }: { children: React.ReactNode }) => {
    const location = useLocation();

    // Standalone pages that manage their own layout/theme
    const isStandalone =
        location.pathname === '/' ||
        location.pathname === '/login' ||
        location.pathname === '/privacy' ||
        location.pathname === '/terms' ||
        location.pathname === '/promo' ||
        location.pathname === '/promo-film';

    if (isStandalone) {
        return <>{children}</>;
    }

    return (
        <div className="flex h-screen bg-background text-foreground font-sans overflow-hidden">
            <Sidebar />
            <main className="flex-1 flex flex-col h-full overflow-hidden relative">
                <Header />
                <div className="flex-1 overflow-y-auto scrollbar-hide">
                    {children}
                </div>
            </main>
        </div>
    );
};

const App = () => {
    return (
        <ThemeProvider defaultTheme="light" storageKey="aetherguard-theme-v2">
            <LiveModeProvider>
                <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
                    <DemoProvider>
                        <LanguageProvider>
                            <WebSocketProvider>
                                <AttackStatusProvider>
                                    <Layout>
                                        <AnimatedRoutes />
                                    </Layout>
                                </AttackStatusProvider>
                            </WebSocketProvider>
                        </LanguageProvider>
                    </DemoProvider>
                </BrowserRouter>
            </LiveModeProvider>
        </ThemeProvider>
    );
};

export default App;

﻿import { useEffect, useState } from 'react';
import {
    Brain, Plus, Trash2, TestTube,
    Server, Laptop, Globe, Check, X, Loader2,
    ChevronDown, ChevronUp, AlertCircle
} from 'lucide-react';
import {
    fetchAIEndpoints,
    createAIEndpoint,
    updateAIEndpoint,
    deleteAIEndpoint,
    testAIEndpoint,
    verifyPlatformAI
} from '../services/api';
import type { PlatformAIProofError } from '../services/api';
import { motion, Variants } from 'framer-motion';

type EndpointType = 'ollama' | 'openai' | 'custom';
type EndpointPurpose = 'hot_path' | 'deep_analysis';

interface AIEndpoint {
    id: string;
    name: string;
    url: string;
    modelName: string;
    apiKey: string;
    enabled: boolean;
    priority: number;
    timeout: number;
    type: EndpointType;
    purpose?: EndpointPurpose;
    lastTest?: {
        success: boolean;
        latency: number;
        timestamp: string;
    };
}

interface AddEndpointFormData {
    name: string;
    url: string;
    modelName: string;
    apiKey: string;
    type: EndpointType;
    purpose: EndpointPurpose;
    priority: number;
}

const BUILT_IN_MODEL_OPTIONS = [
    { label: 'Tencent HY 2.0 Instruct', value: 'hunyuan-2.0-instruct' },
    { label: 'Tencent HY 2.0 Think', value: 'hunyuan-2.0-thinking' },
    { label: 'MiniMax-M2.5', value: 'minimax-m2.5' },
    { label: 'Kimi-K2.5', value: 'kimi-k2.5' },
    { label: 'GLM-5', value: 'glm-5' },
    { label: 'Hunyuan-T1', value: 'hunyuan-t1' },
    { label: 'Hunyuan-TurboS', value: 'hunyuan-turbos' }
];

const staggerContainer: Variants = {
    hidden: { opacity: 0 },
    visible: {
        opacity: 1,
        transition: {
            staggerChildren: 0.1
        }
    }
};

const itemVariant: Variants = {
    hidden: { opacity: 0, y: 15 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.3 } }
};

const AIEndpointSettings = ({ onChanged }: { onChanged?: () => void }) => {
    const [endpoints, setEndpoints] = useState<AIEndpoint[]>([]);
    const [loading, setLoading] = useState(true);
    const [showAddForm, setShowAddForm] = useState(false);
    const [testingId, setTestingId] = useState<string | null>(null);
    const [verifyingPlatform, setVerifyingPlatform] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [platformProof, setPlatformProof] = useState<{
        success: boolean;
        content: string;
        model: string;
        latency: number;
        route?: string;
        provider?: string;
        upstreamPath?: string;
        requestId?: string;
    } | null>(null);
    const [platformProofError, setPlatformProofError] = useState<{
        message: string;
        provider?: string;
        upstreamStatus?: number;
        upstreamPath?: string;
        requestId?: string;
    } | null>(null);

    const [formData, setFormData] = useState<AddEndpointFormData>({
        name: '',
        url: '',
        modelName: '',
        apiKey: '',
        type: 'ollama',
        purpose: 'deep_analysis',
        priority: 10,
    });

    const loadEndpoints = async () => {
        setLoading(true);
        setError(null);
        try {
            const rows = await fetchAIEndpoints();
            setEndpoints(rows || []);
        } catch (e: any) {
            setError(e.message || 'FG-AI-ENDPOINTS-LIST');
            setEndpoints([]);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadEndpoints();
    }, []);

    const handleAddEndpoint = async () => {
        if (!formData.url) return;
        setError(null);
        try {
            await createAIEndpoint({
                name: formData.name,
                url: formData.url,
                modelName: formData.modelName,
                apiKey: formData.apiKey,
                type: formData.type,
                purpose: formData.purpose,
                priority: formData.priority
            });
            setShowAddForm(false);
            setFormData({
                name: '',
                url: '',
                modelName: '',
                apiKey: '',
                type: 'ollama',
                purpose: 'deep_analysis',
                priority: 10,
            });
            await loadEndpoints();
            onChanged?.();
        } catch (e: any) {
            setError(e.message || 'FG-AI-ENDPOINTS-CREATE');
        }
    };

    const handleDeleteEndpoint = async (id: string) => {
        setError(null);
        try {
            await deleteAIEndpoint(id);
            await loadEndpoints();
            onChanged?.();
        } catch (e: any) {
            setError(e.message || 'FG-AI-ENDPOINTS-DELETE');
        }
    };

    const handleToggleEndpoint = async (id: string, enabled: boolean) => {
        setError(null);
        try {
            await updateAIEndpoint(id, { enabled: !enabled });
            await loadEndpoints();
            onChanged?.();
        } catch (e: any) {
            setError(e.message || 'FG-AI-ENDPOINTS-UPDATE');
        }
    };

    const handleTestEndpoint = async (id: string) => {
        setTestingId(id);
        setError(null);
        try {
            await testAIEndpoint(id);
            await loadEndpoints();
        } catch (e: any) {
            setError(e.message || 'FG-AI-ENDPOINTS-TEST');
        } finally {
            setTestingId(null);
        }
    };

    const handleVerifyPlatformAI = async () => {
        setVerifyingPlatform(true);
        setError(null);
        setPlatformProofError(null);
        try {
            const result = await verifyPlatformAI();
            setPlatformProof(result);
        } catch (e: any) {
            const typedError = e as PlatformAIProofError;
            setPlatformProof(null);
            setPlatformProofError({
                message: typedError.message || 'FG-AI-PLATFORM-VERIFY',
                provider: typedError.diagnostics?.provider,
                upstreamStatus: typedError.diagnostics?.upstreamStatus,
                upstreamPath: typedError.diagnostics?.upstreamPath,
                requestId: typedError.diagnostics?.requestId
            });
        } finally {
            setVerifyingPlatform(false);
        }
    };

    const handlePriorityChange = async (id: string, direction: 'up' | 'down') => {
        const sorted = [...endpoints].sort((a, b) => a.priority - b.priority);
        const idx = sorted.findIndex(ep => ep.id === id);
        if (idx < 0) return;

        const current = sorted[idx];
        const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
        if (targetIdx < 0 || targetIdx >= sorted.length) return;

        const target = sorted[targetIdx];
        setError(null);
        try {
            await Promise.all([
                updateAIEndpoint(current.id, { priority: target.priority }),
                updateAIEndpoint(target.id, { priority: current.priority })
            ]);
            await loadEndpoints();
            onChanged?.();
        } catch (e: any) {
            setError(e.message || 'FG-AI-ENDPOINTS-PRIORITY');
        }
    };

    const getTypeIcon = (type: string) => {
        switch (type) {
            case 'ollama': return <Laptop size={16} className="text-emerald-500" />;
            case 'openai': return <Globe size={16} className="text-blue-500" />;
            default: return <Server size={16} className="text-orange-500" />;
        }
    };

    const sortedEndpoints = [...endpoints].sort((a, b) => a.priority - b.priority);

    return (
        <div className="bg-card border border-border rounded-xl p-5 shadow-sm">
            <div className="flex justify-between items-center mb-5">
                <div className="flex items-center gap-2">
                    <Brain size={18} className="text-primary" />
                    <h3 className="font-semibold text-foreground">AI Endpoint Settings</h3>
                </div>
                <button
                    onClick={() => setShowAddForm(!showAddForm)}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-all"
                >
                    <Plus size={14} /> Add Endpoint
                </button>
            </div>

            {error && (
                <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4 text-xs text-red-300">
                    {error}
                </div>
            )}

            <div className="bg-blue-500/10 border border-blue-500/20 rounded-lg p-3 mb-4 flex items-start gap-2">
                <AlertCircle size={16} className="text-blue-500 mt-0.5" />
                <div className="text-xs text-blue-700 dark:text-blue-300">
                    Endpoints are used by priority order. If one fails, the next enabled endpoint is used.
                </div>
            </div>

            <div className="border border-border rounded-lg p-4 mb-4 bg-muted/20">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                    <div>
                        <div className="text-sm font-medium text-foreground">Built-in Platform AI Proof</div>
                        <div className="text-xs text-muted-foreground mt-1">
                            Runs one deterministic cloud-model check and expects <span className="font-mono">AETHERGUARD_REMOTE_AI_OK</span>.
                        </div>
                    </div>
                    <button
                        onClick={handleVerifyPlatformAI}
                        disabled={verifyingPlatform}
                        className="flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-medium bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 disabled:opacity-60 disabled:cursor-not-allowed transition-all"
                    >
                        {verifyingPlatform ? <Loader2 size={14} className="animate-spin" /> : <TestTube size={14} />}
                        Verify Platform AI
                    </button>
                </div>

                {platformProof && (
                    <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="mt-3 rounded-lg border border-emerald-500/20 bg-emerald-500/10 p-3">
                        <div className="flex items-center gap-2 text-xs text-emerald-700 dark:text-emerald-300">
                            <Check size={12} />
                            Platform route returned a live response.
                        </div>
                        <div className="mt-2 text-xs text-muted-foreground space-y-1">
                            <div>Model: <span className="text-foreground">{platformProof.model}</span></div>
                            <div>Latency: <span className="text-foreground">{platformProof.latency}ms</span></div>
                            {platformProof.route && <div>Route: <span className="text-foreground">{platformProof.route}</span></div>}
                            {platformProof.provider && <div>Provider: <span className="text-foreground">{platformProof.provider}</span></div>}
                            {platformProof.upstreamPath && <div>Path: <span className="font-mono text-foreground">{platformProof.upstreamPath}</span></div>}
                            {platformProof.requestId && <div>Request ID: <span className="font-mono text-foreground">{platformProof.requestId}</span></div>}
                        </div>
                        <div className="mt-3 rounded-md border border-border bg-background/80 px-3 py-2 text-xs font-mono text-foreground break-all">
                            {platformProof.content}
                        </div>
                    </motion.div>
                )}

                {platformProofError && (
                    <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="mt-3 rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-xs text-rose-700 dark:text-rose-300">
                        <div className="font-medium">{platformProofError.message}</div>
                        <div className="mt-2 space-y-1 text-rose-700/80 dark:text-rose-300/80">
                            {platformProofError.provider && <div>Provider: {platformProofError.provider}</div>}
                            {platformProofError.upstreamStatus && <div>Status: {platformProofError.upstreamStatus}</div>}
                            {platformProofError.upstreamPath && <div>Path: <span className="font-mono">{platformProofError.upstreamPath}</span></div>}
                            {platformProofError.requestId && <div>Request ID: <span className="font-mono">{platformProofError.requestId}</span></div>}
                        </div>
                    </motion.div>
                )}
            </div>

            {showAddForm && (
                <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} className="bg-muted/30 border border-border rounded-lg p-4 mb-4 overflow-hidden">
                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div>
                            <label className="block text-xs text-muted-foreground mb-1">Name</label>
                            <input
                                type="text"
                                value={formData.name}
                                onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}
                                placeholder="Production model endpoint"
                                className="w-full px-3 py-2 text-sm bg-background border border-border rounded-lg focus:border-primary focus:outline-none"
                            />
                        </div>
                        <div>
                            <label className="block text-xs text-muted-foreground mb-1">Type</label>
                            <select
                                value={formData.type}
                                onChange={e => setFormData(prev => ({ ...prev, type: e.target.value as EndpointType }))}
                                className="w-full px-3 py-2 text-sm bg-background border border-border rounded-lg focus:border-primary focus:outline-none"
                            >
                                <option value="ollama">Ollama</option>
                                <option value="openai">OpenAI Compatible</option>
                                <option value="custom">Custom</option>
                            </select>
                        </div>
                    </div>

                    <div className="mb-4">
                        <label className="block text-xs text-muted-foreground mb-1">Purpose</label>
                        <select
                            value={formData.purpose}
                            onChange={e => setFormData(prev => ({ ...prev, purpose: e.target.value as EndpointPurpose }))}
                            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-lg focus:border-primary focus:outline-none"
                        >
                            <option value="deep_analysis">deep_analysis</option>
                            <option value="hot_path">hot_path</option>
                        </select>
                    </div>

                    <div className="mb-4">
                        <label className="block text-xs text-muted-foreground mb-1">Endpoint URL *</label>
                        <input
                            type="text"
                            value={formData.url}
                            onChange={e => setFormData(prev => ({ ...prev, url: e.target.value }))}
                            placeholder="http://your-server:5000/api/analyze"
                            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-lg focus:border-primary focus:outline-none"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div>
                            <label className="block text-xs text-muted-foreground mb-1">Model</label>
                            <input
                                type="text"
                                list="built-in-model-options"
                                value={formData.modelName}
                                onChange={e => setFormData(prev => ({ ...prev, modelName: e.target.value }))}
                                placeholder="glm-5 / hunyuan-turbos / kimi-k2.5"
                                className="w-full px-3 py-2 text-sm bg-background border border-border rounded-lg focus:border-primary focus:outline-none"
                            />
                            <datalist id="built-in-model-options">
                                {BUILT_IN_MODEL_OPTIONS.map((model) => (
                                    <option key={model.value} value={model.value}>
                                        {model.label}
                                    </option>
                                ))}
                            </datalist>
                        </div>
                        <div>
                            <label className="block text-xs text-muted-foreground mb-1">API Key</label>
                            <input
                                type="password"
                                value={formData.apiKey}
                                onChange={e => setFormData(prev => ({ ...prev, apiKey: e.target.value }))}
                                placeholder="sk-..."
                                className="w-full px-3 py-2 text-sm bg-background border border-border rounded-lg focus:border-primary focus:outline-none"
                            />
                        </div>
                    </div>

                    <div className="flex justify-end gap-2">
                        <button
                            onClick={() => setShowAddForm(false)}
                            className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleAddEndpoint}
                            disabled={!formData.url}
                            className="px-4 py-2 text-sm font-medium bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                        >
                            Add
                        </button>
                    </div>
                </motion.div>
            )}

            {loading ? (
                <div className="text-center py-8 text-muted-foreground">
                    <Loader2 size={24} className="mx-auto mb-2 animate-spin" />
                    Loading...
                </div>
            ) : sortedEndpoints.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                    No configured AI endpoints.
                </div>
            ) : (
                <motion.div variants={staggerContainer} initial="hidden" animate="visible" className="space-y-3">
                    {sortedEndpoints.map((endpoint, index) => (
                        <motion.div
                            variants={itemVariant}
                            whileHover={{ scale: 1.01 }}
                            key={endpoint.id}
                            className={`border rounded-lg p-4 transition-all ${endpoint.enabled
                                ? 'border-border bg-card hover:border-primary/40'
                                : 'border-border/50 bg-muted/20 opacity-60'
                                }`}
                        >
                            <div className="flex items-start justify-between">
                                <div className="flex items-start gap-3">
                                    <div className="flex flex-col items-center">
                                        <button
                                            onClick={() => handlePriorityChange(endpoint.id, 'up')}
                                            disabled={index === 0}
                                            className="p-0.5 text-muted-foreground hover:text-foreground disabled:opacity-30 transition-colors"
                                        >
                                            <ChevronUp size={14} />
                                        </button>
                                        <span className="text-xs font-bold text-muted-foreground">{index + 1}</span>
                                        <button
                                            onClick={() => handlePriorityChange(endpoint.id, 'down')}
                                            disabled={index === sortedEndpoints.length - 1}
                                            className="p-0.5 text-muted-foreground hover:text-foreground disabled:opacity-30 transition-colors"
                                        >
                                            <ChevronDown size={14} />
                                        </button>
                                    </div>

                                    <div>
                                        <div className="flex items-center gap-2 mb-1">
                                            {getTypeIcon(endpoint.type)}
                                            <span className="font-medium text-foreground">{endpoint.name}</span>
                                            <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] uppercase tracking-wide text-muted-foreground">
                                                {endpoint.purpose || 'deep_analysis'}
                                            </span>
                                        </div>
                                        <div className="text-xs text-muted-foreground mb-1">{endpoint.url}</div>
                                        <div className="flex items-center gap-3 text-xs text-muted-foreground">
                                            <span>Model: {endpoint.modelName}</span>
                                            {endpoint.lastTest && (
                                                <span className={`flex items-center gap-1 ${endpoint.lastTest.success ? 'text-emerald-500' : 'text-red-500'}`}>
                                                    {endpoint.lastTest.success ? <Check size={12} /> : <X size={12} />}
                                                    {endpoint.lastTest.latency}ms
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => handleTestEndpoint(endpoint.id)}
                                        disabled={testingId === endpoint.id}
                                        className="p-2 text-muted-foreground hover:text-foreground hover:bg-muted rounded-lg transition-all"
                                        title="Test"
                                    >
                                        {testingId === endpoint.id ? (
                                            <Loader2 size={16} className="animate-spin" />
                                        ) : (
                                            <TestTube size={16} />
                                        )}
                                    </button>
                                    <button
                                        onClick={() => handleToggleEndpoint(endpoint.id, endpoint.enabled)}
                                        className={`p-2 rounded-lg transition-all ${endpoint.enabled
                                            ? 'text-emerald-500 hover:bg-emerald-500/10'
                                            : 'text-muted-foreground hover:bg-muted'
                                            }`}
                                        title={endpoint.enabled ? 'Disable' : 'Enable'}
                                    >
                                        {endpoint.enabled ? <Check size={16} /> : <X size={16} />}
                                    </button>
                                    <button
                                        onClick={() => handleDeleteEndpoint(endpoint.id)}
                                        className="p-2 text-red-500 hover:bg-red-500/10 rounded-lg transition-all"
                                        title="Delete"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </div>
                        </motion.div>
                    ))}
                </motion.div>
            )}
        </div>
    );
};

export default AIEndpointSettings;

import { useEffect, useState, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Brain, Lock, Sparkles, Crown, Loader2, AlertTriangle } from 'lucide-react';
import { fetchAvailableModels, AIModelInfo } from '../services/api';

const getCategoryIcon = (model: AIModelInfo) => {
    if (model.category === 'partner') {
        return <Sparkles className="h-3.5 w-3.5" />;
    }
    return <Brain className="h-3.5 w-3.5" />;
};

const getCategoryLabel = (model: AIModelInfo) => {
    if (model.category === 'partner') {
        return 'Partner';
    }
    return 'Tencent';
};

const getTierBadge = (tier: string) => {
    switch (tier) {
        case 'starter':
            return <span className="rounded-full border border-border bg-muted px-1.5 py-0.5 text-[9px] font-bold text-muted-foreground">STARTER</span>;
        case 'pro':
            return <span className="rounded-full border border-blue-500/20 bg-blue-500/10 px-1.5 py-0.5 text-[9px] font-bold text-blue-600 dark:text-blue-400">PRO</span>;
        case 'ultra':
            return <span className="rounded-full border border-rose-500/20 bg-rose-500/10 px-1.5 py-0.5 text-[9px] font-bold text-rose-600 dark:text-rose-400">ULTRA</span>;
        default:
            return null;
    }
};

const ModelSelector = () => {
    const [models, setModels] = useState<AIModelInfo[]>([]);
    const [plan, setPlan] = useState<string>('starter');
    const [canCustomize, setCanCustomize] = useState(false);
    const [selectedModelId, setSelectedModelId] = useState<string>('');
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const loadModels = useCallback(async () => {
        try {
            setLoading(true);
            setError(null);
            const data = await fetchAvailableModels();
            setModels(data.models);
            setPlan(data.plan);
            setCanCustomize(data.canCustomize);
            setSelectedModelId(data.defaultModelId);
        } catch (err: any) {
            setError(err.message || 'Failed to load model catalog');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        loadModels();
    }, [loadModels]);

    if (loading) {
        return (
            <div className="flex items-center justify-center gap-3 rounded-2xl border border-border bg-card p-8">
                <Loader2 className="h-5 w-5 animate-spin text-primary" />
                <span className="text-sm text-muted-foreground">Loading AI model configuration...</span>
            </div>
        );
    }

    if (error) {
        return (
            <div className="rounded-2xl border border-rose-500/20 bg-card p-6">
                <div className="flex items-center gap-2 text-rose-600 dark:text-rose-400">
                    <AlertTriangle className="h-5 w-5" />
                    <span>{error}</span>
                </div>
                <button onClick={loadModels} className="mt-3 rounded-lg border border-border bg-muted px-4 py-1.5 text-sm text-foreground transition-colors hover:bg-muted/80">
                    Retry
                </button>
            </div>
        );
    }

    return (
        <div className="overflow-hidden rounded-2xl border border-border bg-card">
            <div className="flex items-center justify-between gap-4 border-b border-border bg-muted/20 px-6 py-4">
                <div className="flex items-center gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-xl border border-border bg-card text-primary">
                        <Brain className="h-5 w-5" />
                    </div>
                    <div>
                        <h3 className="text-lg font-semibold text-foreground">AI Model Center</h3>
                        <p className="text-xs text-muted-foreground">
                            Current plan: {getTierBadge(plan)}
                            <span className="ml-2">
                                {models.filter((model) => model.available).length}/{models.length} models available
                            </span>
                        </p>
                    </div>
                </div>
                {canCustomize && (
                    <span className="flex items-center gap-1 rounded-full border border-amber-500/20 bg-amber-500/10 px-3 py-1 text-xs font-medium text-amber-600 dark:text-amber-400">
                        <Crown className="h-3 w-3" />
                        Custom model policy enabled
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 gap-3 p-6 sm:grid-cols-2 lg:grid-cols-3">
                {models.map((model, idx) => {
                    const isSelected = model.id === selectedModelId;
                    const isLocked = !model.available;

                    return (
                        <motion.button
                            key={model.id}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: idx * 0.05 }}
                            whileHover={isLocked ? {} : { y: -4, scale: 1.01, transition: { duration: 0.2 } }}
                            onClick={() => !isLocked && setSelectedModelId(model.id)}
                            disabled={isLocked}
                            className={`relative rounded-xl border p-4 text-left transition-colors ${isLocked
                                    ? 'cursor-not-allowed border-border bg-muted/15 opacity-60'
                                    : isSelected
                                        ? 'border-primary/25 bg-primary/5'
                                        : 'border-border bg-card hover:bg-muted/20 hover:shadow-lg hover:border-primary/30'
                                }`}
                        >
                            {isSelected && <div className="absolute right-3 top-3 h-2.5 w-2.5 rounded-full bg-primary" />}

                            {isLocked && (
                                <div className="absolute right-3 top-3 flex h-6 w-6 items-center justify-center rounded-full border border-border bg-muted">
                                    <Lock className="h-3 w-3 text-muted-foreground" />
                                </div>
                            )}

                            <div className="mb-1.5 flex items-center gap-2">
                                <span className="text-sm font-semibold text-foreground">{model.name}</span>
                            </div>

                            <p className="mb-3 line-clamp-2 text-xs text-muted-foreground">{model.description}</p>

                            <div className="flex flex-wrap items-center gap-1.5">
                                <span className="inline-flex items-center gap-1 rounded-full border border-border bg-muted/40 px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
                                    {getCategoryIcon(model)}
                                    {getCategoryLabel(model)}
                                </span>
                                {getTierBadge(model.minTier)}
                                {isLocked && <span className="ml-auto text-[10px] text-amber-600 dark:text-amber-400">Upgrade required</span>}
                            </div>
                        </motion.button>
                    );
                })}
            </div>
        </div>
    );
};

