type EndpointOption = { id: string; name: string; modelName: string; purpose?: 'hot_path' | 'deep_analysis' };

const targets: DeploymentTarget[] = ['nginx', 'apache', 'caddy', 'docker_compose', 'binary_agent', 'k8s_daemonset'];
