type StructuredDataViewProps = {
    value: unknown;
    emptyLabel?: string;
    depth?: number;
};

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
    typeof value === 'object' && value !== null && !Array.isArray(value);

const humanizeKey = (key: string) =>
    key
        .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
        .replace(/[_-]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/^./, (char) => char.toUpperCase());

const formatPrimitive = (value: string | number | boolean) => {
    if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
    }

    if (typeof value === 'number') {
        return Number.isFinite(value) ? new Intl.NumberFormat('zh-CN').format(value) : String(value);
    }

    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime()) && /^\d{4}-\d{2}-\d{2}T/.test(value)) {
        return parsed.toLocaleString();
    }

    return value;
};

const StructuredDataView = ({ value, emptyLabel = 'No data available', depth = 0 }: StructuredDataViewProps) => {
    if (value === null || value === undefined || value === '') {
        return <span className="text-sm text-muted-foreground">{emptyLabel}</span>;
    }

    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
        return <span className="text-sm text-foreground">{formatPrimitive(value)}</span>;
    }

    if (Array.isArray(value)) {
        if (value.length === 0) {
            return <span className="text-sm text-muted-foreground">{emptyLabel}</span>;
        }

        const primitiveItems = value.every(
            (item) => item === null || item === undefined || ['string', 'number', 'boolean'].includes(typeof item)
        );

        if (primitiveItems) {
            return (
                <div className="flex flex-wrap gap-2">
                    {value.map((item, index) => (
                        <span
                            key={`${String(item)}-${index}`}
                            className="rounded-md border border-border bg-muted/20 px-2 py-1 text-xs text-foreground"
                        >
                            {item === null || item === undefined || item === '' ? emptyLabel : formatPrimitive(item as string | number | boolean)}
                        </span>
                    ))}
                </div>
            );
        }

        return (
            <div className="space-y-2">
                {value.map((item, index) => (
                    <div key={index} className="rounded-lg border border-border bg-muted/10 p-3">
                        <StructuredDataView value={item} emptyLabel={emptyLabel} depth={depth + 1} />
                    </div>
                ))}
            </div>
        );
    }

    if (!isPlainObject(value)) {
        return <span className="text-sm text-foreground">{String(value)}</span>;
    }

    const entries = Object.entries(value).filter(([, entryValue]) => entryValue !== undefined);
    if (entries.length === 0) {
        return <span className="text-sm text-muted-foreground">{emptyLabel}</span>;
    }

    return (
        <div className={depth === 0 ? 'grid gap-2 md:grid-cols-2' : 'space-y-2'}>
            {entries.map(([key, entryValue]) => (
                <div key={key} className="rounded-lg border border-border bg-muted/10 p-3">
                    <div className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">
                        {humanizeKey(key)}
                    </div>
                    <div className="mt-2">
                        <StructuredDataView value={entryValue} emptyLabel={emptyLabel} depth={depth + 1} />
                    </div>
                </div>
            ))}
        </div>
    );
};

export default StructuredDataView;

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useWebSocket } from './WebSocketContext';

interface AttackStatus {
    isRunning: boolean;
    total: number;
    completed: number;
    blocked: number;
    allowed: number;
    currentAttack: string | null;
    startTime: Date | null;
}

interface AttackStatusContextType {
    status: AttackStatus;
}

const AttackStatusContext = createContext<AttackStatusContextType | undefined>(undefined);

export const AttackStatusProvider = ({ children }: { children: ReactNode }) => {
    const { subscribe } = useWebSocket();
    const [status, setStatus] = useState<AttackStatus>({
        isRunning: false,
        total: 0,
        completed: 0,
        blocked: 0,
        allowed: 0,
        currentAttack: null,
        startTime: null
    });

    useEffect(() => {
        const unsubscribe = subscribe('*', (data: any) => {
            const { event, ...eventData } = data;

            switch (event) {
                case 'attack:simulation:start':
                    setStatus({
                        isRunning: true,
                        total: eventData.totalAttacks,
                        completed: 0,
                        blocked: 0,
                        allowed: 0,
                        currentAttack: null,
                        startTime: new Date()
                    });
                    break;

                case 'attack:start':
                    setStatus(prev => ({
                        ...prev,
                        currentAttack: eventData.attackName
                    }));
                    break;

                case 'attack:result':
                    setStatus(prev => ({
                        ...prev,
                        completed: prev.completed + 1,
                        blocked: prev.blocked + (eventData.blocked ? 1 : 0),
                        allowed: prev.allowed + (eventData.blocked ? 0 : 1)
                    }));
                    break;

                case 'attack:simulation:complete':
                    setStatus(prev => ({
                        ...prev,
                        isRunning: false,
                        currentAttack: null
                    }));
                    break;
            }
        });

        return () => {
            unsubscribe();
        };
    }, [subscribe]);

    return (
        <AttackStatusContext.Provider value={{ status }}>
            {children}
        </AttackStatusContext.Provider>
    );
};

export const useAttackStatus = () => {
    const context = useContext(AttackStatusContext);
    if (!context) {
        throw new Error('useAttackStatus must be used within an AttackStatusProvider');
    }
    return context;
};

import { createContext, useState, useContext, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import i18n from '../i18n';

type Language = 'en' | 'zh';

interface LanguageContextType {
    language: Language;
    toggleLanguage: () => void;
    t: (key: string) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider = ({ children }: { children: ReactNode }) => {
    const { t } = useTranslation();
    const [language, setLanguage] = useState<Language>((i18n.language as Language) || 'en');

    const toggleLanguage = () => {
        const newLang = language === 'en' ? 'zh' : 'en';
        setLanguage(newLang);
        i18n.changeLanguage(newLang);
    };

    return (
        <LanguageContext.Provider value={{ language, toggleLanguage, t: t as any }}>
            {children}
        </LanguageContext.Provider>
    );
};

export const useLanguage = () => {
    const context = useContext(LanguageContext);
    if (!context) {
        throw new Error('useLanguage must be used within a LanguageProvider');
    }
    return context;
};

