                                                <div className="min-w-0">
                                                    <div className={`truncate text-sm font-semibold ${category.color}`}>{category.name}</div>
                                                    <div className="text-xs text-muted-foreground">{categoryAttacks.length} 项攻击</div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                {selectedInCategory > 0 && (
                                                    <span className="rounded-full border border-border bg-card px-2 py-0.5 text-[10px] font-semibold text-foreground">
                                                        {selectedInCategory}
                                                    </span>
                                                )}
                                                {isExpanded ? <ChevronDown className="h-4 w-4 text-muted-foreground" /> : <ChevronRight className="h-4 w-4 text-muted-foreground" />}
                                            </div>
                                        </button>
                                        <AnimatePresence initial={false}>
                                            {isExpanded && (
                                                <motion.div
                                                    initial={{ height: 0, opacity: 0 }}
                                                    animate={{ height: 'auto', opacity: 1 }}
                                                    exit={{ height: 0, opacity: 0 }}
                                                    transition={{ duration: 0.2 }}
                                                    className="overflow-hidden border-t border-border bg-muted/15"
                                                >
                                                    <div className="space-y-2 p-3">
                                                        {categoryAttacks.map((attack) => {
                                                            const isSelected = selectedAttacks.includes(attack.id);
                                                            const severityStyle = getSeverityStyle(attack.severity);

                                                            return (
                                                                <button
                                                                    key={attack.id}
                                                                    onClick={() => toggleAttack(attack.id)}
                                                                    className={`w-full rounded-xl border p-3 text-left transition-colors ${
                                                                        isSelected
                                                                            ? `${severityStyle.bg} ${severityStyle.border}`
                                                                            : 'border-border bg-card hover:bg-muted/20'
                                                                    }`}
                                                                >
                                                                    <div className="flex items-start justify-between gap-3">
                                                                        <div className="min-w-0">
                                                                            <p className="truncate text-sm font-medium text-foreground">{attack.name}</p>
                                                                            <p className="mt-1 truncate font-mono text-[11px] text-muted-foreground">{attack.description}</p>
                                                                        </div>
                                                                        <span className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase ${severityStyle.bg} ${severityStyle.border} ${severityStyle.text}`}>
                                                                            {getSeverityName(attack.severity)}
                                                                        </span>
                                                                    </div>
                                                                </button>
                                                            );
                                                        })}
                                                    </div>
                                                </motion.div>
                                            )}
                                        </AnimatePresence>
                                    </div>
                                );
                            })}
                        </div>
                    </ConsolePanel>
                </motion.div>

                <motion.div variants={itemVariants} className="space-y-6 lg:col-span-8 xl:col-span-9">
                    <ConsolePanel
                        title={t('attackSimulator.liveAttackAnalysis')}
                        subtitle={attackProgress.length > 0 ? `${attackProgress.filter((item) => item.status === 'complete').length}/${attackProgress.length} ${t('attackSimulator.completed')}` : undefined}
                        icon={Users}
                        iconTone="primary"
                    >
                        <div className="max-h-[440px] space-y-3 overflow-y-auto pr-1">
                            {attackProgress.length > 0 ? (
                                attackProgress.map((progress, index) => {
                                    const isBlocked = progress.result?.blocked;
                                    const statusClasses =
                                        progress.status === 'complete'
                                            ? isBlocked
                                                ? 'border-emerald-500/20 bg-emerald-500/10'
                                                : 'border-rose-500/20 bg-rose-500/10'
                                            : progress.status === 'analyzing'
                                              ? 'border-amber-500/20 bg-amber-500/10'
                                              : 'border-border bg-muted/10';

                                    return (
                                        <motion.div
                                            key={progress.attackId}
                                            initial={{ opacity: 0, y: 10 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            transition={{ delay: index * 0.05 }}
                                            className={`rounded-xl border p-4 ${statusClasses}`}
                                        >
                                            <div className="flex items-start gap-4">
                                                <div
                                                    className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${
                                                        progress.status === 'complete'
                                                            ? isBlocked
                                                                ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400'
                                                                : 'bg-rose-500/15 text-rose-600 dark:text-rose-400'
                                                            : progress.status === 'analyzing'
                                                              ? 'bg-amber-500/15 text-amber-600 dark:text-amber-400'
                                                              : 'bg-muted text-muted-foreground'
                                                    }`}
                                                >
                                                    {progress.status === 'complete' ? (
                                                        isBlocked ? <CheckCircle className="h-5 w-5" /> : <XCircle className="h-5 w-5" />
                                                    ) : progress.status === 'analyzing' ? (
                                                        <RefreshCw className="h-5 w-5 animate-spin" />
                                                    ) : (
                                                        <Clock className="h-5 w-5" />
                                                    )}
                                                </div>
                                                <div className="min-w-0 flex-1">
                                                    <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
                                                        <div className="min-w-0">
                                                            <p className="truncate text-sm font-semibold text-foreground">{progress.attackName}</p>
                                                            <p className="text-xs text-muted-foreground">{getCategoryName(progress.category)}</p>
                                                        </div>
                                                        <div className="text-left sm:text-right">
                                                            {progress.status === 'complete' && progress.result && (
                                                                <>
                                                                    <p className={`text-sm font-semibold ${isBlocked ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                                                        {isBlocked ? t('attackSimulator.blocked') : t('attackSimulator.allowed')}
                                                                    </p>
                                                                    <p className="text-xs text-muted-foreground">{progress.result.responseTime}ms</p>
                                                                    {progress.result.aiAnalysis?.usedAI && (
                                                                        <p className="text-[11px] text-muted-foreground">
                                                                            AI {progress.result.aiAnalysis.route || 'unknown'} via {progress.result.aiAnalysis.provider || progress.result.aiAnalysis.engine || 'model-router'}
                                                                        </p>
                                                                    )}
                                                                </>
                                                            )}
                                                            {progress.status === 'analyzing' && <p className="text-sm font-medium text-amber-600 dark:text-amber-400">{t('attackSimulator.analyzing')}</p>}
                                                            {progress.status === 'pending' && <p className="text-sm text-muted-foreground">{t('attackSimulator.pending')}</p>}
                                                        </div>
                                                    </div>

                                                    {progress.analyses.length > 0 && (
                                                        <div className="mt-3 space-y-2">
                                                            {progress.analyses.map((analysis, analysisIndex) => {
                                                                const agentStyle = getAgentStyle(analysis.agent);
                                                                return (
                                                                    <motion.div
                                                                        key={`${progress.attackId}-${analysisIndex}`}
                                                                        initial={{ opacity: 0, x: -10 }}
                                                                        animate={{ opacity: 1, x: 0 }}
                                                                        transition={{ delay: analysisIndex * 0.05 }}
                                                                        className={`rounded-lg border px-3 py-2 ${agentStyle.bg} ${agentStyle.border}`}
                                                                    >
                                                                        <div className="flex items-start gap-3">
                                                                            <div className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full ${agentStyle.bg}`}>
                                                                                <Bot className={`h-3.5 w-3.5 ${agentStyle.color}`} />
                                                                            </div>
                                                                            <div className="min-w-0 flex-1">
                                                                                <div className={`text-xs font-semibold ${agentStyle.color}`}>{agentStyle.name}</div>
                                                                                <p className="mt-1 text-xs leading-5 text-foreground">{analysis.message}</p>
                                                                                {analysis.verdict && (
                                                                                    <div className="mt-2 rounded-md border border-border bg-card/80 px-2.5 py-2 text-xs">
                                                                                        <span className="font-medium text-foreground">{t('attackSimulator.decision')}: </span>
                                                                                        <span className={analysis.verdict === 'block' ? 'text-rose-600 dark:text-rose-400' : 'text-emerald-600 dark:text-emerald-400'}>
                                                                                            {analysis.verdict === 'block' ? t('attackSimulator.blocked') : t('attackSimulator.allowed')}
                                                                                        </span>
                                                                                        {analysis.confidence && <span className="text-muted-foreground"> ({(analysis.confidence * 100).toFixed(0)}%)</span>}
                                                                                    </div>
                                                                                )}
                                                                            </div>
                                                                        </div>
                                                                    </motion.div>
                                                                );
                                                            })}
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </motion.div>
                                    );
                                })
                            ) : (
                                <ConsoleEmptyState title={t('attackSimulator.selectAndRun')} description="选中攻击并执行后，这里会显示分析过程与判定结果。" />
                            )}
                        </div>
                    </ConsolePanel>

                    <ConsolePanel title={t('attackSimulator.terminal')} subtitle="执行日志流" icon={Terminal} iconTone="neutral">
                        <div className="rounded-xl border border-border bg-muted/20">
                            <div className="border-b border-border px-4 py-3 text-xs text-muted-foreground">终端输出</div>
                            <div ref={terminalRef} className="h-52 overflow-y-auto bg-background/80 px-4 py-4 font-mono text-sm">
                                {terminalLogs.length > 0 ? (
                                    <div className="space-y-2">
                                        {terminalLogs.map((log, index) => (
                                            <motion.div key={`${log}-${index}`} initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="leading-relaxed text-foreground">
                                                <span className="text-emerald-600 dark:text-emerald-400">$</span> {log}
                                            </motion.div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="flex items-center gap-2 text-muted-foreground">
                                        <span className="text-emerald-600 dark:text-emerald-400">$</span>
                                        {t('attackSimulator.waitingSimulation')}
                                    </div>
                                )}
                            </div>
                        </div>
                    </ConsolePanel>
                </motion.div>
            </div>

            <AnimatePresence>
                {report && (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -20 }}
                        className="grid grid-cols-1 gap-6 lg:grid-cols-12"
                    >
                        <div className="lg:col-span-4">
                            <ConsolePanel title={t('attackSimulator.results')} subtitle="最近一次演练汇总" icon={BarChart3} iconTone="primary">
                                <div className="grid grid-cols-3 gap-3">
                                    <div className="rounded-xl border border-border bg-muted/20 p-4 text-center">
                                        <p className="text-3xl font-bold tracking-tight text-foreground">{report.total}</p>
                                        <p className="mt-1 text-xs text-muted-foreground">{t('attackSimulator.total')}</p>
                                    </div>
                                    <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/10 p-4 text-center">
                                        <p className="text-3xl font-bold tracking-tight text-emerald-600 dark:text-emerald-400">{report.blocked}</p>
                                        <p className="mt-1 text-xs text-emerald-600/80 dark:text-emerald-400/80">{t('attackSimulator.blocked')}</p>
                                    </div>
                                    <div className="rounded-xl border border-rose-500/20 bg-rose-500/10 p-4 text-center">
                                        <p className="text-3xl font-bold tracking-tight text-rose-600 dark:text-rose-400">{report.allowed}</p>
                                        <p className="mt-1 text-xs text-rose-600/80 dark:text-rose-400/80">{t('attackSimulator.allowed')}</p>
                                    </div>
                                </div>

                                <div className="mt-6 space-y-3">
                                    <div className="flex items-center justify-between text-sm">
                                        <span className="text-muted-foreground">{t('attackSimulator.blockRate')}</span>
                                        <span className="font-medium text-foreground">{getBlockRate()}%</span>
                                    </div>
                                    <div className="h-2 overflow-hidden rounded-full bg-muted">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${getBlockRate()}%` }}
                                            transition={{ duration: 0.5 }}
                                            className="h-full rounded-full bg-emerald-500"
                                        />
                                    </div>
                                    {report.aiAnalysis && (
                                        <div className="rounded-xl border border-border bg-background/70 p-3 text-xs text-muted-foreground space-y-1">
                                            <div className="flex items-center justify-between">
                                                <span>AI-backed decisions</span>
                                                <span className="font-medium text-foreground">{report.aiAnalysis.aiBackedCount}/{report.total}</span>
                                            </div>
                                            <div className="flex items-center justify-between">
                                                <span>Cloud routes</span>
                                                <span className="font-medium text-foreground">{report.aiAnalysis.cloudCount}</span>
                                            </div>
                                            <div className="flex items-center justify-between">
                                                <span>Local routes</span>
                                                <span className="font-medium text-foreground">{report.aiAnalysis.localCount}</span>
                                            </div>
                                            {report.aiAnalysis.errorCount > 0 && (
                                                <div className="flex items-center justify-between text-rose-600 dark:text-rose-400">
                                                    <span>AI route errors</span>
                                                    <span className="font-medium">{report.aiAnalysis.errorCount}</span>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </ConsolePanel>
                        </div>

                        <div className="lg:col-span-8">
                            <ConsolePanel title={t('attackSimulator.attackResults')} subtitle="逐项攻击判定日志" icon={AlertTriangle} iconTone="warning">
                                <div className="max-h-72 space-y-2 overflow-y-auto pr-1">
                                    {report.results.map((result, i) => (
                                        <motion.div
                                            key={i}
                                            initial={{ opacity: 0, x: -20 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            transition={{ delay: i * 0.05 }}
                                            className={`flex items-center justify-between rounded-xl border p-3 ${
                                                result.blocked
                                                    ? 'border-emerald-500/20 bg-emerald-500/10'
                                                    : 'border-rose-500/20 bg-rose-500/10'
                                            }`}
                                        >
                                            <div className="flex min-w-0 items-center gap-3">
                                                <div className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${
                                                    result.blocked
                                                        ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400'
                                                        : 'bg-rose-500/15 text-rose-600 dark:text-rose-400'
                                                }`}>
                                                    {result.blocked ? <CheckCircle className="h-4 w-4" /> : <XCircle className="h-4 w-4" />}
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="truncate text-sm font-medium text-foreground">{result.attackName}</p>
                                                    <p className="text-xs text-muted-foreground">{getCategoryName(result.category)}</p>
                                                    {result.aiAnalysis?.usedAI && (
                                                        <p className="text-[11px] text-muted-foreground">
                                                            AI {result.aiAnalysis.route || 'unknown'} via {result.aiAnalysis.provider || result.aiAnalysis.engine || 'model-router'}
                                                        </p>
                                                    )}
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <p className={`text-sm font-semibold ${result.blocked ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                                    {result.blocked ? t('attackSimulator.blocked') : t('attackSimulator.allowed')}
                                                </p>
                                                <p className="text-xs text-muted-foreground">{result.responseTime}ms</p>
                                            </div>
                                        </motion.div>
                                    ))}
                                </div>
                            </ConsolePanel>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {history.length > 0 && (
                <motion.div variants={itemVariants}>
                    <ConsolePanel title={t('attackSimulator.recentSimulations')} subtitle="最近完成的演练批次" icon={Clock} iconTone="neutral">
                        <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">
                            {history.slice(0, 6).map((item, i) => (
                                <motion.div
                                    key={item.id || i}
                                    initial={{ opacity: 0, scale: 0.95 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    transition={{ delay: i * 0.05 }}
                                    className="rounded-xl border border-border bg-muted/15 p-4"
                                >
                                    <p className="text-xs text-muted-foreground">{new Date(item.startTime).toLocaleString()}</p>
                                    <div className="mt-3 flex flex-wrap items-center gap-3 text-sm">
                                        <span className="font-medium text-foreground">
                                            {item.total} {t('attackSimulator.attacks')}
                                        </span>
                                        <span className="text-emerald-600 dark:text-emerald-400">
                                            {item.blocked} {t('attackSimulator.blocked')}
                                        </span>
                                        <span className="text-rose-600 dark:text-rose-400">
                                            {item.allowed} {t('attackSimulator.allowed')}
                                        </span>
                                    </div>
                                    <div className="mt-3 flex justify-end">
                                        <Link to={`/attack-sim/runs/${getAttackRunRouteId(item)}`} className="rounded-lg border border-border bg-card px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted/30">
                                            查看详情
                                        </Link>
                                    </div>
                                </motion.div>
                            ))}
                        </div>
                    </ConsolePanel>
                </motion.div>
            )}
        </motion.div>
    );
}

import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Activity, ArrowLeft, Clock3, Cpu, MemoryStick, Router } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';
import { fetchDeviceConfig, fetchDeviceDetail, fetchDeviceEvents } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel, ConsoleStatCard } from '../components/ConsolePrimitives';

interface DeviceInfo {
    deviceId: string;
    version: string;
    chipModel: string;
    freeHeap: number;
    mode: 'online' | 'offline';
    isOnline: boolean;
    lastHeartbeat: string;
    status?: {
        cpuUsage: number;
        memoryUsage: number;
        uptime: number;
        wifiRssi: number;
    };
    transport?: 'wifi' | 'usb_serial' | 'ethernet' | 'unknown';
    externalPowerPresent?: boolean;
    secureElementPresent?: boolean;
    pendingPhysicalApproval?: boolean;
    interlockState?: string;
    hostActionState?: string;
    physicalAuth?: {
        hasPublicKey?: boolean;
        monotonicCounter?: number;
        lastConfirmedAt?: string | null;
    };
    latestConfirmationSession?: {
        id: string;
        commandType: string;
        status: string;
        createdAt: string;
        confirmedAt?: string;
    } | null;
}

const BoardStatus = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { t } = useLanguage();

    const [device, setDevice] = useState<DeviceInfo | null>(null);
    const [deviceConfig, setDeviceConfig] = useState<any>(null);
    const [logs, setLogs] = useState<string[]>([]);
    const [error, setError] = useState<string | null>(null);

    const loadDevice = async () => {
        if (!id) return;
        try {
            const data = await fetchDeviceDetail(id);
            setDevice(data?.device || null);
            const configResponse = await fetchDeviceConfig(id);
            setDeviceConfig(configResponse?.config || null);
            setError(null);
        } catch (e: any) {
            setError(e.message || 'FG-DEVICE-DETAIL-ERR');
        }
    };

    const loadEvents = async () => {
        if (!id) return;
        try {
            const events = await fetchDeviceEvents(id, 80);
            const mapped = (events || []).map((ev: any) => {
                const ts = new Date(ev.timestamp).toLocaleTimeString('zh-CN', { hour12: false });
                return `[${ts}] ${ev.type}: ${JSON.stringify(ev.payload || {})}`;
            });
            setLogs(mapped);
        } catch (e: any) {
            setError(e.message || 'FG-DEVICE-EVENTS-ERR');
        }
    };

    useEffect(() => {
        loadDevice();
        loadEvents();
        const interval = setInterval(() => {
            loadDevice();
            loadEvents();
        }, 5000);
        return () => clearInterval(interval);
    }, [id]);

    const uptimeText = useMemo(() => {
        const uptime = device?.status?.uptime ?? 0;
        const hours = Math.floor(uptime / 3600);
        const minutes = Math.floor((uptime % 3600) / 60);
        return `${hours}h ${minutes}m`;
    }, [device?.status?.uptime]);

    return (
        <ConsolePage
            title={device?.deviceId || id || t('board.unknown')}
            subtitle={`${t('board.device_id')}: ${id || t('board.unknown')}`}
            actions={
                <>
                    <div className="flex items-center gap-2 rounded-full border border-border bg-card px-3 py-2 text-xs font-medium text-muted-foreground">
                        <span className={`h-2 w-2 rounded-full ${device?.isOnline ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                        <span className={device?.isOnline ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}>
                            {device?.isOnline ? '在线' : '离线'}
                        </span>
                    </div>
                    <button
                        onClick={() => navigate('/devices')}
                        className="flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-2 text-sm font-medium text-foreground transition-colors hover:bg-muted/30"
                    >
                        <ArrowLeft size={14} />
                        返回设备列表
                    </button>
                </>
            }
        >
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                <ConsoleStatCard icon={Cpu} label="CPU" value={`${device?.status?.cpuUsage ?? 0}%`} hint={device?.chipModel || '-'} tone="primary" />
                <ConsoleStatCard
                    icon={MemoryStick}
                    label={t('board.memory')}
                    value={`${device?.status?.memoryUsage ?? 0}%`}
                    hint={`${t('board.free_heap')}: ${device?.freeHeap ?? 0}`}
                    tone="warning"
                />
                <ConsoleStatCard
                    icon={Activity}
                    label="Transport"
                    value={device?.transport || 'unknown'}
                    hint={device?.externalPowerPresent ? 'External DC present' : 'USB-only logic power'}
                    tone={device?.isOnline ? 'success' : 'danger'}
                />
                <ConsoleStatCard
                    icon={Clock3}
                    label="Uptime"
                    value={uptimeText}
                    hint={device?.lastHeartbeat ? new Date(device.lastHeartbeat).toLocaleString() : '-'}
                    tone="neutral"
                />
            </div>

            <div className="grid grid-cols-1 gap-6 lg:grid-cols-12">
                <div className="lg:col-span-4">
                    <ConsolePanel title={t('board.device_metrics')} subtitle="网关运行时指标" icon={Router} iconTone="primary">
                        <div className="space-y-3 text-sm">
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">{t('board.chip')}</span>
                                <span className="font-medium text-foreground">{device?.chipModel || '-'}</span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">{t('board.version')}</span>
                                <span className="font-medium text-foreground">{device?.version || '-'}</span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">{t('board.mode')}</span>
                                <span className="font-medium text-foreground">{device?.mode || '-'}</span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Secure element</span>
                                <span className="font-medium text-foreground">{device?.secureElementPresent ? 'Present' : 'Missing'}</span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Interlock / Host action</span>
                                <span className="text-right font-medium text-foreground">{device?.interlockState || 'unknown'} / {device?.hostActionState || 'unknown'}</span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Physical confirmation</span>
                                <span className="text-right font-medium text-foreground">{device?.pendingPhysicalApproval ? 'Pending' : 'Idle'}</span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Verification key</span>
                                <span className="text-right font-medium text-foreground">
                                    {device?.physicalAuth?.hasPublicKey ? `Loaded · ctr ${device?.physicalAuth?.monotonicCounter || 0}` : 'Unavailable'}
                                </span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Last confirmed</span>
                                <span className="text-right font-medium text-foreground">
                                    {device?.physicalAuth?.lastConfirmedAt ? new Date(device.physicalAuth.lastConfirmedAt).toLocaleString() : 'Never'}
                                </span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Confirmation session</span>
                                <span className="text-right font-medium text-foreground">
                                    {device?.latestConfirmationSession ? `${device.latestConfirmationSession.commandType} / ${device.latestConfirmationSession.status}` : 'None'}
                                </span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">Allowed commands</span>
                                <span className="text-right font-medium text-foreground">
                                    {Array.isArray(deviceConfig?.commandPermissions) ? deviceConfig.commandPermissions.length : 0}
                                </span>
                            </div>
                            <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
                                <span className="text-muted-foreground">{t('board.last_heartbeat')}</span>
                                <span className="text-right font-medium text-foreground">
                                    {device?.lastHeartbeat ? new Date(device.lastHeartbeat).toLocaleString() : '-'}
                                </span>
                            </div>
                            <div className="flex items-center justify-between gap-3">
                                <span className="text-muted-foreground">{t('board.real_data')}</span>
                                <span className="rounded-full border border-border bg-muted/30 px-2 py-1 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                                    /api/devices/{id}
                                </span>
                            </div>
                        </div>

                        {error && (
                            <div className="mt-4 rounded-lg border border-rose-500/20 bg-rose-500/10 px-3 py-2 text-xs text-rose-600 dark:text-rose-300">
                                {error}
                            </div>
                        )}
                    </ConsolePanel>
                </div>

                <div className="lg:col-span-8">
                    <ConsolePanel
                        title={t('board.event_stream')}
                        subtitle="设备最近事件流"
                        icon={Activity}
                        iconTone="warning"
                        headerAction={<span className="text-xs text-muted-foreground">/api/devices/{id}/events</span>}
                    >
                        <div className="rounded-xl border border-border bg-muted/20">
                            <div className="flex items-center justify-between border-b border-border px-4 py-3 text-xs text-muted-foreground">
                                <span className="font-medium text-foreground">实时事件流</span>
                                <span>最近 80 条</span>
                            </div>
                            <div className="max-h-[560px] overflow-y-auto px-4 py-4">
                                {logs.length > 0 ? (
                                    <div className="space-y-2 font-mono text-xs leading-6 text-foreground">
                                        {logs.map((log, index) => (
                                            <div key={`${log}-${index}`} className="rounded-lg border border-border/70 bg-background/70 px-3 py-2">
                                                {log}
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <ConsoleEmptyState title="暂无事件" description="设备上报遥测后，这里会显示事件消息。" />
                                )}
                            </div>
                        </div>
                    </ConsolePanel>
                </div>
            </div>
        </ConsolePage>
    );
};

export default BoardStatus;

import { useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';
import {
    Activity,
    Code,
    Cpu,
    Database,
    Download,
    Globe,
    HardDrive,
    Key,
    Pause,
    Search,
    Server,
    Shield,
    Terminal,
    AlertTriangle,
    Zap,
} from 'lucide-react';
import {
    fetchAdminApiKeys,
    fetchCurrentUserSession,
    fetchDashboardRulesSummary,
    fetchEdgeAutoModules,
    fetchEdgeAutoSummary,
    fetchLogs,
    fetchStats,
    isRequestAbortError,
} from '../services/api';
import type { EdgeAutoSummary } from '../types/edge-auto';
import { EdgeAutoProtocolSummaryGrid } from '../components/EdgeAutoProtocolModules';
import { DashboardSecuritySummary, DashboardStats, LogItem } from '../types/api';
import ErrorDisplay from '../components/ErrorDisplay';
import { useWebSocket } from '../context/WebSocketContext';
import { useLiveMode } from '../context/LiveModeContext';
import { ConsoleEmptyState, ConsolePage, ConsolePanel, ConsoleStatCard } from '../components/ConsolePrimitives';
import StableResponsiveChart from '../components/StableResponsiveChart';

const defaultSecuritySummary: DashboardSecuritySummary = {
    openCriticalFindings: 0,
    highRiskFindings: 0,
    activeAlerts: 0,
    runningScans: 0,
    queuedScans: 0,
    pendingActions: 0,
    failedValidations: 0,
    assetsAtRisk: 0,
    observedSessions: 0,
    trafficAnomalies: 0,
    recentActions: [],
    recentValidations: [],
};

const TrafficChart = ({ data }: { data: { time: string; requests: number; blocked: number }[] }) => (
    <StableResponsiveChart minHeight={300} loadingText="Waiting for chart container...">
        <AreaChart data={data}>
            <defs>
                <linearGradient id="colorRequests" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.18} />
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                </linearGradient>
                <linearGradient id="colorBlocked" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#ef4444" stopOpacity={0.18} />
                    <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
                </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
            <XAxis dataKey="time" stroke="hsl(var(--muted-foreground))" fontSize={11} tickLine={false} axisLine={false} dy={10} />
            <YAxis stroke="hsl(var(--muted-foreground))" fontSize={11} tickLine={false} axisLine={false} dx={-10} />
            <Tooltip
                contentStyle={{
                    backgroundColor: 'hsl(var(--card))',
                    borderColor: 'hsl(var(--border))',
                    borderRadius: '12px',
                }}
            />
            <Area type="monotone" dataKey="requests" stroke="#3b82f6" strokeWidth={2.5} fillOpacity={1} fill="url(#colorRequests)" />
            <Area type="monotone" dataKey="blocked" stroke="#ef4444" strokeWidth={2.5} fillOpacity={1} fill="url(#colorBlocked)" />
        </AreaChart>
    </StableResponsiveChart>
);

const LogStream = ({ logs, emptyText }: { logs: LogItem[]; emptyText: string }) => (
    <div className="h-full rounded-xl border border-border bg-muted/15 p-4">
        <div className="h-full space-y-2 overflow-y-auto font-mono text-xs">
            <AnimatePresence>
                {logs.map((log) => (
                    <motion.div
                        key={`${log.id}-${log.time}`}
                        initial={{ opacity: 0, x: -12 }}
                        animate={{ opacity: 1, x: 0 }}
                        className={`flex gap-4 rounded-lg border p-2.5 ${
                            log.level === 'ERROR' || log.status === 403
                                ? 'border-rose-500/20 bg-rose-500/10 text-rose-600 dark:text-rose-300'
                                : 'border-border bg-card text-foreground'
                        }`}
                    >
                        <span className="w-20 shrink-0 text-muted-foreground">{new Date(log.time).toLocaleTimeString()}</span>
                        <span className="w-12 shrink-0 font-bold">{log.status || 200}</span>
                        <span className="w-12 shrink-0 font-semibold text-primary">{log.type}</span>
                        <span className="break-all">{log.message}</span>
                    </motion.div>
                ))}
            </AnimatePresence>
            {logs.length === 0 && <div className="py-8 text-center font-sans text-muted-foreground">{emptyText}</div>}
        </div>
    </div>
);

const countryColor = (code: string) => ({
    CN: 'bg-rose-500',
    US: 'bg-blue-500',
    RU: 'bg-rose-600',
    JP: 'bg-amber-500',
    DE: 'bg-cyan-500',
    GB: 'bg-indigo-500',
    Unknown: 'bg-slate-400',
}[code] || 'bg-slate-400');

export default function Dashboard() {
    const { subscribe } = useWebSocket();
    const { liveModeEnabled } = useLiveMode();
    const [stats, setStats] = useState<DashboardStats | null>(null);
    const [logs, setLogs] = useState<LogItem[]>([]);
    const [error, setError] = useState<string | null>(null);
    const [rulesSummary, setRulesSummary] = useState<{ totalRules: number; topRules: any[] }>({ totalRules: 0, topRules: [] });
    const [edgeAutoSummary, setEdgeAutoSummary] = useState<EdgeAutoSummary | null>(null);
    const [edgeAutoModules, setEdgeAutoModules] = useState<any[]>([]);
    const [apiKeys, setApiKeys] = useState<any[]>([]);
    const [userRole, setUserRole] = useState('viewer');
    const [timeRange, setTimeRange] = useState<'1h' | '24h'>('1h');
    const [filterQuery, setFilterQuery] = useState('');
    const [paused, setPaused] = useState(false);
    const [exportMessage, setExportMessage] = useState<string | null>(null);

    const filteredLogs = useMemo(() => logs.filter((log) => {
        if (!filterQuery.trim()) return true;
        const query = filterQuery.toLowerCase();
        return [log.type, log.level, log.message, log.path, log.method, String(log.status || '')]
            .filter(Boolean)
            .some((value) => String(value).toLowerCase().includes(query));
    }), [filterQuery, logs]);

    const filteredHistory = useMemo(
        () => stats?.history?.slice(timeRange === '1h' ? -10 : 0) || [],
        [stats?.history, timeRange],
    );

    const securitySummary = stats?.securityOperations || defaultSecuritySummary;

    useEffect(() => {
        let disposed = false;
        let controller: AbortController | null = null;

        const loadData = async () => {
            controller?.abort();
            controller = new AbortController();
            try {
                const statsData = await fetchStats(controller.signal);
                if (!disposed && statsData) {
                    setStats(statsData);
                    setError(null);
                }
            } catch (err: any) {
                if (!disposed && !isRequestAbortError(err, controller.signal)) {
                    setError(err.message || 'FG-DASHBOARD-STATS');
                }
            }
        };

        void loadData();
        if (!liveModeEnabled || paused) {
            return () => {
                disposed = true;
                controller?.abort();
            };
        }

        const interval = setInterval(() => {
            void loadData();
        }, 4000);

        return () => {
            disposed = true;
            controller?.abort();
            clearInterval(interval);
        };
    }, [liveModeEnabled, paused]);

    useEffect(() => {
        let disposed = false;
        const controller = new AbortController();

        void fetchLogs(controller.signal)
            .then((rows) => {
                if (!disposed && Array.isArray(rows)) {
                    setLogs(rows);
                }
            })
            .catch((err) => {
                if (!disposed && !isRequestAbortError(err, controller.signal)) {
                    setError(err.message || 'FG-DASHBOARD-LOGS');
                }
            });

        const unsubscribe = subscribe('agent:log', (logData: any) => {
            if (paused) return;
            setLogs((prev) => [logData, ...prev].slice(0, 100));
        });

        return () => {
            disposed = true;
            controller.abort();
            unsubscribe();
        };
    }, [paused, subscribe]);

    useEffect(() => {
        let disposed = false;
        const controller = new AbortController();

        const loadSideData = async () => {
            try {
                const user = await fetchCurrentUserSession(controller.signal);
                const role = user?.role || 'viewer';
                if (disposed) return;
                setUserRole(role);

                const [rules, edgeSummary, moduleManifests, keys] = await Promise.all([
                    fetchDashboardRulesSummary(controller.signal),
                    fetchEdgeAutoSummary(controller.signal).catch(() => null),
                    fetchEdgeAutoModules(controller.signal).catch(() => []),
                    role === 'admin' ? fetchAdminApiKeys(controller.signal).catch(() => []) : Promise.resolve([]),
                ]);

                if (disposed) return;
                setRulesSummary(rules || { totalRules: 0, topRules: [] });
                setEdgeAutoSummary(edgeSummary);
                setEdgeAutoModules(moduleManifests || []);
                setApiKeys(keys || []);
            } catch (err: any) {
                if (!disposed && !isRequestAbortError(err, controller.signal)) {
                    setError(err.message || 'FG-DASHBOARD-SIDE');
                }
            }
        };

        void loadSideData();

        return () => {
            disposed = true;
            controller.abort();
        };
    }, []);

    if (error) {
        return <ErrorDisplay title="Dashboard unavailable" message={error} onRetry={() => window.location.reload()} />;
    }

    if (!stats) {
        return (
            <div className="flex min-h-[400px] items-center justify-center">
                <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}
                    className="h-8 w-8 rounded-full border-b-2 border-t-2 border-primary"
                />
            </div>
        );
    }

    const exportSnapshot = (format: 'json' | 'csv') => {
        const payload = format === 'json'
            ? JSON.stringify({
                generatedAt: new Date().toISOString(),
                timeRange,
                filterQuery,
                stats,
                logs: filteredLogs,
            }, null, 2)
            : [
                'time,type,level,status,method,path,message',
                ...filteredLogs.map((log) => [
                    log.time,
                    log.type,
                    log.level,
                    log.status || '',
                    log.method || '',
                    log.path || '',
                    `"${String(log.message).replace(/"/g, '""')}"`,
                ].join(',')),
            ].join('\n');

        const blob = new Blob([payload], { type: format === 'json' ? 'application/json' : 'text/csv;charset=utf-8' });
        const url = window.URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = `dashboard-${timeRange}-${Date.now()}.${format}`;
        anchor.click();
        window.URL.revokeObjectURL(url);
        setExportMessage(`已导出当前视图（${format.toUpperCase()}）`);
        window.setTimeout(() => setExportMessage(null), 2500);
    };

    const healthStatus = stats.successRate >= 99 ? '系统健康' : stats.successRate >= 95 ? '运行稳定' : '需要重点关注';
    const emptyAttackDescription = securitySummary.observedSessions || securitySummary.trafficAnomalies
        ? `最近已观测 ${securitySummary.observedSessions || 0} 条会话，识别 ${securitySummary.trafficAnomalies || 0} 个异常流量特征。`
        : '当前没有新的来源分布，但系统仍在持续接收实时流量摘要。';
    const emptyRulesDescription = securitySummary.activeAlerts || securitySummary.highRiskFindings
        ? `当前有 ${securitySummary.activeAlerts} 条活跃告警、${securitySummary.highRiskFindings || 0} 条高风险发现等待规则命中。`
        : '规则命中后这里会显示排行；当前可转到监控、告警和设备页查看实时状态。';
    const emptyLogsText = securitySummary.pendingActions || securitySummary.failedValidations
        ? `当前没有新的日志流；待执行动作 ${securitySummary.pendingActions}，失败验证 ${securitySummary.failedValidations}。`
        : '正在等待新的日志事件进入当前视图。';

    return (
        <ConsolePage title="安全控制台" subtitle="统一监控、规则、日志与运营摘要">
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                <ConsoleStatCard icon={Server} label="总请求数" value={stats.totalRequests.toLocaleString()} hint="整体流量处理规模" tone="primary" />
                <ConsoleStatCard icon={Shield} label="拦截威胁" value={stats.blockedRequests.toLocaleString()} hint="近期拦截事件累计" tone="danger" />
                <ConsoleStatCard icon={Zap} label="平均延迟" value={`${stats.avgProcessingTime || 0}ms`} hint={`P99 ${stats.p99Latency || 0}ms`} tone="warning" />
                <ConsoleStatCard icon={Globe} label="全局健康" value={`${stats.successRate}%`} hint={healthStatus} tone="success" />
            </div>

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                <ConsoleStatCard icon={Cpu} label="CPU 使用率" value={`${stats.cpuUsage?.toFixed(1) || 0}%`} hint="主机 CPU" tone="primary" />
                <ConsoleStatCard icon={HardDrive} label="内存占用" value={`${stats.memoryUsage?.toFixed(1) || 0}%`} hint="系统内存" tone="warning" />
                <ConsoleStatCard icon={Database} label="磁盘占用" value={`${stats.diskUsage?.toFixed(1) || 0}%`} hint="根分区使用率" tone="neutral" />
                <ConsoleStatCard icon={Activity} label="网络吞吐" value={`${stats.networkUsage?.toFixed(2) || 0} MB/s`} hint="实时 I/O 吞吐量" tone="success" />
            </div>

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                <ConsoleStatCard icon={AlertTriangle} label="高危发现" value={securitySummary.openCriticalFindings} hint={`高风险总数 ${securitySummary.highRiskFindings || 0}`} tone="danger" />
                <ConsoleStatCard icon={Shield} label="活跃告警" value={securitySummary.activeAlerts} hint={`待处理动作 ${securitySummary.pendingActions}`} tone="warning" />
                <ConsoleStatCard icon={Search} label="扫描任务" value={securitySummary.runningScans} hint={`排队中 ${securitySummary.queuedScans || 0}`} tone="primary" />
                <ConsoleStatCard icon={Globe} label="观测会话" value={securitySummary.observedSessions || 0} hint={`异常流量 ${securitySummary.trafficAnomalies || 0}`} tone="success" />
            </div>

            {edgeAutoSummary && (
                <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                    <ConsoleStatCard icon={Server} label="Edge + Vehicle" value={(edgeAutoSummary.edgeNodes + edgeAutoSummary.vehicleNodes).toLocaleString()} hint={`Vehicle ${edgeAutoSummary.vehicleNodes} | Edge ${edgeAutoSummary.edgeNodes}`} tone="primary" />
                    <ConsoleStatCard icon={Cpu} label="ARM64 Nodes" value={edgeAutoSummary.arm64Nodes} hint={`Cloud ${edgeAutoSummary.cloudNodes}`} tone="warning" />
                    <ConsoleStatCard icon={Activity} label="Bypass Nodes" value={edgeAutoSummary.readOnlyBypassNodes} hint={`Protocol anomalies ${edgeAutoSummary.protocolAnomalies}`} tone={edgeAutoSummary.readOnlyBypassNodes > 0 ? 'danger' : 'success'} />
                    <ConsoleStatCard icon={Download} label="MQTT Saved" value={`${edgeAutoSummary.mqttSavedMb} MB`} hint={`${edgeAutoSummary.mqttSavedMessages} suppressed`} tone="success" />
                </div>
            )}

            {edgeAutoSummary && edgeAutoModules.length > 0 && (
                <ConsolePanel
                    title="Protocol Modules"
                    subtitle="Manifest-driven protocol module activity across edge and vehicle nodes"
                    icon={Shield}
                    iconTone="primary"
                >
                    <EdgeAutoProtocolSummaryGrid
                        manifests={edgeAutoModules}
                        stats={undefined}
                        finops={undefined}
                        summary={edgeAutoSummary.modules}
                        compact
                    />
                </ConsolePanel>
            )}

            <div className="grid grid-cols-1 gap-6 lg:grid-cols-12">
                <div className="lg:col-span-8">
                    <ConsolePanel
                        title="流量分析"
                        subtitle="按时间窗口查看请求与拦截趋势"
                        icon={Activity}
                        iconTone="primary"
                    >
                        <div className="flex items-center justify-end gap-2 pb-4">
                            <button
                                onClick={() => setTimeRange('1h')}
                                className={`rounded-lg border px-4 py-1.5 text-xs font-semibold ${
                                    timeRange === '1h'
                                        ? 'border-border bg-card text-foreground'
                                        : 'border-transparent text-muted-foreground hover:text-foreground'
                                }`}
                            >
                                1 小时
                            </button>
                            <button
                                onClick={() => setTimeRange('24h')}
                                className={`rounded-lg border px-4 py-1.5 text-xs font-semibold ${
                                    timeRange === '24h'
                                        ? 'border-border bg-card text-foreground'
                                        : 'border-transparent text-muted-foreground hover:text-foreground'
                                }`}
                            >
                                24 小时
                            </button>
                        </div>
                        <TrafficChart data={filteredHistory} />
                    </ConsolePanel>
                </div>

                <div className="lg:col-span-4">
                    <ConsolePanel title="攻击来源" subtitle="按地区聚合的最近来源分布" icon={Globe} iconTone="warning">
                        <div className="space-y-5">
                            {(stats.attackOrigins || []).length > 0 ? (
                                stats.attackOrigins!.map((item, index) => (
                                    <div key={`${item.countryCode}-${index}`}>
                                        <div className="mb-2 flex items-center justify-between text-sm">
                                            <span className="flex items-center gap-2 font-medium text-foreground">
                                                <span className={`h-2 w-2 rounded-full ${countryColor(item.countryCode)}`} />
                                                {item.country}
                                                <span className="text-muted-foreground">({item.countryCode})</span>
                                            </span>
                                            <span className="font-mono font-bold text-foreground">{Math.round(item.percentage)}%</span>
                                        </div>
                                        <div className="h-2 overflow-hidden rounded-full border border-border/50 bg-muted">
                                            <motion.div
                                                initial={{ width: 0 }}
                                                animate={{ width: `${item.percentage}%` }}
                                                transition={{ duration: 0.6, delay: index * 0.06 }}
                                                className={`h-full ${countryColor(item.countryCode)}`}
                                            />
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <ConsoleEmptyState title="暂无攻击来源分布" description={emptyAttackDescription} />
                            )}
                        </div>
                    </ConsolePanel>
                </div>
            </div>

            <div className="grid grid-cols-1 gap-6 lg:grid-cols-12">
                <div className="lg:col-span-8">
                    <ConsolePanel
                        title="实时日志流"
                        subtitle="筛选当前视图并导出结果"
                        icon={Terminal}
                        iconTone="neutral"
                        headerAction={(
                            <div className="flex items-center gap-3">
                                <div className="relative">
                                    <Search className="absolute left-3 top-2 text-muted-foreground" size={16} />
                                    <input
                                        type="text"
                                        value={filterQuery}
                                        onChange={(event) => setFilterQuery(event.target.value)}
                                        placeholder="筛选：status / type / path / message"
                                        className="w-full rounded-lg border border-border bg-card py-1.5 pl-9 pr-3 text-sm text-foreground placeholder:text-muted-foreground focus:border-primary focus:outline-none md:w-64"
                                    />
                                </div>
                                <button
                                    onClick={() => setPaused((current) => !current)}
                                    className={`rounded-lg border border-border bg-card p-2 transition-colors hover:bg-muted/30 ${
                                        paused ? 'text-amber-600 dark:text-amber-400' : 'text-muted-foreground hover:text-foreground'
                                    }`}
                                >
                                    <Pause size={18} />
                                </button>
                                <button
                                    onClick={() => exportSnapshot('json')}
                                    className="rounded-lg border border-border bg-card p-2 text-muted-foreground transition-colors hover:bg-muted/30 hover:text-foreground"
                                >
                                    <Download size={18} />
                                </button>
                                <button
                                    onClick={() => exportSnapshot('csv')}
                                    className="rounded-lg border border-border bg-card px-3 py-2 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted/30 hover:text-foreground"
                                >
                                    CSV
                                </button>
                            </div>
                        )}
                    >
                        {exportMessage && (
                            <div className="mb-3 rounded-lg border border-emerald-500/20 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-600 dark:text-emerald-300">
                                {exportMessage}
                            </div>
                        )}
                        <div className="h-[450px]">
                            <LogStream logs={filteredLogs} emptyText={emptyLogsText} />
                        </div>
                    </ConsolePanel>
                </div>

                <div className="space-y-6 lg:col-span-4">
                    <ConsolePanel title="最近运营动作" subtitle="来自扫描、处置和验证链路的最新结果" icon={Zap} iconTone="success">
                        {(securitySummary.recentActions || []).length > 0 || (securitySummary.recentValidations || []).length > 0 ? (
                            <div className="space-y-3">
                                {(securitySummary.recentActions || []).slice(0, 3).map((action) => (
                                    <div key={action.actionId} className="rounded-xl border border-border bg-muted/15 p-3">
                                        <div className="text-sm font-semibold text-foreground">{action.title}</div>
                                        <div className="mt-1 flex items-center justify-between text-xs text-muted-foreground">
                                            <span>{action.status}</span>
                                            <span>{new Date(action.updatedAt || action.createdAt).toLocaleString()}</span>
                                        </div>
                                    </div>
                                ))}
                                {(securitySummary.recentValidations || []).slice(0, 2).map((validation) => (
                                    <div key={validation.validationRunId} className="rounded-xl border border-border bg-muted/15 p-3">
                                        <div className="text-sm font-semibold text-foreground">{validation.attackName}</div>
                                        <div className="mt-1 flex items-center justify-between text-xs text-muted-foreground">
                                            <span>{validation.verdict}</span>
                                            <span>{new Date(validation.completedAt).toLocaleString()}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <ConsoleEmptyState title="暂无新的运营动作" description="当扫描、处置或攻击验证完成后，这里会展示最近的真实结果。" />
                        )}
                    </ConsolePanel>

                    <ConsolePanel
                        title="活跃规则"
                        subtitle="触发次数最高的规则清单"
                        icon={Code}
                        iconTone="primary"
                        headerAction={(
                            <span className="rounded-full border border-border bg-muted px-3 py-1 text-xs font-semibold text-muted-foreground">
                                总计 {rulesSummary.totalRules || 0}
                            </span>
                        )}
                    >
                        <div className="space-y-4">
                            {(rulesSummary.topRules || []).length > 0 ? (
                                (rulesSummary.topRules || []).slice(0, 5).map((rule: any) => (
                                    <div key={rule.id} className="flex items-center justify-between rounded-xl border border-border bg-muted/15 p-3 transition-colors hover:bg-muted/25">
                                        <div className="flex items-center gap-4">
                                            <div className="flex h-10 w-10 items-center justify-center rounded-lg border border-primary/15 bg-primary/10 text-primary">
                                                <Code size={18} />
                                            </div>
                                            <div>
                                                <div className="text-sm font-semibold text-foreground">{rule.name || rule.id}</div>
                                                <div className="text-xs uppercase tracking-wide text-muted-foreground">严重级别 {rule.severity || 'unknown'}</div>
                                            </div>
                                        </div>
                                        <div className="rounded-md border border-primary/15 bg-primary/10 px-2 py-1 font-mono text-sm font-semibold text-primary">
                                            {rule.count || 0}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <ConsoleEmptyState title="暂无规则遥测" description={emptyRulesDescription} />
                            )}
                        </div>
                    </ConsolePanel>

                    {userRole === 'admin' && (
                        <ConsolePanel title="管理员 API 密钥" subtitle="快速查看最近使用的接入前缀" icon={Key} iconTone="success">
                            <div className="space-y-4">
                                <p className="text-sm leading-6 text-muted-foreground">
                                    展示当前管理员可快速核对的首个密钥前缀与最近使用时间，便于排查接入链路。
                                </p>
                                <div className="flex items-center justify-between rounded-xl border border-border bg-muted p-3">
                                    <code className="font-mono text-sm font-bold text-emerald-600 dark:text-emerald-400">
                                        {apiKeys[0]?.prefix ? `${apiKeys[0].prefix}********` : '未找到'}
                                    </code>
                                    <span className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                                        {apiKeys[0]?.lastUsed || 'never'}
                                    </span>
                                </div>
                            </div>
                        </ConsolePanel>
                    )}
                </div>
            </div>
        </ConsolePage>
    );
}

import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Server, Download, Check, FileCode, ChevronRight, Save } from 'lucide-react';
import { clsx } from 'clsx';
import { useLanguage } from '../context/LanguageContext';
import { DeploymentTarget, fetchDeploymentHistory, generateDeploymentConfig, getDeploymentDownloadUrl, saveDeploymentConfig } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';

interface GeneratedConfig {
    configText: string;
    envSnippet: string;
    checksum: string;
    warnings: string[];
}

const deploymentTargets: DeploymentTarget[] = ['nginx', 'apache', 'caddy', 'docker_compose', 'binary_agent', 'k8s_daemonset'];

const DeploymentWizard = () => {
    const { t } = useLanguage();
    const [step, setStep] = useState(1);
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [serverType, setServerType] = useState<DeploymentTarget | null>(null);
    const [generated, setGenerated] = useState<GeneratedConfig | null>(null);
    const [savedId, setSavedId] = useState<string | null>(null);
    const [history, setHistory] = useState<any[]>([]);
    const [config, setConfig] = useState({
        port: '8080',
        serverName: 'api.example.com',
        rateLimit: '100',
        upstream: 'http://backend:3005',
    });

    const handleNext = async () => {
        if (step === 1) {
            setStep(2);
            return;
        }
        if (step === 2) {
            await doGenerate();
        }
    };

    const handleBack = () => {
        setError(null);
        setStep((prev) => Math.max(1, prev - 1));
    };

    const doGenerate = async () => {
        if (!serverType) return;
        setError(null);
        setLoading(true);
        try {
            const response = await generateDeploymentConfig({
                serverType,
                profile: {
                    port: Number(config.port),
                    serverName: config.serverName,
                    rateLimit: Number(config.rateLimit),
                    upstream: config.upstream,
                },
            });
            setGenerated(response.data);
            setStep(3);
        } catch (e: any) {
            setError(e.message || '生成配置失败');
        } finally {
            setLoading(false);
        }
    };

    const doSave = async () => {
        if (!serverType || !generated) return;
        setSaving(true);
        setError(null);
        try {
            const response = await saveDeploymentConfig({
                serverType,
                profile: {
                    port: Number(config.port),
                    serverName: config.serverName,
                    rateLimit: Number(config.rateLimit),
                    upstream: config.upstream,
                },
                configText: generated.configText,
                envSnippet: generated.envSnippet,
                name: `${serverType}-${config.serverName}`,
            });
            setSavedId(response.data.deploymentId);
            await loadHistory();
        } catch (e: any) {
            setError(e.message || '保存部署配置失败');
        } finally {
            setSaving(false);
        }
    };

    const loadHistory = async () => {
        try {
            const rows = await fetchDeploymentHistory(undefined, 10);
            setHistory(rows);
        } catch {
            setHistory([]);
        }
    };

    useEffect(() => {
        loadHistory();
    }, []);

    return (
        <ConsolePage title={t('deploy.title')} subtitle="按步骤生成、保存并下载中间件部署配置">
            <div className="grid grid-cols-1 gap-6 xl:grid-cols-3">
                <ConsolePanel title="部署向导" subtitle="按步骤完成中间件配置" icon={Server} iconTone="primary" className="xl:col-span-2">
                    <div className="relative mb-12 flex items-center justify-between">
                        <div className="absolute left-0 top-1/2 h-px w-full -translate-y-1/2 bg-border" />
                        {[1, 2, 3].map((s) => (
                            <div key={s} className="relative z-10 flex flex-col items-center gap-2 bg-card px-2">
                                <div
                                    className={clsx(
                                        'flex h-8 w-8 items-center justify-center rounded-full border text-sm font-bold transition-all',
                                        step >= s ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-muted text-muted-foreground',
                                    )}
                                >
                                    {step > s ? <Check size={14} /> : s}
                                </div>
                                <span className="whitespace-nowrap text-xs font-medium text-muted-foreground">{s === 1 ? t('deploy.step1') : s === 2 ? t('deploy.step2') : t('deploy.step3')}</span>
                            </div>
                        ))}
                    </div>

                    {error && <div className="mb-4 rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}

                    {step === 1 && (
                        <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }}>
                            <h2 className="mb-6 text-lg font-medium text-foreground">{t('deploy.select_server')}</h2>
                            <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                                {deploymentTargets.map((type) => (
                                    <div
                                        key={type}
                                        onClick={() => setServerType(type)}
                                        className={clsx(
                                            'flex cursor-pointer flex-col items-center gap-4 rounded-xl border p-6 transition-colors',
                                            serverType === type ? 'border-primary bg-primary/5' : 'border-border bg-muted/15 hover:bg-muted/25',
                                        )}
                                    >
                                        <Server size={48} className={serverType === type ? 'text-primary' : 'text-muted-foreground'} />
                                        <span className="text-base font-medium capitalize text-foreground">{type}</span>
                                    </div>
                                ))}
                            </div>
                        </motion.div>
                    )}

                    {step === 2 && (
                        <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">
                            <h2 className="text-lg font-medium text-foreground">{t('deploy.configure_middleware')}</h2>
                            <div className="grid grid-cols-1 gap-6">
                                <div>
                                    <label className="mb-2 block text-xs text-muted-foreground">{t('deploy.listen_port')}</label>
                                    <input
                                        type="text"
                                        value={config.port}
                                        onChange={(e) => setConfig({ ...config, port: e.target.value })}
                                        className="w-full rounded-lg border border-border bg-muted/20 px-4 py-2 text-sm text-foreground focus:border-primary focus:outline-none"
                                    />
                                </div>
                                <div>
                                    <label className="mb-2 block text-xs text-muted-foreground">{t('deploy.server_name')}</label>
                                    <input
                                        type="text"
                                        value={config.serverName}
                                        onChange={(e) => setConfig({ ...config, serverName: e.target.value })}
                                        className="w-full rounded-lg border border-border bg-muted/20 px-4 py-2 text-sm text-foreground focus:border-primary focus:outline-none"
                                    />
                                </div>
                                <div>
                                    <label className="mb-2 block text-xs text-muted-foreground">{t('deploy.rate_limit')}</label>
                                    <input
                                        type="text"
                                        value={config.rateLimit}
                                        onChange={(e) => setConfig({ ...config, rateLimit: e.target.value })}
                                        className="w-full rounded-lg border border-border bg-muted/20 px-4 py-2 text-sm text-foreground focus:border-primary focus:outline-none"
                                    />
                                </div>
                                <div>
                                    <label className="mb-2 block text-xs text-muted-foreground">{t('wizard.upstream')}</label>
                                    <input
                                        type="text"
                                        value={config.upstream}
                                        onChange={(e) => setConfig({ ...config, upstream: e.target.value })}
                                        className="w-full rounded-lg border border-border bg-muted/20 px-4 py-2 text-sm text-foreground focus:border-primary focus:outline-none"
                                    />
                                </div>
                            </div>
                        </motion.div>
                    )}

                    {step === 3 && generated && (
                        <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">
                            <div className="mb-4 text-center">
                                <div className="mb-4 inline-flex rounded-full border border-emerald-500/20 bg-emerald-500/10 p-4 text-emerald-600 dark:text-emerald-400">
                                    <FileCode size={48} />
                                </div>
                                <h2 className="text-xl font-bold text-foreground">{t('deploy.config_ready')}</h2>
                                <p className="mt-2 text-sm text-muted-foreground">{t('deploy.config_desc')}</p>
                            </div>

                            <div className="text-xs text-muted-foreground">
                                校验和：<span className="font-mono">{generated.checksum}</span>
                            </div>
                            <div className="overflow-x-auto rounded-xl border border-border bg-muted/20 p-6 font-mono text-xs text-foreground">
                                <pre>{generated.configText}</pre>
                                <div className="my-4 border-t border-border"></div>
                                <pre>{generated.envSnippet}</pre>
                            </div>
                        </motion.div>
                    )}

                    <div className="mt-8 flex justify-between border-t border-border pt-6">
                        <button
                            onClick={handleBack}
                            disabled={step === 1 || loading || saving}
                            className={clsx('rounded-lg px-4 py-2 text-sm font-medium transition-colors', step === 1 ? 'cursor-not-allowed text-muted-foreground' : 'text-muted-foreground hover:bg-muted/30 hover:text-foreground')}
                        >
                            {t('deploy.back')}
                        </button>

                        {step < 3 ? (
                            <button
                                onClick={handleNext}
                                disabled={(step === 1 && !serverType) || loading}
                                className={clsx(
                                    'flex items-center gap-2 rounded-lg bg-primary px-6 py-2 text-sm font-medium text-primary-foreground transition-colors',
                                    (step === 1 && !serverType) || loading ? 'cursor-not-allowed opacity-50' : 'hover:bg-primary/90',
                                )}
                            >
                                {loading ? t('wizard.generating') : t('deploy.next')} <ChevronRight size={16} />
                            </button>
                        ) : (
                            <div className="flex gap-2">
                                <button
                                    onClick={doSave}
                                    disabled={saving || !generated}
                                    className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-60"
                                >
                                    <Save size={16} /> {saving ? t('wizard.saving') : t('wizard.save_version')}
                                </button>
                                <a
                                    href={savedId ? getDeploymentDownloadUrl(savedId, 'bundle') : '#'}
                                    className={clsx('flex items-center gap-2 rounded-lg bg-emerald-600 px-6 py-2 text-sm font-medium text-white transition-colors hover:bg-emerald-500', !savedId && 'pointer-events-none opacity-50')}
                                >
                                    <Download size={16} /> {t('wizard.download')}
                                </a>
                            </div>
                        )}
                    </div>
                </ConsolePanel>

                <ConsolePanel title={t('wizard.deployment_history')} subtitle="最近生成与保存的配置包" icon={FileCode} iconTone="neutral">
                    <div className="max-h-[560px] space-y-3 overflow-y-auto pr-1">
                        {history.length === 0 && <ConsoleEmptyState title={t('wizard.no_profiles')} description="还没有保存过部署配置。" />}
                        {history.map((row: any) => (
                            <div key={row.id} className="rounded-xl border border-border bg-muted/15 p-3">
                                <div className="flex items-start justify-between gap-2">
                                    <div>
                                        <div className="text-sm font-medium text-foreground">{row.name || row.server_type}</div>
                                        <div className="text-xs text-muted-foreground">
                                            v{row.version} / {row.server_type}
                                        </div>
                                    </div>
                                    <a href={getDeploymentDownloadUrl(row.id, 'bundle')} className="text-xs text-primary hover:underline">
                                        {t('wizard.download')}
                                    </a>
                                </div>
                                <div className="mt-2 break-all font-mono text-[10px] text-muted-foreground">{row.checksum}</div>
                                <div className="mt-1 text-[10px] text-muted-foreground">{new Date(row.created_at).toLocaleString()}</div>
                            </div>
                        ))}
                    </div>
                </ConsolePanel>
            </div>
        </ConsolePage>
    );
};

export default DeploymentWizard;

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { useLiveMode } from '../context/LiveModeContext';
import {
    Cpu, HardDrive, Wifi, WifiOff, Radio, RefreshCw, Terminal, Power, Settings, X,
    Server, Activity, Shield, Globe, Zap, ChevronRight, Save, RotateCcw, History, CheckCircle2
} from 'lucide-react';
import { fetchDeviceConfig, fetchDevicesList, fetchSystemBadges, isRequestAbortError, requestDevicePhysicalConfirmation, saveDeviceConfig, sendDeviceCommand } from '../services/api';

interface DeviceCommandRecord {
    id: string;
    deviceId: string;
    command: string;
    status: 'queued' | 'completed' | 'failed';
    message: string;
    executedBy: string;
    createdAt: string;
    completedAt?: string;
}

interface DeviceConfig {
    displayName: string;
    group: string;
    site: string;
    networkProfile: string;
    scanProfile: string;
    notes: string;
    commandPermissions: string[];
    tags: string[];
    updatedAt?: string;
}

interface Device {
    deviceId: string;
    version: string;
    chipModel: string;
    flashSize: number;
    freeHeap: number;
    sdkVersion: string;
    mode: 'online' | 'offline';
    isOnline: boolean;
    lastHeartbeat: string;
    connectedAgents: string[];
    config?: DeviceConfig;
    latestCommand?: DeviceCommandRecord | null;
    status?: {
        cpuUsage: number;
        memoryUsage: number;
        uptime: number;
        wifiRssi: number;
    };
    systemInfo?: {
        hostname: string;
        os: string;
        kernel: string;
        arch: string;
    };
    transport?: 'wifi' | 'usb_serial' | 'ethernet' | 'unknown';
    externalPowerPresent?: boolean;
    secureElementPresent?: boolean;
    pendingPhysicalApproval?: boolean;
    interlockState?: 'disabled' | 'armed' | 'asserted' | 'fault' | 'unknown';
    hostActionState?: 'idle' | 'running' | 'awaiting_confirmation' | 'completed' | 'failed' | 'unknown';
    physicalAuth?: {
        hasPublicKey?: boolean;
        monotonicCounter?: number;
        lastConfirmedAt?: string | null;
    };
    latestConfirmationSession?: {
        id: string;
        commandType: string;
        status: string;
        createdAt: string;
        confirmedAt?: string;
    } | null;
    securitySummary?: {
        asset?: {
            riskScore?: number;
            findingsOpen?: number;
            alertsOpen?: number;
        } | null;
        findings?: { title: string; severity: string }[];
        alerts?: { title: string; status: string }[];
        actions?: { title: string; status: string }[];
        latestCommand?: DeviceCommandRecord | null;
    };
}

const PHYSICAL_CONFIRMATION_COMMANDS = new Set([
    'reboot',
    'host_remove',
    'recovery_flash',
    'factory_reset',
    'diagnostic_unlock',
    'vehicle_ota_flash',
    'cellular_breaker_assert',
    'cellular_breaker_release'
]);

const defaultConfig = (device: Device): DeviceConfig => ({
    displayName: device.config?.displayName || device.deviceId,
    group: device.config?.group || 'default',
    site: device.config?.site || device.systemInfo?.hostname || 'unassigned',
    networkProfile: device.config?.networkProfile || 'cloud-mesh',
    scanProfile: device.config?.scanProfile || 'balanced',
    notes: device.config?.notes || '',
    commandPermissions: device.config?.commandPermissions || ['collect', 'sync-config', 'host_backup', 'host_install', 'reboot', 'host_remove', 'recovery_flash', 'factory_reset', 'diagnostic_unlock', 'vehicle_ota_flash', 'cellular_breaker_assert', 'cellular_breaker_release'],
    tags: device.config?.tags || []
});

const formatDateTime = (value?: string) => (value ? new Date(value).toLocaleString() : '--');

const commandLabel = (command: string) => {
    switch (command) {
        case 'collect':
            return 'Collect';
        case 'host_backup':
            return 'Backup';
        case 'host_remove':
            return 'Remove';
        case 'recovery_flash':
            return 'Recovery Flash';
        case 'factory_reset':
            return 'Factory Reset';
        case 'host_install':
            return 'Install';
        case 'diagnostic_unlock':
            return 'Diagnostic Unlock';
        case 'vehicle_ota_flash':
            return 'Vehicle OTA';
        case 'cellular_breaker_assert':
            return 'Assert Breaker';
        case 'cellular_breaker_release':
            return 'Release Breaker';
        default:
            return command;
    }
};

const DeviceCard = ({
    device,
    onCommand,
    onOpenSettings,
    onSelect,
    isSelected,
    commandBusy
}: {
    device: Device;
    onCommand: (cmd: string) => void;
    onOpenSettings: () => void;
    onSelect: () => void;
    isSelected: boolean;
    commandBusy?: string | null;
}) => {
    const { t } = useLanguage();
    const latestCommand = device.latestCommand || device.securitySummary?.latestCommand || null;

    return (
        <div
            onClick={onSelect}
            className={`bg-card border rounded-xl p-5 shadow-sm transition-all cursor-pointer hover:shadow-md ${
                isSelected ? 'border-primary ring-2 ring-primary/20' : 'border-border hover:border-primary/30'
            }`}
        >
            <div className="flex justify-between items-start mb-4 gap-3">
                <div className="flex items-center gap-3">
                    <div className={`p-2.5 rounded-lg ${device.isOnline
                        ? device.mode === 'online'
                            ? 'bg-blue-500/10 text-blue-500'
                            : 'bg-emerald-500/10 text-emerald-500'
                        : 'bg-muted text-muted-foreground'}`}>
                        <Radio size={20} />
                    </div>
                    <div>
                        <div className="font-semibold text-foreground">{device.config?.displayName || device.deviceId}</div>
                        <div className="text-xs text-muted-foreground">{device.chipModel} v{device.version}</div>
                    </div>
                </div>

                <div className={`flex items-center gap-1.5 px-2 py-1 rounded-full text-xs font-medium ${device.isOnline
                    ? device.mode === 'online'
                        ? 'bg-blue-500/10 text-blue-500 border border-blue-500/20'
                        : 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20'
                    : 'bg-muted text-muted-foreground border border-border'}`}>
                    {device.isOnline ? (
                        device.mode === 'online' ? <><Wifi size={12} /> {t('devices.cloud_mode')}</> : <><WifiOff size={12} /> {t('devices.no_agents')}</>
                    ) : (
                        <><span className="w-1.5 h-1.5 rounded-full bg-muted-foreground"></span> Disconnected</>
                    )}
                </div>
            </div>

            {device.status && (
                <div className="grid grid-cols-3 gap-3 mb-4">
                    <div className="bg-muted/30 rounded-lg p-2 text-center">
                        <Cpu size={14} className="mx-auto mb-1 text-muted-foreground" />
                        <div className="text-sm font-medium text-foreground">{device.status.cpuUsage}%</div>
                        <div className="text-xxs text-muted-foreground">{t('devices.cpu')}</div>
                    </div>
                    <div className="bg-muted/30 rounded-lg p-2 text-center">
                        <HardDrive size={14} className="mx-auto mb-1 text-muted-foreground" />
                        <div className="text-sm font-medium text-foreground">{device.status.memoryUsage.toFixed(0)}%</div>
                        <div className="text-xxs text-muted-foreground">{t('devices.memory')}</div>
                    </div>
                    <div className="bg-muted/30 rounded-lg p-2 text-center">
                        <Activity size={14} className="mx-auto mb-1 text-muted-foreground" />
                        <div className="text-sm font-medium text-foreground">{device.status.wifiRssi}dBm</div>
                        <div className="text-xxs text-muted-foreground">{t('devices.signal')}</div>
                    </div>
                </div>
            )}

            <div className="mb-4 space-y-2 text-sm">
                <div className="flex items-center justify-between">
                    <span className="text-muted-foreground">{t('devices.connected_agents')}</span>
                    <span className="font-medium text-foreground flex items-center gap-1"><Server size={14} className="text-primary" />{device.connectedAgents.length}</span>
                </div>
                <div className="flex items-center justify-between">
                    <span className="text-muted-foreground">Risk</span>
                    <span className="font-medium text-foreground">{device.securitySummary?.asset?.riskScore || 0}</span>
                </div>
                <div className="text-xs text-muted-foreground">
                    Latest action: <span className="text-foreground">{latestCommand?.command || 'none'}</span>
                </div>
                <div className="text-xs text-muted-foreground">
                    Link: <span className="text-foreground">{device.transport || 'unknown'}</span> · Secure element: <span className="text-foreground">{device.secureElementPresent ? 'present' : 'missing'}</span>
                </div>
                <div className="text-xs text-muted-foreground">
                    Power / Interlock: <span className="text-foreground">{device.externalPowerPresent ? 'external DC' : 'USB only'}</span> · <span className="text-foreground">{device.interlockState || 'unknown'}</span>
                </div>
            </div>

            <div className="flex gap-2">
                <button
                    onClick={(e) => { e.stopPropagation(); onCommand('collect'); }}
                    disabled={!device.isOnline || commandBusy === 'collect'}
                    className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-medium bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                >
                    <Zap size={12} /> {commandBusy === 'collect' ? 'Running...' : 'Collect'}
                </button>
                <button
                    onClick={(e) => { e.stopPropagation(); onCommand('host_backup'); }}
                    disabled={!device.isOnline || commandBusy === 'host_backup'}
                    className="flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-medium bg-muted text-foreground rounded-lg hover:bg-muted/80 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                >
                    <Save size={12} />
                </button>
                <button
                    onClick={(e) => { e.stopPropagation(); onCommand('reboot'); }}
                    disabled={!device.isOnline || commandBusy === 'reboot'}
                    className="flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-medium bg-muted text-foreground rounded-lg hover:bg-muted/80 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                >
                    <Power size={12} />
                </button>
                <button
                    onClick={(e) => { e.stopPropagation(); onOpenSettings(); }}
                    className="flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-medium bg-muted text-foreground rounded-lg hover:bg-muted/80 transition-all"
                >
                    <Settings size={12} />
                </button>
                <div onClick={(e) => e.stopPropagation()} className="ml-auto">
                    <Link to={`/devices/board-status/${device.deviceId}`} className="px-3 py-2 text-xs font-medium bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 rounded-lg hover:bg-emerald-500/20 transition-all flex items-center gap-1">
                        <Activity size={12} /> View Status
                    </Link>
                </div>
            </div>
        </div>
    );
};

const Devices = () => {
    const { t } = useLanguage();
    const { liveModeEnabled } = useLiveMode();
    const [devices, setDevices] = useState<Device[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedDevice, setSelectedDevice] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [actionMessage, setActionMessage] = useState<string | null>(null);
    const [settingsOpen, setSettingsOpen] = useState(false);
    const [settingsDeviceId, setSettingsDeviceId] = useState<string | null>(null);
    const [configDraft, setConfigDraft] = useState<DeviceConfig | null>(null);
    const [configLoading, setConfigLoading] = useState(false);
    const [configSaving, setConfigSaving] = useState(false);
    const [commandHistory, setCommandHistory] = useState<DeviceCommandRecord[]>([]);
    const [commandBusyByDevice, setCommandBusyByDevice] = useState<Record<string, string | null>>({});
    const [platformBadges, setPlatformBadges] = useState({ agents: 0, alerts: 0, devices: 0, agentMonitor: 0, traffic: 0, scanner: 0 });

    const fetchDevices = async (signal?: AbortSignal) => {
        setLoading(true);
        setError(null);
        try {
            const [data, badges] = await Promise.all([
                fetchDevicesList(signal),
                fetchSystemBadges(signal),
            ]);
            if (signal?.aborted) {
                return;
            }
            const nextDevices = data.devices || [];
            setDevices(nextDevices);
            setPlatformBadges(badges);
            setSelectedDevice((current) => current && nextDevices.some((device: Device) => device.deviceId === current) ? current : nextDevices[0]?.deviceId || null);
        } catch (e: any) {
            if (!isRequestAbortError(e, signal)) {
                setError(e.message || 'FG-DEVICES-LIST-ERR');
                setDevices([]);
            }
        } finally {
            if (!signal?.aborted) {
                setLoading(false);
            }
        }
    };

    const loadDeviceConfig = async (deviceId: string) => {
        setConfigLoading(true);
        try {
            const response = await fetchDeviceConfig(deviceId);
            setConfigDraft(response?.config || null);
            setCommandHistory(response?.commandHistory || []);
            setError(null);
        } catch (e: any) {
            setError(e.message || 'FG-DEVICE-CONFIG-ERR');
        } finally {
            setConfigLoading(false);
        }
    };

    useEffect(() => {
        const controller = new AbortController();
        void fetchDevices(controller.signal);
        return () => controller.abort();
    }, []);

    useEffect(() => {
        let disposed = false;
        let controller: AbortController | null = null;

        if (!liveModeEnabled) {
            return;
        }

        const refresh = async () => {
            const nextController = new AbortController();
            controller?.abort();
            controller = nextController;
            await fetchDevices(nextController.signal);
        };

        const interval = setInterval(() => {
            if (!disposed) {
                void refresh();
            }
        }, 10000);

        return () => {
            disposed = true;
            controller?.abort();
            clearInterval(interval);
        };
    }, [liveModeEnabled]);

    const openSettings = async (device: Device) => {
        setSelectedDevice(device.deviceId);
        setSettingsDeviceId(device.deviceId);
        setSettingsOpen(true);
        setConfigDraft(defaultConfig(device));
        await loadDeviceConfig(device.deviceId);
    };

    const closeSettings = () => {
        setSettingsOpen(false);
        setSettingsDeviceId(null);
        setConfigDraft(null);
        setCommandHistory([]);
    };

    const sendCommand = async (deviceId: string, command: string) => {
        setError(null);
        setActionMessage(null);
        setCommandBusyByDevice((current) => ({ ...current, [deviceId]: command }));
        try {
            if (PHYSICAL_CONFIRMATION_COMMANDS.has(command)) {
                const response = await requestDevicePhysicalConfirmation(deviceId, command);
                setActionMessage(
                    response?.data?.status === 'pending_physical_confirmation'
                        ? `${commandLabel(command)} is waiting for board confirmation`
                        : `${commandLabel(command)} confirmation session created`
                );
            } else {
                const response = await sendDeviceCommand(deviceId, command);
                setActionMessage(response.message || `Command ${command} completed`);
            }
            await fetchDevices();
            if (settingsOpen && settingsDeviceId === deviceId) {
                await loadDeviceConfig(deviceId);
            }
        } catch (e: any) {
            setError(e.message || 'FG-DEVICE-CMD-ERR');
        } finally {
            setCommandBusyByDevice((current) => ({ ...current, [deviceId]: null }));
        }
    };

    const saveSettings = async () => {
        if (!settingsDeviceId || !configDraft) {
            return;
        }

        setConfigSaving(true);
        setError(null);
        try {
            const response = await saveDeviceConfig(settingsDeviceId, configDraft);
            setConfigDraft(response?.config || configDraft);
            setCommandHistory(response?.commandHistory || []);
            setActionMessage('Device configuration saved');
            await fetchDevices();
        } catch (e: any) {
            setError(e.message || 'FG-DEVICE-SAVE-ERR');
        } finally {
            setConfigSaving(false);
        }
    };

    const selectedDeviceData = devices.find((device) => device.deviceId === selectedDevice) || null;
    const activeConfigDevice = devices.find((device) => device.deviceId === settingsDeviceId) || null;

    const onlineCount = devices.filter((device) => device.isOnline).length;
    const cloudCount = devices.filter((device) => device.isOnline && device.mode === 'online').length;
    const findingsOpen = devices.reduce((sum, device) => sum + (device.securitySummary?.asset?.findingsOpen || 0), 0);
    const recentActions = useMemo(
        () => devices.filter((device) => device.latestCommand || device.securitySummary?.latestCommand).length,
        [devices]
    );

    return (
        <div className="relative p-6 space-y-6 max-w-[1600px] mx-auto">
            <div className="flex justify-between items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-foreground tracking-tight">{t('devices.title')}</h2>
                    <p className="text-sm text-muted-foreground mt-1">设备、命令、配置与安全上下文统一查看。</p>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => void fetchDevices()} className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-card border border-border text-foreground rounded-lg hover:bg-muted/50 hover:border-primary/30 transition-all shadow-sm">
                        <RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Refresh
                    </button>
                </div>
            </div>

            {actionMessage && (
                <div className="flex items-center gap-2 rounded-lg border border-emerald-500/20 bg-emerald-500/10 px-4 py-3 text-sm text-emerald-600 dark:text-emerald-300">
                    <CheckCircle2 size={16} />
                    <span>{actionMessage}</span>
                </div>
            )}

            {error && <div className="p-3 rounded border border-red-500/30 text-red-300 bg-red-500/10 text-sm">{error}</div>}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-gradient-to-br from-card to-muted/20 border border-border rounded-xl p-5 shadow-sm">
                    <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-primary/10 text-primary rounded-lg"><Radio size={18} /></div><span className="text-sm font-medium text-muted-foreground">{t('devices.total_gateways')}</span></div>
                    <div className="text-3xl font-bold text-foreground">{devices.length}</div>
                </div>
                <div className="bg-gradient-to-br from-card to-muted/20 border border-border rounded-xl p-5 shadow-sm">
                    <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-emerald-500/10 text-emerald-500 rounded-lg"><Wifi size={18} /></div><span className="text-sm font-medium text-muted-foreground">{t('devices.online')}</span></div>
                    <div className="text-3xl font-bold text-foreground">{onlineCount}</div>
                </div>
                <div className="bg-gradient-to-br from-card to-muted/20 border border-border rounded-xl p-5 shadow-sm">
                    <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-blue-500/10 text-blue-500 rounded-lg"><Globe size={18} /></div><span className="text-sm font-medium text-muted-foreground">{t('devices.cloud_mode')}</span></div>
                    <div className="text-3xl font-bold text-foreground">{cloudCount}</div>
                </div>
                <div className="bg-gradient-to-br from-card to-muted/20 border border-border rounded-xl p-5 shadow-sm">
                    <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-orange-500/10 text-orange-500 rounded-lg"><Shield size={18} /></div><span className="text-sm font-medium text-muted-foreground">Open Findings / Actions</span></div>
                    <div className="text-3xl font-bold text-foreground">{findingsOpen} / {recentActions}</div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2">
                    <div className="bg-card border border-border rounded-xl p-5 shadow-sm">
                        <div className="flex justify-between items-center mb-5"><h3 className="font-semibold text-foreground flex items-center gap-2"><Radio size={16} className="text-primary" /> Edge Gateways</h3></div>
                        {loading ? (
                            <div className="text-center py-12 text-muted-foreground">Loading gateways...</div>
                        ) : devices.length === 0 ? (
                            <div className="rounded-lg border border-dashed border-border/50 bg-muted/20 px-6 py-8">
                                <div className="text-center">
                                    <div className="text-base font-medium text-foreground">{t('devices.no_gateways')}</div>
                                    <p className="mt-2 text-sm text-muted-foreground">
                                        平台当前运行正常，但该租户尚未注册任何物联网网关。生产模式下不会再注入演示设备，因此这里会真实反映接入现状。
                                    </p>
                                </div>
                                <div className="mt-6 grid grid-cols-1 gap-3 md:grid-cols-3">
                                    <div className="rounded-xl border border-border bg-card px-4 py-3 text-sm">
                                        <div className="text-xs text-muted-foreground">在线智能体</div>
                                        <div className="mt-1 text-2xl font-semibold text-foreground">{platformBadges.agentMonitor || platformBadges.agents}</div>
                                    </div>
                                    <div className="rounded-xl border border-border bg-card px-4 py-3 text-sm">
                                        <div className="text-xs text-muted-foreground">活跃告警</div>
                                        <div className="mt-1 text-2xl font-semibold text-foreground">{platformBadges.alerts}</div>
                                    </div>
                                    <div className="rounded-xl border border-border bg-card px-4 py-3 text-sm">
                                        <div className="text-xs text-muted-foreground">进行中扫描</div>
                                        <div className="mt-1 text-2xl font-semibold text-foreground">{platformBadges.scanner}</div>
                                    </div>
                                </div>
                                <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
                                    <Link
                                        to="/deploy"
                                        className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-muted/40"
                                    >
                                        <Server size={14} />
                                        查看接入与部署
                                    </Link>
                                    <button
                                        onClick={() => void fetchDevices()}
                                        className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-muted/40"
                                    >
                                        <RefreshCw size={14} />
                                        重新检查接入状态
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {devices.map((device) => (
                                    <DeviceCard
                                        key={device.deviceId}
                                        device={device}
                                        onCommand={(cmd) => sendCommand(device.deviceId, cmd)}
                                        onOpenSettings={() => void openSettings(device)}
                                        onSelect={() => setSelectedDevice(device.deviceId)}
                                        isSelected={selectedDevice === device.deviceId}
                                        commandBusy={commandBusyByDevice[device.deviceId] || null}
                                    />
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                <div className="space-y-6">
                    {selectedDeviceData ? (
                        <>
                            <div className="bg-card border border-border rounded-xl p-5 shadow-sm">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="font-semibold text-foreground flex items-center gap-2"><Terminal size={16} className="text-primary" /> Device Details</h3>
                                    <button onClick={() => void openSettings(selectedDeviceData)} className="rounded-lg border border-border bg-muted/20 px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted/40">
                                        Edit Config
                                    </button>
                                </div>
                                <dl className="space-y-3 text-sm">
                                    <div className="flex justify-between"><dt className="text-muted-foreground">{t('devices.device_id')}</dt><dd className="font-medium text-foreground">{selectedDeviceData.deviceId}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Display Name</dt><dd className="font-medium text-foreground">{selectedDeviceData.config?.displayName || selectedDeviceData.deviceId}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Group</dt><dd className="font-medium text-foreground">{selectedDeviceData.config?.group || '--'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Site</dt><dd className="font-medium text-foreground">{selectedDeviceData.config?.site || '--'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">{t('devices.chip_model')}</dt><dd className="font-medium text-foreground">{selectedDeviceData.chipModel}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">{t('devices.flash_size')}</dt><dd className="font-medium text-foreground">{(selectedDeviceData.flashSize / 1024 / 1024).toFixed(0)} MB</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">{t('devices.free_heap')}</dt><dd className="font-medium text-foreground">{(selectedDeviceData.freeHeap / 1024).toFixed(0)} KB</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">{t('devices.sdk_version')}</dt><dd className="font-medium text-foreground">{selectedDeviceData.sdkVersion}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Transport</dt><dd className="font-medium text-foreground">{selectedDeviceData.transport || 'unknown'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">External Power</dt><dd className="font-medium text-foreground">{selectedDeviceData.externalPowerPresent ? 'Present' : 'USB only'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Secure Element</dt><dd className="font-medium text-foreground">{selectedDeviceData.secureElementPresent ? 'Present' : 'Missing'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Interlock</dt><dd className="font-medium text-foreground">{selectedDeviceData.interlockState || 'unknown'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Host Action State</dt><dd className="font-medium text-foreground">{selectedDeviceData.hostActionState || 'unknown'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Physical Confirm</dt><dd className="font-medium text-foreground">{selectedDeviceData.pendingPhysicalApproval ? 'Pending' : 'Idle'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">Verification Key</dt><dd className="font-medium text-foreground">{selectedDeviceData.physicalAuth?.hasPublicKey ? 'Loaded' : 'Not loaded'}</dd></div>
                                    <div className="flex justify-between"><dt className="text-muted-foreground">{t('devices.last_heartbeat')}</dt><dd className="font-medium text-foreground">{new Date(selectedDeviceData.lastHeartbeat).toLocaleTimeString()}</dd></div>
                                </dl>
                                <div className="mt-4 grid grid-cols-2 gap-2">
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'host_backup')}
                                        className="rounded-lg border border-border bg-muted/20 px-3 py-2 text-xs font-medium text-foreground hover:bg-muted/40"
                                    >
                                        Host Backup
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'reboot')}
                                        className="rounded-lg border border-amber-500/20 bg-amber-500/10 px-3 py-2 text-xs font-medium text-amber-600 dark:text-amber-300 hover:bg-amber-500/20"
                                    >
                                        Arm Reboot
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'host_remove')}
                                        className="rounded-lg border border-rose-500/20 bg-rose-500/10 px-3 py-2 text-xs font-medium text-rose-600 dark:text-rose-300 hover:bg-rose-500/20"
                                    >
                                        Require Remove Confirm
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'recovery_flash')}
                                        className="rounded-lg border border-border bg-muted/20 px-3 py-2 text-xs font-medium text-foreground hover:bg-muted/40"
                                    >
                                        Recovery Flash
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'diagnostic_unlock')}
                                        className="rounded-lg border border-sky-500/20 bg-sky-500/10 px-3 py-2 text-xs font-medium text-sky-700 hover:bg-sky-500/20 dark:text-sky-300"
                                    >
                                        Diagnostic Unlock
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'vehicle_ota_flash')}
                                        className="rounded-lg border border-indigo-500/20 bg-indigo-500/10 px-3 py-2 text-xs font-medium text-indigo-700 hover:bg-indigo-500/20 dark:text-indigo-300"
                                    >
                                        Vehicle OTA Flash
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'cellular_breaker_assert')}
                                        className="rounded-lg border border-rose-500/20 bg-rose-500/10 px-3 py-2 text-xs font-medium text-rose-700 hover:bg-rose-500/20 dark:text-rose-300"
                                    >
                                        Assert Cellular Breaker
                                    </button>
                                    <button
                                        onClick={() => void sendCommand(selectedDeviceData.deviceId, 'cellular_breaker_release')}
                                        className="rounded-lg border border-emerald-500/20 bg-emerald-500/10 px-3 py-2 text-xs font-medium text-emerald-700 hover:bg-emerald-500/20 dark:text-emerald-300"
                                    >
                                        Release Cellular Breaker
                                    </button>
                                </div>
                            </div>
                            <div className="bg-card border border-border rounded-xl p-5 shadow-sm">
                                <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2"><History size={16} className="text-primary" /> Latest Command</h3>
                                {(selectedDeviceData.latestCommand || selectedDeviceData.securitySummary?.latestCommand) ? (
                                    <div className="rounded-lg border border-border bg-muted/20 p-3 text-sm">
                                        <div className="font-medium text-foreground">{(selectedDeviceData.latestCommand || selectedDeviceData.securitySummary?.latestCommand)?.command}</div>
                                        <div className="mt-1 text-muted-foreground">{(selectedDeviceData.latestCommand || selectedDeviceData.securitySummary?.latestCommand)?.message}</div>
                                        <div className="mt-2 text-xs text-muted-foreground">{formatDateTime((selectedDeviceData.latestCommand || selectedDeviceData.securitySummary?.latestCommand)?.createdAt)}</div>
                                    </div>
                                ) : (
                                    <p className="text-sm text-muted-foreground text-center py-4">No commands have been executed yet.</p>
                                )}
                            </div>
                            <div className="bg-card border border-border rounded-xl p-5 shadow-sm">
                                <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2"><Server size={16} className="text-primary" /> Connected Agents</h3>
                                {selectedDeviceData.connectedAgents.length > 0 ? (
                                    <ul className="space-y-2">
                                        {selectedDeviceData.connectedAgents.map((agent) => (
                                            <li key={agent} className="flex items-center justify-between p-2 bg-muted/30 rounded-lg"><span className="text-sm font-medium text-foreground">{agent}</span><ChevronRight size={16} className="text-muted-foreground" /></li>
                                        ))}
                                    </ul>
                                ) : <p className="text-sm text-muted-foreground text-center py-4">{t('devices.no_agents')}</p>}
                            </div>
                            <div className="bg-card border border-border rounded-xl p-5 shadow-sm">
                                <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2"><Shield size={16} className="text-primary" /> Security Context</h3>
                                {selectedDeviceData.securitySummary?.asset ? (
                                    <div className="space-y-3 text-sm">
                                        <div className="grid grid-cols-3 gap-3">
                                            <div className="rounded-lg bg-muted/30 p-3 text-center">
                                                <div className="text-xs text-muted-foreground">Risk</div>
                                                <div className="mt-1 text-lg font-semibold text-foreground">{selectedDeviceData.securitySummary.asset.riskScore || 0}</div>
                                            </div>
                                            <div className="rounded-lg bg-muted/30 p-3 text-center">
                                                <div className="text-xs text-muted-foreground">Findings</div>
                                                <div className="mt-1 text-lg font-semibold text-foreground">{selectedDeviceData.securitySummary.asset.findingsOpen || 0}</div>
                                            </div>
                                            <div className="rounded-lg bg-muted/30 p-3 text-center">
                                                <div className="text-xs text-muted-foreground">Alerts</div>
                                                <div className="mt-1 text-lg font-semibold text-foreground">{selectedDeviceData.securitySummary.asset.alertsOpen || 0}</div>
                                            </div>
                                        </div>
                                        <div>
                                            <div className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">Recent Findings</div>
                                            {(selectedDeviceData.securitySummary.findings || []).slice(0, 3).map((finding) => (
                                                <div key={`${finding.title}-${finding.severity}`} className="mb-2 rounded-lg border border-border bg-muted/20 px-3 py-2">
                                                    <div className="text-sm font-medium text-foreground">{finding.title}</div>
                                                    <div className="text-xs text-muted-foreground">{finding.severity}</div>
                                                </div>
                                            ))}
                                            {(selectedDeviceData.securitySummary.findings || []).length === 0 && <div className="text-xs text-muted-foreground">No linked findings yet.</div>}
                                        </div>
                                    </div>
                                ) : (
                                    <p className="text-sm text-muted-foreground text-center py-4">This device has not been linked to a security asset yet.</p>
                                )}
                            </div>
                        </>
                    ) : (
                        <div className="bg-card border border-border rounded-xl p-5 shadow-sm text-center py-12"><Shield size={32} className="mx-auto mb-3 text-muted-foreground" /><p className="text-muted-foreground">{t('devices.select_device')}</p></div>
                    )}
                </div>
            </div>

            {settingsOpen && activeConfigDevice && (
                <div className="fixed inset-0 z-40 bg-black/40 backdrop-blur-[1px]">
                    <div className="absolute inset-y-0 right-0 w-full max-w-xl border-l border-border bg-background shadow-2xl">
                        <div className="flex h-full flex-col">
                            <div className="flex items-center justify-between border-b border-border px-6 py-4">
                                <div>
                                    <div className="text-lg font-semibold text-foreground">Device Settings</div>
                                    <div className="text-sm text-muted-foreground">{activeConfigDevice.deviceId}</div>
                                </div>
                                <button onClick={closeSettings} className="rounded-lg border border-border p-2 text-muted-foreground hover:bg-muted/20 hover:text-foreground">
                                    <X size={16} />
                                </button>
                            </div>

                            <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
                                {configLoading || !configDraft ? (
                                    <div className="text-sm text-muted-foreground">Loading device configuration...</div>
                                ) : (
                                    <>
                                        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                                            <label className="space-y-2 text-sm"><span className="text-muted-foreground">Display Name</span><input value={configDraft.displayName} onChange={(e) => setConfigDraft({ ...configDraft, displayName: e.target.value })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                            <label className="space-y-2 text-sm"><span className="text-muted-foreground">Group</span><input value={configDraft.group} onChange={(e) => setConfigDraft({ ...configDraft, group: e.target.value })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                            <label className="space-y-2 text-sm"><span className="text-muted-foreground">Site</span><input value={configDraft.site} onChange={(e) => setConfigDraft({ ...configDraft, site: e.target.value })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                            <label className="space-y-2 text-sm"><span className="text-muted-foreground">Network Profile</span><input value={configDraft.networkProfile} onChange={(e) => setConfigDraft({ ...configDraft, networkProfile: e.target.value })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                            <label className="space-y-2 text-sm"><span className="text-muted-foreground">Scan Profile</span><input value={configDraft.scanProfile} onChange={(e) => setConfigDraft({ ...configDraft, scanProfile: e.target.value })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                            <label className="space-y-2 text-sm"><span className="text-muted-foreground">Allowed Commands</span><input value={configDraft.commandPermissions.join(', ')} onChange={(e) => setConfigDraft({ ...configDraft, commandPermissions: e.target.value.split(',').map((item) => item.trim()).filter(Boolean) })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                        </div>

                                        <label className="space-y-2 text-sm block"><span className="text-muted-foreground">Tags</span><input value={configDraft.tags.join(', ')} onChange={(e) => setConfigDraft({ ...configDraft, tags: e.target.value.split(',').map((item) => item.trim()).filter(Boolean) })} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>
                                        <label className="space-y-2 text-sm block"><span className="text-muted-foreground">Notes</span><textarea value={configDraft.notes} onChange={(e) => setConfigDraft({ ...configDraft, notes: e.target.value })} rows={4} className="w-full rounded-lg border border-border bg-card px-3 py-2 text-foreground" /></label>

                                        <div className="rounded-xl border border-border bg-muted/20 p-4">
                                            <div className="mb-3 flex items-center gap-2 text-sm font-medium text-foreground"><History size={14} className="text-primary" /> Recent Command History</div>
                                            <div className="space-y-2">
                                                {commandHistory.length === 0 ? (
                                                    <div className="text-sm text-muted-foreground">No command history recorded yet.</div>
                                                ) : (
                                                    commandHistory.map((entry) => (
                                                        <div key={entry.id} className="rounded-lg border border-border bg-card px-3 py-2">
                                                            <div className="flex items-center justify-between gap-3">
                                                                <div className="text-sm font-medium text-foreground">{entry.command}</div>
                                                                <div className="text-xs text-muted-foreground">{formatDateTime(entry.createdAt)}</div>
                                                            </div>
                                                            <div className="mt-1 text-xs text-muted-foreground">{entry.message}</div>
                                                        </div>
                                                    ))
                                                )}
                                            </div>
                                        </div>
                                    </>
                                )}
                            </div>

                            <div className="border-t border-border px-6 py-4">
                                <div className="flex items-center justify-between gap-3">
                                    <button onClick={() => activeConfigDevice && setConfigDraft(defaultConfig(activeConfigDevice))} className="flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground hover:bg-muted/20">
                                        <RotateCcw size={14} /> Reset
                                    </button>
                                    <div className="flex gap-3">
                                        <button onClick={closeSettings} className="rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground hover:bg-muted/20">Cancel</button>
                                        <button onClick={saveSettings} disabled={configSaving || !configDraft} className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 disabled:opacity-50">
                                            <Save size={14} /> {configSaving ? 'Saving...' : 'Save'}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Devices;

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { ArrowRight, History } from 'lucide-react';
import { fetchFixHistory } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';

const FixHistory = () => {
    const [rows, setRows] = useState<any[]>([]);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    const load = async () => {
        setLoading(true);
        setError(null);
        try {
            const data = await fetchFixHistory(100);
            setRows(data || []);
        } catch (e: any) {
            setError(e.message || 'FG-FIX-HISTORY-LIST');
            setRows([]);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        void load();
    }, []);

    return (
        <ConsolePage title="修复历史" subtitle="查看历史修复记录、阶段状态与任务详情。">
            {error && <div className="rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}
            <ConsolePanel title="修复记录" subtitle="点击按钮进入稳定详情页查看完整记录。" icon={History} iconTone="primary">
                {loading ? (
                    <ConsoleEmptyState title="正在加载历史记录" />
                ) : rows.length === 0 ? (
                    <ConsoleEmptyState title="当前没有可展示的历史记录" />
                ) : (
                    <div className="space-y-3">
                        {rows.map((row) => (
                            <div key={row.id} className="flex items-center justify-between rounded-xl border border-border bg-muted/15 p-4">
                                <div>
                                    <div className="break-all font-mono text-xs text-foreground">{row.id}</div>
                                    <div className="mt-1 text-xs text-muted-foreground">{row.status} / {row.phase} / {row.progress}%</div>
                                    <div className="mt-1 text-[11px] text-muted-foreground">{new Date(row.createdAt).toLocaleString()}</div>
                                </div>
                                <Link to={`/history/${row.id}`} className="flex items-center gap-1 rounded-lg border border-border bg-card px-3 py-2 text-xs font-medium text-foreground hover:bg-muted/30">
                                    查看详情
                                    <ArrowRight size={12} />
                                </Link>
                            </div>
                        ))}
                    </div>
                )}
            </ConsolePanel>
        </ConsolePage>
    );
};

export default FixHistory;

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { ArrowLeft, History, Wrench } from 'lucide-react';
import { fetchFixHistoryDetail } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';
import StructuredDataView from '../components/StructuredDataView';

const FixHistoryDetail = () => {
    const { id = '' } = useParams();
    const [detail, setDetail] = useState<any>(null);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        fetchFixHistoryDetail(id)
            .then((response) => setDetail(response || null))
            .catch((err: any) => setError(err.message || 'FG-HISTORY-DETAIL'));
    }, [id]);

    return (
        <ConsolePage title="修复记录详情" subtitle={`查看记录 ${id} 的状态、阶段与发现项`} actions={<Link to="/history" className="flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground hover:bg-muted/30"><ArrowLeft size={14} />返回修复历史</Link>}>
            {error && <div className="rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}
            {!detail ? <ConsoleEmptyState title="正在加载修复记录" /> : (
                <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
                    <div className="space-y-6 xl:col-span-4">
                        <ConsolePanel title={detail.id} subtitle="任务摘要" icon={History} iconTone="primary">
                            <div className="space-y-3 text-sm">
                                <div className="rounded-lg border border-border bg-muted/15 p-3">状态：<span className="font-semibold text-foreground">{detail.status}</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">阶段：<span className="font-semibold text-foreground">{detail.phase}</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">进度：<span className="font-semibold text-foreground">{detail.progress}%</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">错误：<span className="font-semibold text-foreground">{detail.error || '无'}</span></div>
                            </div>
                        </ConsolePanel>
                    </div>
                    <div className="space-y-6 xl:col-span-8">
                        <ConsolePanel title="修复摘要" subtitle="结果统计与剩余工作" icon={Wrench} iconTone="warning">
                            <StructuredDataView value={detail.summary || {}} emptyLabel="暂无修复摘要" />
                        </ConsolePanel>
                        <ConsolePanel title="发现项" subtitle="本次记录关联的风险与修复对象" icon={History} iconTone="neutral">
                            {(detail.findings || []).length > 0 ? (
                                <div className="space-y-3">
                                    {(detail.findings || []).map((finding: any, index: number) => (
                                        <div key={`${finding.title}-${index}`} className="rounded-lg border border-border bg-muted/15 p-4">
                                            <div className="font-medium text-foreground">{finding.title}</div>
                                            <div className="mt-1 text-sm text-muted-foreground">{finding.description}</div>
                                            <div className="mt-2 text-xs text-muted-foreground">{finding.target_type} · {finding.target} · {finding.severity}</div>
                                        </div>
                                    ))}
                                </div>
                            ) : <ConsoleEmptyState title="暂无关联发现项" />}
                        </ConsolePanel>
                    </div>
                </div>
            )}
        </ConsolePage>
    );
};

export default FixHistoryDetail;

import React, { useEffect, useState } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { useTheme } from '../context/ThemeContext';
import { useDemo } from '../context/DemoContext';
import { useNavigate } from 'react-router-dom';
import { User, Lock, ArrowRight, ArrowLeft, CheckCircle, Info } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import Logo from '../components/Logo';
import { COMPANY_NAME_CN, COMPANY_NAME_EN } from '../config/branding';
import { fetchSystemCapabilities, login } from '../services/api';

type ToastState = {
    msg: string;
    type: 'success' | 'info';
};

type DevLoginPreset = {
    id: string;
    label: string;
    detail: string;
    email: string;
    password: string;
};

const DEV_LOGIN_PRESETS: DevLoginPreset[] = [
    {
        id: 'admin',
        label: 'Admin',
        detail: 'Ultra admin',
        email: 'dev-admin@aetherguard.local',
        password: 'DevAdmin!2026',
    },
    {
        id: 'starter',
        label: 'Starter',
        detail: 'Starter tenant',
        email: 'starter@aetherguard.local',
        password: 'DevStarter!2026',
    },
    {
        id: 'pro',
        label: 'Pro',
        detail: 'Pro tenant',
        email: 'pro@aetherguard.local',
        password: 'DevPro!2026',
    },
    {
        id: 'ultra',
        label: 'Ultra',
        detail: 'Ultra tenant',
        email: 'ultra@aetherguard.local',
        password: 'DevUltra!2026',
    },
];

const Login = () => {
    const navigate = useNavigate();
    const { t } = useLanguage();
    useTheme();
    const { refreshDemoState } = useDemo();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isDevModeOpen, setIsDevModeOpen] = useState(false);
    const [devLoginEnabled, setDevLoginEnabled] = useState(false);
    const [toast, setToast] = useState<ToastState | null>(null);

    useEffect(() => {
        const controller = new AbortController();

        fetchSystemCapabilities(controller.signal)
            .then((mode) => {
                if (!controller.signal.aborted) {
                    setDevLoginEnabled(Boolean(mode.devLoginEnabled));
                }
            })
            .catch(() => {
                if (!controller.signal.aborted) {
                    setDevLoginEnabled(false);
                }
            });

        return () => controller.abort();
    }, []);

    const showToast = (msg: string, type: ToastState['type'] = 'info') => {
        setToast({ msg, type });
        setTimeout(() => setToast(null), 3000);
    };

    const handleApplyPreset = (preset: DevLoginPreset) => {
        setEmail(preset.email);
        setPassword(preset.password);
        showToast(`${preset.label} credentials filled`);
    };

    const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            await login({ email, password });
            showToast('Login succeeded. Redirecting...', 'success');

            await refreshDemoState();

            setTimeout(() => {
                navigate('/dashboard');
            }, 800);
        } catch (error: any) {
            let errorMsg = error.message || 'Login failed. Check your network connection.';
            if (errorMsg.includes('invalid_credentials') || errorMsg.includes('401')) {
                errorMsg = 'Incorrect email or password.';
            }
            showToast(errorMsg);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen overflow-x-hidden overflow-y-auto bg-background text-foreground">
            <AnimatePresence>
                {toast && (
                    <motion.div
                        initial={{ opacity: 0, x: 100 }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: 100 }}
                        className={`fixed bottom-5 right-5 z-50 flex items-center gap-3 rounded-xl border px-5 py-3 shadow-sm ${
                            toast.type === 'success' ? 'border-emerald-500/25 bg-card' : 'border-border bg-card'
                        }`}
                    >
                        {toast.type === 'success' ? <CheckCircle className="h-5 w-5 text-emerald-500" /> : <Info className="h-5 w-5 text-primary" />}
                        <span className="text-sm font-medium text-foreground">{toast.msg}</span>
                    </motion.div>
                )}
            </AnimatePresence>

            <div className="mx-auto flex min-h-screen w-full max-w-6xl items-center px-4 py-8 md:px-8">
                <div className="grid w-full gap-6 lg:grid-cols-[1.25fr_460px]">
                    <motion.section
                        initial={{ opacity: 0, y: 16 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="hidden overflow-hidden rounded-3xl border border-border bg-card shadow-sm lg:flex"
                    >
                        <div className="flex flex-1 flex-col justify-between p-8 xl:p-10">
                            <div className="space-y-8">
                                <div className="flex items-center justify-between gap-4">
                                    <div className="space-y-1">
                                        <Logo className="origin-left" />
                                        <div className="text-xs text-muted-foreground">{COMPANY_NAME_CN}</div>
                                    </div>
                                    <span className="rounded-full border border-border bg-muted/30 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">
                                        Operations Console
                                    </span>
                                </div>
                                <div className="space-y-4">
                                    <h1 className="max-w-2xl text-4xl font-bold tracking-tight text-foreground">
                                        Security operations for gateways, agents, scans, and response workflows.
                                    </h1>
                                    <p className="max-w-xl text-sm leading-6 text-muted-foreground">
                                        Sign in to the same monitoring console used for device health, alert handling, deployment, and incident history.
                                    </p>
                                </div>
                                <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                                    <div className="rounded-2xl border border-border bg-muted/20 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground">Gateways</div>
                                        <div className="mt-2 text-3xl font-bold tracking-tight text-foreground">24</div>
                                        <div className="mt-2 text-xs text-muted-foreground">Field inspection points online</div>
                                    </div>
                                    <div className="rounded-2xl border border-border bg-muted/20 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground">Agents</div>
                                        <div className="mt-2 text-3xl font-bold tracking-tight text-foreground">7</div>
                                        <div className="mt-2 text-xs text-muted-foreground">Inference and response roles available</div>
                                    </div>
                                    <div className="rounded-2xl border border-border bg-muted/20 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground">Alerts</div>
                                        <div className="mt-2 text-3xl font-bold tracking-tight text-foreground">3</div>
                                        <div className="mt-2 text-xs text-muted-foreground">Items currently awaiting review</div>
                                    </div>
                                </div>
                            </div>

                            <div className="rounded-2xl border border-border bg-muted/15 p-5">
                                <div className="text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Workspace Notes</div>
                                <div className="mt-3 grid gap-3 text-sm text-muted-foreground">
                                    <div className="flex items-start gap-3">
                                        <div className="mt-1 h-2 w-2 rounded-full bg-emerald-500" />
                                        <p>Device telemetry and board status use the same console shell after sign-in.</p>
                                    </div>
                                    <div className="flex items-start gap-3">
                                        <div className="mt-1 h-2 w-2 rounded-full bg-amber-500" />
                                        <p>Demo mode and development presets remain available without changing the authentication flow.</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </motion.section>

                    <motion.div
                        initial={{ opacity: 0, scale: 0.98 }}
                        animate={{ opacity: 1, scale: 1 }}
                        className="w-full rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"
                    >
                        <div className="mb-8 space-y-4">
                            <div className="inline-flex items-center gap-2 lg:hidden">
                                <Logo />
                            </div>
                            <div className="space-y-2">
                                <div className="text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Account Access</div>
                                <h2 className="text-2xl font-bold tracking-tight text-foreground">Control console login</h2>
                                <p className="text-sm text-muted-foreground">Sign in with your enterprise account.</p>
                            </div>
                        </div>

                        {devLoginEnabled && (
                            <div className="mb-6 rounded-2xl border border-border bg-muted/15 p-4">
                                <button
                                    type="button"
                                    data-testid="dev-login-toggle"
                                    onClick={() => setIsDevModeOpen((open) => !open)}
                                    className="flex w-full items-center justify-between gap-3 text-left"
                                >
                                    <div>
                                        <div className="text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Dev Access</div>
                                        <div className="mt-1 text-sm text-foreground">Fill local test accounts instantly.</div>
                                    </div>
                                    <span className="text-xs text-muted-foreground">{isDevModeOpen ? 'Hide' : 'Show'}</span>
                                </button>

                                <AnimatePresence initial={false}>
                                    {isDevModeOpen && (
                                        <motion.div
                                            initial={{ opacity: 0, height: 0 }}
                                            animate={{ opacity: 1, height: 'auto' }}
                                            exit={{ opacity: 0, height: 0 }}
                                            className="overflow-hidden"
                                        >
                                            <div className="grid grid-cols-2 gap-2 pt-4">
                                                {DEV_LOGIN_PRESETS.map((preset) => (
                                                    <button
                                                        key={preset.id}
                                                        type="button"
                                                        data-testid={`dev-preset-${preset.id}`}
                                                        onClick={() => handleApplyPreset(preset)}
                                                        className="rounded-xl border border-border bg-card px-3 py-3 text-left transition-colors hover:border-primary/25 hover:bg-muted/20"
                                                    >
                                                        <div className="text-sm font-semibold text-foreground">{preset.label}</div>
                                                        <div className="text-xs text-muted-foreground">{preset.detail}</div>
                                                        <div className="mt-2 break-all font-mono text-[11px] text-muted-foreground">{preset.email}</div>
                                                    </button>
                                                ))}
                                            </div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </div>
                        )}

                        <form onSubmit={handleLogin} className="space-y-6">
                            <div>
                                <label className="mb-1 block text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground">Email / Username</label>
                                <div className="relative">
                                    <User className="absolute left-3 top-3 h-5 w-5 text-muted-foreground" />
                                    <input
                                        type="text"
                                        name="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        autoComplete="username"
