import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import {
    Activity,
    Bot,
    CheckCircle2,
    Clock3,
    RefreshCw,
    Shield,
    ShieldAlert,
    XCircle
} from 'lucide-react';
import { useLiveMode } from '../context/LiveModeContext';
import { ConsoleEmptyState, ConsolePage, ConsolePanel, ConsoleStatCard } from '../components/ConsolePrimitives';
import {
    approveRuleCandidate,
    fetchRuleCandidate,
    fetchRuleCandidates,
    fetchRuleEvents,
    fetchRules,
    isRequestAbortError,
    rejectRuleCandidate
} from '../services/api';
import type { DetectionEventRecord, RuleCandidateRecord, RuleRecord, RuleSummary } from '../types/api';

const emptySummary: RuleSummary = {
    totalRules: 0,
    activeRules: 0,
    pendingCandidates: 0,
    approvedCandidates: 0,
    rejectedCandidates: 0,
    ruleHitRate: 0,
    aiEscalationRate: 0,
    avgProcessingTimeMs: 0,
    localAICount: 0,
    cloudAICount: 0,
    topRules: []
};

const statusTone: Record<RuleCandidateRecord['status'], string> = {
    pending: 'border-amber-500/20 bg-amber-500/10 text-amber-700 dark:text-amber-300',
    approved: 'border-emerald-500/20 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300',
    rejected: 'border-slate-500/20 bg-slate-500/10 text-slate-700 dark:text-slate-300'
};

const severityTone: Record<RuleRecord['severity'], string> = {
    critical: 'text-rose-600 dark:text-rose-300',
    high: 'text-orange-600 dark:text-orange-300',
    medium: 'text-amber-600 dark:text-amber-300',
    low: 'text-sky-600 dark:text-sky-300'
};

const formatPercent = (value: number) => `${(value * 100).toFixed(1)}%`;

const formatJson = (value: unknown) => JSON.stringify(value || {}, null, 2);

const Rules = () => {
    const { liveModeEnabled } = useLiveMode();
    const [summary, setSummary] = useState<RuleSummary>(emptySummary);
    const [rules, setRules] = useState<RuleRecord[]>([]);
    const [candidates, setCandidates] = useState<RuleCandidateRecord[]>([]);
    const [events, setEvents] = useState<DetectionEventRecord[]>([]);
    const [selectedCandidateId, setSelectedCandidateId] = useState<string | null>(null);
    const [selectedCandidate, setSelectedCandidate] = useState<RuleCandidateRecord | null>(null);
    const [statusFilter, setStatusFilter] = useState<'all' | RuleCandidateRecord['status']>('all');
    const [channelFilter, setChannelFilter] = useState<'all' | RuleCandidateRecord['channel']>('all');
    const [familyFilter, setFamilyFilter] = useState<'all' | RuleCandidateRecord['attackFamily']>('all');
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [actionError, setActionError] = useState<string | null>(null);
    const [syncMessage, setSyncMessage] = useState<string | null>(null);

    const loadPage = async (signal?: AbortSignal) => {
        try {
            const [rulesPayload, candidatesPayload, eventsPayload] = await Promise.all([
                fetchRules(undefined, signal),
                fetchRuleCandidates(undefined, signal),
                fetchRuleEvents({ limit: 30 }, signal)
            ]);

            if (signal?.aborted) {
                return;
            }

            setRules(rulesPayload.rules || []);
            setSummary(rulesPayload.summary || emptySummary);
            setCandidates(candidatesPayload || []);
            setEvents(eventsPayload || []);
            setError(null);
        } catch (nextError: any) {
            if (!isRequestAbortError(nextError, signal)) {
                setError(nextError?.message || 'FG-RULES-PAGE');
            }
        } finally {
            if (!signal?.aborted) {
                setLoading(false);
            }
        }
    };

    useEffect(() => {
        let disposed = false;
        let controller: AbortController | null = null;

        const refresh = async () => {
            const nextController = new AbortController();
            controller?.abort();
            controller = nextController;
            await loadPage(nextController.signal);
        };

        void refresh();

        if (!liveModeEnabled) {
            return () => {
                disposed = true;
                controller?.abort();
            };
        }

        const interval = window.setInterval(() => {
            if (!disposed) {
                void refresh();
            }
        }, 8000);

        return () => {
            disposed = true;
            controller?.abort();
            window.clearInterval(interval);
        };
    }, [liveModeEnabled]);

    const filteredCandidates = useMemo(() => candidates.filter((candidate) => {
        if (statusFilter !== 'all' && candidate.status !== statusFilter) {
            return false;
        }
        if (channelFilter !== 'all' && candidate.channel !== channelFilter) {
            return false;
        }
        if (familyFilter !== 'all' && candidate.attackFamily !== familyFilter) {
            return false;
        }
        return true;
    }), [candidates, statusFilter, channelFilter, familyFilter]);

    const attackFamilies = useMemo(() => Array.from(new Set(candidates.map((candidate) => candidate.attackFamily))), [candidates]);

    useEffect(() => {
        if (filteredCandidates.length === 0) {
            setSelectedCandidateId(null);
            setSelectedCandidate(null);
            return;
        }

        const stillVisible = filteredCandidates.some((candidate) => candidate.candidateId === selectedCandidateId);
        if (!stillVisible) {
            setSelectedCandidateId(filteredCandidates[0].candidateId);
        }
    }, [filteredCandidates, selectedCandidateId]);

    useEffect(() => {
        if (!selectedCandidateId) {
            setSelectedCandidate(null);
            return;
        }

        const controller = new AbortController();
        fetchRuleCandidate(selectedCandidateId, controller.signal)
            .then((candidate) => {
                if (!controller.signal.aborted) {
                    setSelectedCandidate(candidate);
                }
            })
            .catch((nextError) => {
                if (!isRequestAbortError(nextError, controller.signal)) {
                    setActionError((nextError as Error)?.message || 'FG-RULE-CANDIDATE-DETAIL');
                }
            });

        return () => controller.abort();
    }, [selectedCandidateId]);

    const refreshAll = async () => {
        setLoading(true);
        await loadPage();
    };

    const handleApproval = async () => {
        if (!selectedCandidate) {
            return;
        }

        const reason = window.prompt('Approval note (optional)', selectedCandidate.reviewReason || '');
        if (reason === null) {
            return;
        }

        try {
            setActionError(null);
            const result = await approveRuleCandidate(selectedCandidate.candidateId, reason || undefined);
            if (result.sync && selectedCandidate.channel === 'agent') {
                setSyncMessage(`Agent sync ${result.sync.succeeded}/${result.sync.attempted} succeeded.`);
            } else {
                setSyncMessage('Candidate approved and rule set refreshed.');
            }
            await loadPage();
            const detail = await fetchRuleCandidate(selectedCandidate.candidateId);
            setSelectedCandidate(detail);
        } catch (nextError: any) {
            setActionError(nextError?.message || 'FG-RULE-CANDIDATE-APPROVE');
        }
    };

    const handleReject = async () => {
        if (!selectedCandidate) {
            return;
        }

        const reason = window.prompt('Rejection note (optional)', selectedCandidate.reviewReason || '');
        if (reason === null) {
            return;
        }

        try {
            setActionError(null);
            setSyncMessage(null);
            await rejectRuleCandidate(selectedCandidate.candidateId, reason || undefined);
            await loadPage();
            const detail = await fetchRuleCandidate(selectedCandidate.candidateId);
            setSelectedCandidate(detail);
        } catch (nextError: any) {
            setActionError(nextError?.message || 'FG-RULE-CANDIDATE-REJECT');
        }
    };

    const activeRules = useMemo(() => rules.filter((rule) => rule.enabled), [rules]);

    return (
        <ConsolePage
            title="Rule Operations"
            subtitle="Rule-first detection, AI escalation, candidate review, and delivery telemetry in one admin console."
            actions={(
                <div className="flex flex-wrap items-center gap-2">
                    <Link
                        to="/alerts"
                        className="rounded-lg border border-border bg-card px-3 py-2 text-sm font-medium text-foreground transition-colors hover:bg-muted/30"
                    >
                        Open Alerts
                    </Link>
                    <button
                        onClick={() => void refreshAll()}
                        className="inline-flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90"
                    >
                        <RefreshCw size={14} />
                        Refresh
                    </button>
                </div>
            )}
        >
            {error && <div className="rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}
            {actionError && <div className="rounded-lg border border-amber-500/20 bg-amber-500/10 p-3 text-sm text-amber-700 dark:text-amber-300">{actionError}</div>}
            {syncMessage && <div className="rounded-lg border border-emerald-500/20 bg-emerald-500/10 p-3 text-sm text-emerald-700 dark:text-emerald-300">{syncMessage}</div>}

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
                <ConsoleStatCard icon={Shield} label="Active Rules" value={summary.activeRules} hint={`${summary.totalRules} total`} tone="primary" />
                <ConsoleStatCard icon={Bot} label="Pending Candidates" value={summary.pendingCandidates} hint={`${summary.approvedCandidates} approved / ${summary.rejectedCandidates} rejected`} tone="warning" />
                <ConsoleStatCard icon={Activity} label="Rule Hit Rate" value={formatPercent(summary.ruleHitRate)} hint={`AI escalation ${formatPercent(summary.aiEscalationRate)}`} tone="success" />
                <ConsoleStatCard icon={Clock3} label="Average Detection Time" value={`${summary.avgProcessingTimeMs.toFixed(1)} ms`} hint="Across recent detection events" tone="neutral" />
                <ConsoleStatCard icon={Bot} label="Local AI Calls" value={summary.localAICount} hint={`Cloud ${summary.cloudAICount}`} tone="primary" />
                <ConsoleStatCard icon={ShieldAlert} label="Top Rule Hits" value={summary.topRules[0]?.hitCount || 0} hint={summary.topRules[0]?.name || 'No recent hits'} tone="danger" />
            </div>

            <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
                <div className="space-y-6 xl:col-span-7">
                    <ConsolePanel
                        title="Rule Candidates"
                        subtitle="Review AI-learned malicious patterns before they are promoted into active rules."
                        icon={Bot}
                        iconTone="warning"
                        headerAction={(
                            <div className="flex flex-wrap gap-2">
                                {(['all', 'pending', 'approved', 'rejected'] as const).map((value) => (
                                    <button
                                        key={value}
                                        onClick={() => setStatusFilter(value)}
                                        className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                                            statusFilter === value
                                                ? 'border border-primary bg-primary text-primary-foreground'
                                                : 'border border-border bg-card text-muted-foreground hover:text-foreground'
                                        }`}
                                    >
                                        {value}
                                    </button>
                                ))}
                                {(['all', 'http_api', 'packet', 'agent'] as const).map((value) => (
                                    <button
                                        key={value}
                                        onClick={() => setChannelFilter(value)}
                                        className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                                            channelFilter === value
                                                ? 'border border-primary bg-primary text-primary-foreground'
                                                : 'border border-border bg-card text-muted-foreground hover:text-foreground'
                                        }`}
                                    >
                                        {value}
                                    </button>
                                ))}
                                <select
                                    value={familyFilter}
                                    onChange={(event) => setFamilyFilter(event.target.value as typeof familyFilter)}
                                    className="rounded-lg border border-border bg-card px-3 py-1.5 text-xs text-foreground"
                                >
                                    <option value="all">all families</option>
                                    {attackFamilies.map((family) => (
                                        <option key={family} value={family}>{family}</option>
                                    ))}
                                </select>
                            </div>
                        )}
                    >
                        {loading && candidates.length === 0 ? (
                            <div className="text-sm text-muted-foreground">Loading rule candidates...</div>
                        ) : filteredCandidates.length === 0 ? (
                            <ConsoleEmptyState title="No candidates match the current filters." description="AI-learned candidates will appear here after high-risk allowed traffic is escalated and judged malicious." />
                        ) : (
                            <div className="space-y-3">
                                {filteredCandidates.map((candidate) => {
                                    const selected = candidate.candidateId === selectedCandidateId;
                                    return (
                                        <button
                                            key={candidate.candidateId}
                                            type="button"
                                            onClick={() => setSelectedCandidateId(candidate.candidateId)}
                                            className={`w-full rounded-xl border p-4 text-left transition-colors ${
                                                selected
                                                    ? 'border-primary bg-primary/5'
                                                    : 'border-border bg-muted/10 hover:bg-muted/20'
                                            }`}
                                        >
                                            <div className="flex flex-wrap items-start justify-between gap-3">
                                                <div>
                                                    <div className="text-sm font-semibold text-foreground">{candidate.name}</div>
                                                    <div className="mt-1 flex flex-wrap gap-2 text-[11px] text-muted-foreground">
                                                        <span>{candidate.channel}</span>
                                                        <span>{candidate.attackFamily}</span>
                                                        <span>{candidate.sampleCount} samples</span>
                                                        <span>{(candidate.aiConfidence * 100).toFixed(0)}% AI confidence</span>
                                                    </div>
                                                </div>
                                                <span className={`rounded-full border px-2 py-1 text-[11px] font-semibold uppercase ${statusTone[candidate.status]}`}>
                                                    {candidate.status}
                                                </span>
                                            </div>
                                            <div className="mt-3 text-xs text-muted-foreground">
                                                Updated {new Date(candidate.updatedAt).toLocaleString()}
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        )}
                    </ConsolePanel>

                    <ConsolePanel
                        title="Candidate Detail"
                        subtitle="Matcher, latest evidence, AI reasoning, and review history for the selected candidate."
                        icon={ShieldAlert}
                        iconTone="danger"
                        headerAction={selectedCandidate ? (
                            <div className="flex gap-2">
                                <button
                                    onClick={() => void handleApproval()}
                                    disabled={selectedCandidate.status === 'approved'}
                                    className="inline-flex items-center gap-2 rounded-lg bg-emerald-600 px-3 py-2 text-xs font-semibold text-white hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-50"
                                >
                                    <CheckCircle2 size={14} />
                                    Approve
                                </button>
                                <button
                                    onClick={() => void handleReject()}
                                    disabled={selectedCandidate.status === 'rejected'}
                                    className="inline-flex items-center gap-2 rounded-lg bg-rose-600 px-3 py-2 text-xs font-semibold text-white hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-50"
                                >
                                    <XCircle size={14} />
                                    Reject
                                </button>
                            </div>
                        ) : undefined}
                    >
                        {!selectedCandidate ? (
                            <ConsoleEmptyState title="Select a candidate to inspect matcher and evidence." description="The detail panel keeps approval and rejection on the same page so the review loop stays short." />
                        ) : (
                            <div className="space-y-4">
                                <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
                                    <div className="rounded-xl border border-border bg-muted/10 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Candidate</div>
                                        <div className="mt-2 text-base font-semibold text-foreground">{selectedCandidate.name}</div>
                                        <div className="mt-2 space-y-1 text-sm text-muted-foreground">
                                            <div>Channel: <span className="font-medium text-foreground">{selectedCandidate.channel}</span></div>
                                            <div>Attack family: <span className="font-medium text-foreground">{selectedCandidate.attackFamily}</span></div>
                                            <div>AI confidence: <span className="font-medium text-foreground">{(selectedCandidate.aiConfidence * 100).toFixed(1)}%</span></div>
                                            <div>Samples: <span className="font-medium text-foreground">{selectedCandidate.sampleCount}</span></div>
                                        </div>
                                    </div>
                                    <div className="rounded-xl border border-border bg-muted/10 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Review History</div>
                                        <div className="mt-2 space-y-1 text-sm text-muted-foreground">
                                            <div>Status: <span className="font-medium text-foreground">{selectedCandidate.status}</span></div>
                                            <div>Created: <span className="font-medium text-foreground">{new Date(selectedCandidate.createdAt).toLocaleString()}</span></div>
                                            <div>Updated: <span className="font-medium text-foreground">{new Date(selectedCandidate.updatedAt).toLocaleString()}</span></div>
                                            <div>Reviewed by: <span className="font-medium text-foreground">{selectedCandidate.reviewedBy || '-'}</span></div>
                                            <div>Reviewed at: <span className="font-medium text-foreground">{selectedCandidate.reviewedAt ? new Date(selectedCandidate.reviewedAt).toLocaleString() : '-'}</span></div>
                                            <div>Review note: <span className="font-medium text-foreground">{selectedCandidate.reviewReason || '-'}</span></div>
                                            <div>Approved rule: <span className="font-medium text-foreground">{selectedCandidate.approvedRuleId || '-'}</span></div>
                                        </div>
                                    </div>
                                </div>
                                <div className="rounded-xl border border-border bg-muted/10 p-4">
                                    <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">AI Reasoning</div>
                                    <p className="mt-2 text-sm leading-6 text-foreground">{selectedCandidate.reasoning}</p>
                                </div>
                                <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
                                    <div className="rounded-xl border border-border bg-muted/10 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Matcher</div>
                                        <pre className="mt-2 overflow-x-auto whitespace-pre-wrap break-all rounded-lg border border-border bg-card p-3 text-xs text-muted-foreground">{formatJson(selectedCandidate.matcher)}</pre>
                                    </div>
                                    <div className="rounded-xl border border-border bg-muted/10 p-4">
                                        <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Latest Evidence</div>
                                        <pre className="mt-2 overflow-x-auto whitespace-pre-wrap break-all rounded-lg border border-border bg-card p-3 text-xs text-muted-foreground">{formatJson(selectedCandidate.latestEvidence)}</pre>
                                    </div>
                                </div>
                            </div>
                        )}
                    </ConsolePanel>
                </div>

                <div className="space-y-6 xl:col-span-5">
                    <ConsolePanel
                        title="Active Rules"
                        subtitle="Approved candidate rules sit here alongside seed and dynamic rules already active in the pipeline."
                        icon={Shield}
                        iconTone="primary"
                    >
                        {activeRules.length === 0 ? (
                            <ConsoleEmptyState title="No active rules available." description="Approved and seed rules will appear here once the detection pipeline has been initialized." />
                        ) : (
                            <div className="space-y-3">
                                {activeRules.slice(0, 12).map((rule) => (
                                    <div key={rule.ruleId} className="rounded-xl border border-border bg-muted/10 p-4">
                                        <div className="flex flex-wrap items-start justify-between gap-3">
                                            <div>
                                                <div className="text-sm font-semibold text-foreground">{rule.name}</div>
                                                <div className="mt-1 flex flex-wrap gap-2 text-[11px] text-muted-foreground">
                                                    <span>{rule.scope}</span>
                                                    <span>{rule.action}</span>
                                                    <span>{rule.source}</span>
                                                    <span>priority {rule.priority}</span>
                                                </div>
                                            </div>
                                            <span className={`text-xs font-semibold uppercase ${severityTone[rule.severity]}`}>{rule.severity}</span>
                                        </div>
                                        {rule.description && <p className="mt-2 text-sm text-muted-foreground">{rule.description}</p>}
                                    </div>
                                ))}
                            </div>
                        )}
                    </ConsolePanel>

                    <ConsolePanel
                        title="Recent Detection Events"
                        subtitle="Use the event stream to verify the full loop: rule hit, AI escalation, candidate generation, and operator decision."
                        icon={Activity}
                        iconTone="success"
                    >
                        {events.length === 0 ? (
                            <ConsoleEmptyState title="No detection events yet." description="Events are recorded when rules match, AI review is triggered, or candidates are generated." />
                        ) : (
                            <div className="space-y-3">
                                {events.map((event) => (
                                    <div key={event.detectionEventId} className="rounded-xl border border-border bg-muted/10 p-4">
                                        <div className="flex flex-wrap items-start justify-between gap-3">
                                            <div>
                                                <div className="text-sm font-semibold text-foreground">{event.channel} / {event.verdict}</div>
                                                <div className="mt-1 flex flex-wrap gap-2 text-[11px] text-muted-foreground">
                                                    <span>{event.attackFamily}</span>
                                                    <span>risk {event.riskScore.toFixed(2)}</span>
                                                    <span>{event.processingTimeMs} ms</span>
                                                    <span>{event.escalatedToAI ? 'AI escalated' : 'Rules only'}</span>
                                                </div>
                                            </div>
                                            <div className="text-xs text-muted-foreground">{new Date(event.createdAt).toLocaleString()}</div>
                                        </div>
                                        <div className="mt-2 text-xs text-muted-foreground">
                                            Source: <span className="font-medium text-foreground">{event.decisionSource}</span>
                                            {event.candidateId && <span> | Candidate {event.candidateId}</span>}
                                            {event.aiVerdict && <span> | AI {event.aiVerdict} {(event.aiConfidence || 0) * 100 >= 0 ? `(${((event.aiConfidence || 0) * 100).toFixed(0)}%)` : ''}</span>}
                                        </div>
                                        <pre className="mt-3 overflow-x-auto whitespace-pre-wrap break-all rounded-lg border border-border bg-card p-3 text-xs text-muted-foreground">{formatJson(event.requestSnapshot)}</pre>
                                    </div>
                                ))}
                            </div>
                        )}
                    </ConsolePanel>
                </div>
            </div>
        </ConsolePage>
    );
};

export default Rules;

import { useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { Activity, AlertTriangle, CheckCircle, Globe, History, Server, Shield, StopCircle, Wrench } from 'lucide-react';
import { clsx } from 'clsx';
import { cancelScanTask, createScanRemediationAction, createScanTask, fetchScanHistory, fetchScanTask, fetchScanTaskResults } from '../services/api';
import { useWebSocket } from '../context/WebSocketContext';
import { useLiveMode } from '../context/LiveModeContext';
import { ConsoleEmptyState, ConsolePage, ConsolePanel, ConsoleStatCard } from '../components/ConsolePrimitives';
import type { ScanAssetGroup, SecurityFinding } from '../types/api';

type ScanHistoryItem = {
    id: string;
    status: string;
    phase: string;
    progress: number;
    createdAt: string;
    completedAt?: string;
};

type ScanResultPayload = {
    data?: {
        findings?: SecurityFinding[];
        assetGroups?: ScanAssetGroup[];
        timeline?: { eventType: string; payload: Record<string, any>; createdAt: string }[];
        summary?: Record<string, any>;
        urlFindings?: any[];
        hostFindings?: any[];
        nucleiFindings?: any[];
    };
};

const STATUS_LABELS: Record<string, string> = {
    idle: '空闲',
    pending: '排队中',
    running: '执行中',
    completed: '已完成',
    failed: '失败',
    cancelled: '已取消'
};

const PHASE_LABELS: Record<string, string> = {
    queued: '等待执行',
    'url-scan': 'Web 指纹与 TLS',
    'host-scan': '主机与服务',
    'nuclei-scan': '模板验证',
    finalizing: '结果归档',
    done: '已结束'
};

const severityTone: Record<string, string> = {
    critical: 'bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/20',
    high: 'bg-orange-500/10 text-orange-600 dark:text-orange-400 border-orange-500/20',
    medium: 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20',
    low: 'bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20'
};

function normalizeLegacyFindings(data: NonNullable<ScanResultPayload['data']>): SecurityFinding[] {
    const merged = [...(data.urlFindings || []), ...(data.hostFindings || []), ...(data.nucleiFindings || [])];
    return merged.map((finding: any, index) => ({
        findingId: `legacy-${index}`,
        assetId: undefined,
        sourceType: 'scanner',
        sourceRef: '',
        target: finding.target || 'unknown',
        category: finding.sourceEngine || 'scanner',
        severity: finding.severity || 'medium',
        status: 'open',
        title: finding.title,
        description: finding.description,
        evidence: finding.evidence || {},
        remediation: {},
        occurrenceCount: 1,
        firstSeenAt: finding.createdAt || new Date().toISOString(),
        lastSeenAt: finding.createdAt || new Date().toISOString()
    }));
}

const Scanner = () => {
    const { subscribe, connected } = useWebSocket();
    const { liveModeEnabled } = useLiveMode();

    const [taskId, setTaskId] = useState<string | null>(null);
    const [status, setStatus] = useState<string>('idle');
    const [phase, setPhase] = useState<string>('queued');
    const [progress, setProgress] = useState(0);
    const [error, setError] = useState<string | null>(null);
    const [logs, setLogs] = useState<string[]>([]);
    const [urls, setUrls] = useState('');
    const [includeSystem, setIncludeSystem] = useState(true);
    const [includeWeb, setIncludeWeb] = useState(true);
    const [includePorts, setIncludePorts] = useState(true);
    const [history, setHistory] = useState<ScanHistoryItem[]>([]);
    const [findings, setFindings] = useState<SecurityFinding[]>([]);
    const [assetGroups, setAssetGroups] = useState<ScanAssetGroup[]>([]);
    const [timeline, setTimeline] = useState<Array<{ eventType: string; payload: Record<string, any>; createdAt: string }>>([]);
    const [selectedFindingId, setSelectedFindingId] = useState<string | null>(null);
    const [actionMessage, setActionMessage] = useState<string | null>(null);

    const logRef = useRef<HTMLDivElement>(null);
    const isRunning = status === 'pending' || status === 'running';

    const selectedFinding = useMemo(
        () => findings.find((item) => item.findingId === selectedFindingId) || findings[0] || null,
        [findings, selectedFindingId]
    );

    const summary = useMemo(() => {
        return findings.reduce(
            (acc, finding) => {
                acc.total += 1;
                acc[finding.severity] += 1;
                return acc;
            },
            { total: 0, critical: 0, high: 0, medium: 0, low: 0 }
        );
    }, [findings]);

    const addLog = (message: string) => {
        const timestamp = new Date().toLocaleTimeString('zh-CN', { hour12: false });
        setLogs((prev) => [...prev, `[${timestamp}] ${message}`]);
    };

    const loadHistory = async () => {
        try {
            const rows = await fetchScanHistory(20);
            setHistory(rows || []);
        } catch {
            setHistory([]);
        }
    };

    const loadResults = async (id: string) => {
        const response = await fetchScanTaskResults(id);
        const data = response?.data || {};
        const nextFindings: SecurityFinding[] = data.findings || normalizeLegacyFindings(data);
        setFindings(nextFindings);
        setAssetGroups(
            data.assetGroups ||
                nextFindings.reduce((groups: ScanAssetGroup[], finding: SecurityFinding) => {
                    const existing = groups.find((group) => group.target === finding.target);
                    if (existing) {
                        existing.findings.push(finding);
                        existing.severities[finding.severity] = (existing.severities[finding.severity] || 0) + 1;
                        return groups;
                    }
                    groups.push({
                        assetId: finding.assetId,
                        target: finding.target,
                        category: finding.category,
                        findings: [finding],
                        severities: { [finding.severity]: 1 }
                    });
                    return groups;
                }, [])
        );
        setTimeline(data.timeline || []);
        setSelectedFindingId((current) => current || nextFindings[0]?.findingId || null);
    };

    const loadTask = async (id: string) => {
        const response = await fetchScanTask(id);
        const task = response?.data;
        setTaskId(id);
        setStatus(task?.status || 'idle');
        setPhase(task?.phase || 'queued');
        setProgress(task?.progress || 0);
        setError(task?.error || null);
        await loadResults(id);
    };

    useEffect(() => {
        loadHistory();
    }, []);

    useEffect(() => {
        if (!taskId) return;
        if (!liveModeEnabled) {
            return;
        }
        const timer = setInterval(async () => {
            try {
                const response = await fetchScanTask(taskId);
                const task = response?.data;
                setStatus(task?.status || 'idle');
                setPhase(task?.phase || 'queued');
                setProgress(task?.progress || 0);
                if (task?.error) {
                    setError(task.error);
                }
                if (task?.status === 'completed' || task?.status === 'failed' || task?.status === 'cancelled') {
                    await loadResults(taskId);
                    await loadHistory();
                }
            } catch {
                // Keep websocket as the primary update source when polling fails.
            }
        }, 3000);
        return () => clearInterval(timer);
    }, [liveModeEnabled, taskId]);

    useEffect(() => {
        const unsubscribe = subscribe('*', (evt: any) => {
            if (!taskId || evt.taskId !== taskId) return;

            if (evt.event === 'scanner:task:started') {
                setStatus('running');
                setPhase(evt.payload?.phase || 'url-scan');
                setProgress(evt.payload?.progress ?? 0);
                addLog('扫描任务已启动');
            }

            if (evt.event === 'scanner:task:phase') {
                setPhase(evt.payload?.phase || 'queued');
                if (typeof evt.payload?.progress === 'number') {
                    setProgress(evt.payload.progress);
                }
                addLog(`进入阶段：${PHASE_LABELS[evt.payload?.phase] || evt.payload?.phase}`);
            }

            if (evt.event === 'scanner:task:progress' && typeof evt.payload?.progress === 'number') {
                setProgress(evt.payload.progress);
            }

            if (evt.event === 'scanner:task:log') {
                addLog(evt.payload?.message || '收到任务日志');
            }

            if (evt.event === 'scanner:task:completed') {
                setStatus('completed');
                setPhase('done');
                setProgress(100);
                addLog('扫描任务已完成');
                void loadResults(taskId);
                void loadHistory();
            }

            if (evt.event === 'scanner:task:failed') {
                setStatus('failed');
                setPhase('done');
                setProgress(100);
                setError(evt.payload?.error || '扫描失败');
                addLog(`扫描失败：${evt.payload?.error || '未知错误'}`);
                void loadHistory();
            }

            if (evt.event === 'scanner:task:cancelled') {
                setStatus('cancelled');
                setPhase('done');
                setProgress(100);
                addLog('扫描任务已取消');
                void loadHistory();
            }
        });
        return () => unsubscribe();
    }, [subscribe, taskId]);

    useEffect(() => {
        if (logRef.current) {
            logRef.current.scrollTop = logRef.current.scrollHeight;
        }
    }, [logs]);

    const startScan = async () => {
        setError(null);
        setActionMessage(null);
        setLogs([]);
        setFindings([]);
        setAssetGroups([]);
        setTimeline([]);
        setProgress(0);
        setStatus('pending');
        setPhase('queued');

        const urlList = urls
            .split('\n')
            .map((value) => value.trim())
            .filter(Boolean);

        try {
            const response = await createScanTask({
                enginePolicy: 'opt_then_nuclei',
                targets: {
                    urls: urlList,
                    host: {
                        mode: 'local',
                        includeSystem,
                        includeWeb,
                        includePorts
                    }
                }
            });
            const id = response?.data?.taskId;
            setTaskId(id);
            addLog(`已创建任务 ${id}`);
            await loadHistory();
        } catch (scanError: any) {
            setStatus('failed');
            setError(scanError.message || '创建扫描任务失败');
        }
    };

    const stopScan = async () => {
        if (!taskId) return;
        try {
            await cancelScanTask(taskId);
            addLog('已请求取消当前任务');
        } catch (scanError: any) {
            setError(scanError.message || '取消任务失败');
        }
    };

    const createAction = async () => {
        if (!selectedFinding?.findingId || selectedFinding.findingId.startsWith('legacy-')) {
            setActionMessage('当前发现项没有可创建的处置动作。');
            return;
        }

        try {
            const response = await createScanRemediationAction(selectedFinding.findingId);
            setActionMessage(`已创建处置动作：${response?.data?.title || '待处理修复任务'}`);
        } catch (actionError: any) {
            setActionMessage(actionError.message || '创建处置动作失败');
        }
    };

    return (
        <ConsolePage
            title="扫描中心"
            subtitle={`统一管理扫描任务、资产证据与处置建议${connected ? '，WebSocket 已连接' : '，当前使用轮询回退'}`}
            actions={
                <div className="flex gap-2">
                    {isRunning ? (
                        <button
                            onClick={stopScan}
                            className="flex items-center gap-2 rounded-lg bg-rose-600 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-rose-500"
                        >
                            <StopCircle size={16} />
                            取消任务
                        </button>
                    ) : (
                        <button
                            onClick={startScan}
                            className="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
                        >
                            启动扫描
                        </button>
                    )}
                </div>
            }
        >
            {error && <div className="rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                <ConsoleStatCard icon={History} label="当前任务" value={taskId || '-'} hint="最近一次加载或执行的扫描任务" tone="neutral" />
                <ConsoleStatCard icon={Activity} label="任务状态" value={`${STATUS_LABELS[status] || status} / ${PHASE_LABELS[phase] || phase}`} hint="实时阶段与任务状态" tone="primary" />
                <ConsoleStatCard icon={CheckCircle} label="执行进度" value={`${progress}%`} hint="任务阶段推进情况" tone="warning" />
                <ConsoleStatCard icon={AlertTriangle} label="发现总数" value={summary.total} hint={`Critical ${summary.critical} · High ${summary.high} · Medium ${summary.medium} · Low ${summary.low}`} tone="danger" />
            </div>

            <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
                <div className="xl:col-span-5">
                    <ConsolePanel title="扫描输入" subtitle="保留现有入口，但把结果深化为资产、证据与处置闭环" icon={Globe} iconTone="primary">
                        <div className="space-y-4">
                            <div>
                                <label className="text-xs text-muted-foreground">URL 目标（每行一个）</label>
                                <textarea
                                    value={urls}
                                    onChange={(event) => setUrls(event.target.value)}
                                    rows={6}
                                    className="mt-2 w-full rounded-lg border border-border bg-muted/20 px-3 py-2 font-mono text-sm text-foreground"
                                    placeholder="https://example.com&#10;https://api.example.com"
                                />
                            </div>
                            <div className="space-y-2">
                                <div className="text-xs text-muted-foreground">本机扫描范围</div>
                                <label className="flex items-center gap-2 text-sm text-foreground">
                                    <input type="checkbox" checked={includeSystem} onChange={(event) => setIncludeSystem(event.target.checked)} />
                                    系统基线与主机状态
                                </label>
                                <label className="flex items-center gap-2 text-sm text-foreground">
                                    <input type="checkbox" checked={includeWeb} onChange={(event) => setIncludeWeb(event.target.checked)} />
                                    Web 服务指纹与配置
                                </label>
                                <label className="flex items-center gap-2 text-sm text-foreground">
                                    <input type="checkbox" checked={includePorts} onChange={(event) => setIncludePorts(event.target.checked)} />
                                    端口暴露与服务探测
                                </label>
                            </div>
                        </div>
                    </ConsolePanel>
                </div>

                <div className="xl:col-span-7">
                    <ConsolePanel title="任务历史" subtitle="保留原来的历史区块，但支持重新载入完整证据" icon={History} iconTone="neutral">
                        <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
                            {history.length === 0 && <ConsoleEmptyState title="暂无扫描任务" description="执行一次扫描后，这里会保留最近任务与执行进度。" />}
                            {history.map((item) => (
                                <div key={item.id} className="rounded-lg border border-border bg-muted/15 p-3 transition-colors hover:border-border/80 hover:bg-muted/20">
                                    <button onClick={() => void loadTask(item.id)} className="w-full text-left">
                                        <div className="truncate font-mono text-xs text-foreground">{item.id}</div>
                                        <div className="mt-1 text-xs text-muted-foreground">
                                            {STATUS_LABELS[item.status] || item.status} / {PHASE_LABELS[item.phase] || item.phase} / {item.progress}%
                                        </div>
                                        <div className="mt-2 text-[11px] text-muted-foreground">{new Date(item.createdAt).toLocaleString('zh-CN')}</div>
                                    </button>
                                    <div className="mt-3 flex justify-end">
                                        <Link to={`/scanner/runs/${item.id}`} className="rounded-lg border border-border bg-card px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted/30">
                                            查看详情
                                        </Link>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </ConsolePanel>
                </div>
            </div>

            <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
                <div className="xl:col-span-4">
                    <ConsolePanel title="资产视角" subtitle="按目标聚合风险，快速判断优先级" icon={Server} iconTone="warning">
                        <div className="space-y-3 max-h-[420px] overflow-y-auto pr-1">
                            {assetGroups.length === 0 && <ConsoleEmptyState title="暂无资产结果" description="任务完成后，这里会显示按资产聚合的风险分布。" />}
                            {assetGroups.map((group) => (
                                <button
                                    key={`${group.target}-${group.assetId || 'na'}`}
                                    onClick={() => setSelectedFindingId(group.findings[0]?.findingId || null)}
                                    className="w-full rounded-lg border border-border bg-muted/15 p-3 text-left transition-colors hover:border-border/80"
                                >
                                    <div className="font-medium text-foreground">{group.target}</div>
                                    <div className="mt-1 text-xs text-muted-foreground">{group.category}</div>
                                    <div className="mt-3 flex flex-wrap gap-2">
                                        {Object.entries(group.severities).map(([key, value]) => (
                                            <span key={key} className={clsx('rounded border px-2 py-0.5 text-[10px] font-semibold uppercase', severityTone[key] || severityTone.medium)}>
                                                {key} {value}
                                            </span>
                                        ))}
                                    </div>
                                </button>
                            ))}
                        </div>
                    </ConsolePanel>
                </div>

                <div className="xl:col-span-4">
                    <ConsolePanel title="发现列表" subtitle="当前任务中所有可追踪的发现项" icon={Shield} iconTone="danger">
                        <div className="space-y-3 max-h-[420px] overflow-y-auto pr-1">
                            {findings.length === 0 && <ConsoleEmptyState title="暂无发现项" description="完成扫描后，这里会显示按严重级别排序的发现项。" />}
                            {findings.map((finding) => (
                                <button
                                    key={finding.findingId}
                                    onClick={() => setSelectedFindingId(finding.findingId)}
                                    className={clsx(
                                        'w-full rounded-lg border p-3 text-left transition-colors',
                                        selectedFinding?.findingId === finding.findingId ? 'border-primary bg-primary/5' : 'border-border bg-muted/15 hover:border-border/80'
                                    )}
                                >
                                    <div className="flex items-start justify-between gap-3">
                                        <div>
                                            <div className="font-medium text-foreground">{finding.title}</div>
                                            <div className="mt-1 text-xs text-muted-foreground">{finding.target}</div>
                                        </div>
                                        <span className={clsx('rounded border px-2 py-0.5 text-[10px] font-semibold uppercase', severityTone[finding.severity])}>
                                            {finding.severity}
                                        </span>
                                    </div>
                                    <div className="mt-2 line-clamp-2 text-sm text-muted-foreground">{finding.description}</div>
                                </button>
                            ))}
                        </div>
                    </ConsolePanel>
                </div>

                <div className="xl:col-span-4">
                    <ConsolePanel
                        title="证据与处置"
                        subtitle="在原页面里补齐证据展开、处置建议和动作创建"
                        icon={Wrench}
                        iconTone="primary"
                        headerAction={
                            <button
                                onClick={createAction}
                                disabled={!selectedFinding}
                                className="rounded-lg border border-primary/20 bg-primary/10 px-3 py-1.5 text-xs font-medium text-primary transition-colors hover:bg-primary/15 disabled:cursor-not-allowed disabled:opacity-50"
                            >
                                创建处置动作
                            </button>
                        }
                    >
                        {!selectedFinding ? (
                            <ConsoleEmptyState title="选择一个发现项" description="点击左侧发现项后，这里会展开证据与修复建议。" />
                        ) : (
                            <div className="space-y-4">
                                <div>
                                    <div className="flex items-center gap-2">
                                        <h3 className="text-sm font-semibold text-foreground">{selectedFinding.title}</h3>
                                        <span className={clsx('rounded border px-2 py-0.5 text-[10px] font-semibold uppercase', severityTone[selectedFinding.severity])}>
                                            {selectedFinding.severity}
                                        </span>
                                    </div>
                                    <p className="mt-2 text-sm text-muted-foreground">{selectedFinding.description}</p>
                                </div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">
                                    <div className="text-xs font-semibold text-foreground">证据</div>
                                    <pre className="mt-2 overflow-x-auto whitespace-pre-wrap break-all text-xs text-muted-foreground">
                                        {JSON.stringify(selectedFinding.evidence || {}, null, 2)}
                                    </pre>
                                </div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">
                                    <div className="text-xs font-semibold text-foreground">处置建议</div>
                                    <pre className="mt-2 overflow-x-auto whitespace-pre-wrap break-all text-xs text-muted-foreground">
                                        {JSON.stringify(selectedFinding.remediation || {}, null, 2)}
                                    </pre>
                                </div>
                                <div className="text-xs text-muted-foreground">
                                    状态：{selectedFinding.status} · 最近出现：{new Date(selectedFinding.lastSeenAt).toLocaleString('zh-CN')}
                                </div>
                                {actionMessage && <div className="rounded-lg border border-emerald-500/20 bg-emerald-500/10 p-3 text-sm text-emerald-600 dark:text-emerald-300">{actionMessage}</div>}
                            </div>
                        )}
                    </ConsolePanel>
                </div>
            </div>

            <ConsolePanel title="任务时间线" subtitle="保留实时日志区，但同时展示结构化阶段事件" icon={Activity} iconTone="warning">
                <div className="grid grid-cols-1 gap-4 xl:grid-cols-2">
                    <div ref={logRef} className="max-h-56 overflow-y-auto rounded-lg border border-border bg-muted/15 p-3 font-mono text-xs">
                        {logs.length === 0 ? <div className="text-muted-foreground">暂无任务日志。</div> : logs.map((log, index) => <div key={`${log}-${index}`} className="mb-1 text-emerald-600 dark:text-emerald-400">{log}</div>)}
                    </div>
                    <div className="max-h-56 overflow-y-auto rounded-lg border border-border bg-muted/15 p-3 text-xs">
                        {timeline.length === 0 ? (
                            <div className="text-muted-foreground">暂无结构化时间线。</div>
                        ) : (
                            timeline.map((item, index) => (
                                <div key={`${item.eventType}-${index}`} className="mb-3 rounded-lg border border-border bg-background/60 p-3">
                                    <div className="font-medium text-foreground">{item.eventType}</div>
                                    <div className="mt-1 text-muted-foreground">{new Date(item.createdAt).toLocaleString('zh-CN')}</div>
                                    <pre className="mt-2 overflow-x-auto whitespace-pre-wrap break-all text-[11px] text-muted-foreground">
                                        {JSON.stringify(item.payload || {}, null, 2)}
                                    </pre>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </ConsolePanel>
        </ConsolePage>
    );
};

export default Scanner;

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { Activity, ArrowLeft, Shield, Wrench } from 'lucide-react';
import { fetchScannerRunDetail } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';

const ScannerRunDetail = () => {
    const { id = '' } = useParams();
    const [detail, setDetail] = useState<any>(null);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        fetchScannerRunDetail(id)
            .then((response) => setDetail(response?.data || null))
            .catch((err: any) => setError(err.message || 'FG-SCAN-RUN-DETAIL'));
    }, [id]);

    const findings = detail?.result?.findings || [];
    const timeline = detail?.result?.timeline || [];

    return (
        <ConsolePage title="扫描任务详情" subtitle={`查看任务 ${id} 的阶段、证据与修复建议`} actions={<Link to="/scanner" className="flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground hover:bg-muted/30"><ArrowLeft size={14} />返回扫描中心</Link>}>
            {error && <div className="rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}
            {!detail ? <ConsoleEmptyState title="正在加载扫描详情" /> : (
                <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
                    <div className="space-y-6 xl:col-span-4">
                        <ConsolePanel title="任务摘要" subtitle="当前状态与执行阶段" icon={Activity} iconTone="primary">
                            <div className="space-y-3 text-sm">
                                <div className="rounded-lg border border-border bg-muted/15 p-3">状态：<span className="font-semibold text-foreground">{detail.summary?.status || '-'}</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">阶段：<span className="font-semibold text-foreground">{detail.summary?.phase || '-'}</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">进度：<span className="font-semibold text-foreground">{detail.summary?.progress || 0}%</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">错误：<span className="font-semibold text-foreground">{detail.summary?.error || '无'}</span></div>
                            </div>
                        </ConsolePanel>
                        <ConsolePanel title="任务时间线" subtitle="阶段与结构化事件" icon={Activity} iconTone="neutral">
                            <div className="space-y-3">
                                {timeline.length > 0 ? timeline.map((item: any, index: number) => (
                                    <div key={`${item.eventType}-${index}`} className="rounded-lg border border-border bg-muted/15 p-3">
                                        <div className="font-medium text-foreground">{item.eventType}</div>
                                        <div className="mt-1 text-xs text-muted-foreground">{new Date(item.createdAt).toLocaleString()}</div>
                                        <pre className="mt-2 overflow-x-auto whitespace-pre-wrap break-all text-xs text-muted-foreground">{JSON.stringify(item.payload || {}, null, 2)}</pre>
                                    </div>
                                )) : <ConsoleEmptyState title="暂无结构化事件" />}
                            </div>
                        </ConsolePanel>
                    </div>
                    <div className="space-y-6 xl:col-span-8">
                        <ConsolePanel title="发现项" subtitle="任务产生的结构化安全发现" icon={Shield} iconTone="danger">
                            <div className="space-y-3">
                                {findings.length > 0 ? findings.map((finding: any) => (
                                    <div key={finding.findingId} className="rounded-lg border border-border bg-muted/15 p-4">
                                        <div className="flex items-center justify-between gap-3">
                                            <div>
                                                <div className="font-medium text-foreground">{finding.title}</div>
                                                <div className="mt-1 text-xs text-muted-foreground">{finding.target}</div>
                                            </div>
                                            <span className="rounded border border-border px-2 py-0.5 text-xs text-muted-foreground">{finding.severity}</span>
                                        </div>
                                        <p className="mt-2 text-sm text-muted-foreground">{finding.description}</p>
                                        <pre className="mt-3 overflow-x-auto whitespace-pre-wrap break-all rounded-lg border border-border bg-card p-3 text-xs text-muted-foreground">{JSON.stringify(finding.evidence || {}, null, 2)}</pre>
                                    </div>
                                )) : <ConsoleEmptyState title="暂无发现项" description="任务完成并产生命中后，这里会显示证据与风险摘要。" />}
                            </div>
                        </ConsolePanel>
                        <ConsolePanel title="修复建议" subtitle="从证据和规则链路归纳的处置建议" icon={Wrench} iconTone="warning">
                            {findings.length > 0 ? findings.map((finding: any) => (
                                <pre key={`${finding.findingId}-remediation`} className="mb-3 overflow-x-auto whitespace-pre-wrap break-all rounded-lg border border-border bg-muted/15 p-3 text-xs text-muted-foreground">{JSON.stringify(finding.remediation || {}, null, 2)}</pre>
                            )) : <ConsoleEmptyState title="暂无处置建议" />}
                        </ConsolePanel>
                    </div>
                </div>
            )}
        </ConsolePage>
    );
};

export default ScannerRunDetail;

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { ArrowLeft, Globe, Shield, Workflow } from 'lucide-react';
import { fetchSiteDetail } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';
import StructuredDataView from '../components/StructuredDataView';

const formatBytes = (value?: number) => {
    if (!value) return '0 B';
    if (value >= 1024 * 1024) return `${(value / (1024 * 1024)).toFixed(1)} MB`;
    if (value >= 1024) return `${(value / 1024).toFixed(1)} KB`;
    return `${value} B`;
};

const SiteDetail = () => {
    const { id = '' } = useParams();
    const [detail, setDetail] = useState<any>(null);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        fetchSiteDetail(id)
            .then((response) => setDetail(response?.data || null))
            .catch((err: any) => setError(err.message || 'FG-SITE-DETAIL'));
    }, [id]);

    return (
        <ConsolePage title="站点详情" subtitle={`查看站点 ${id} 的暴露面、关联事件与安全上下文`} actions={<Link to="/sites" className="flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium text-foreground hover:bg-muted/30"><ArrowLeft size={14} />返回站点列表</Link>}>
            {error && <div className="rounded-lg border border-rose-500/20 bg-rose-500/10 p-3 text-sm text-rose-600 dark:text-rose-300">{error}</div>}
            {!detail ? <ConsoleEmptyState title="正在加载站点详情" /> : (
                <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
                    <div className="space-y-6 xl:col-span-4">
                        <ConsolePanel title={detail.domain || id} subtitle={detail.target} icon={Globe} iconTone="primary">
                            <div className="space-y-3 text-sm">
                                <div className="rounded-lg border border-border bg-muted/15 p-3">状态：<span className="font-semibold text-foreground">{detail.status || 'unknown'}</span></div>
                                <div className="rounded-lg border border-border bg-muted/15 p-3">目标：<span className="font-semibold text-foreground">{detail.target}</span></div>
                                {detail.securityOverview?.asset && <div className="rounded-lg border border-border bg-muted/15 p-3">风险分：<span className="font-semibold text-foreground">{detail.securityOverview.asset.riskScore}</span></div>}
                            </div>
                        </ConsolePanel>
                    </div>
                    <div className="space-y-6 xl:col-span-8">
                        <ConsolePanel title="关联告警" subtitle="与该站点相关的风险与事件" icon={Shield} iconTone="danger">
                            {(detail.relatedAlerts || detail.securityOverview?.alerts || []).length > 0 ? (
                                <div className="space-y-3">
                                    {(detail.relatedAlerts || detail.securityOverview?.alerts || []).map((item: any, index: number) => (
                                        <div key={item.id || item.alertId || index} className="rounded-lg border border-border bg-muted/15 p-4">
                                            <div className="font-medium text-foreground">{item.title}</div>
                                            <div className="mt-1 text-sm text-muted-foreground">{item.message || item.status}</div>
                                        </div>
                                    ))}
                                </div>
                            ) : <ConsoleEmptyState title="暂无关联告警" />}
                        </ConsolePanel>
                        <ConsolePanel title="关联流量与暴露面" subtitle="最近关联的流量与资产上下文" icon={Workflow} iconTone="warning">
                            <div className="space-y-4">
                                {(detail.relatedFlows || []).length > 0 ? (
                                    <div className="space-y-3">
                                        {(detail.relatedFlows || []).map((flow: any) => (
                                            <div key={flow.id} className="rounded-lg border border-border bg-muted/15 p-4">
                                                <div className="flex flex-wrap items-center justify-between gap-3">
                                                    <div>
                                                        <div className="font-medium text-foreground">
                                                            {flow.sourceIP}:{flow.sourcePort} → {flow.destIP}:{flow.destPort}
                                                        </div>
                                                        <div className="mt-1 text-xs text-muted-foreground">
                                                            {String(flow.protocol || '').toUpperCase()} · {flow.state || 'unknown'}
                                                        </div>
                                                    </div>
                                                    <div className="text-right text-xs text-muted-foreground">
                                                        <div>报文 {flow.packetCount ?? 0}</div>
                                                        <div>流量 {formatBytes(flow.byteCount)}</div>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <ConsoleEmptyState title="暂无关联流量" description="站点产生或命中的观测会话会展示在这里。" />
                                )}

                                {detail.securityOverview ? (
                                    <div className="rounded-lg border border-border bg-muted/15 p-4">
                                        <div className="mb-3 text-sm font-medium text-foreground">安全概览</div>
                                        <StructuredDataView value={detail.securityOverview} emptyLabel="暂无安全概览数据" />
                                    </div>
                                ) : null}
                            </div>
                        </ConsolePanel>
                    </div>
                </div>
            )}
        </ConsolePage>
    );
};

export default SiteDetail;

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Globe, ArrowRight } from 'lucide-react';
import { fetchSites } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';

const Sites = () => {
    const [sites, setSites] = useState<any[]>([]);

    useEffect(() => {
        fetchSites().then((data) => setSites(data)).catch(console.error);
    }, []);

    return (
        <ConsolePage title="站点资产" subtitle="统一查看受保护站点、目标地址与当前防护状态。">
            <ConsolePanel title="站点列表" subtitle="支持直接进入站点详情页查看暴露面和关联安全上下文。" icon={Globe} iconTone="primary">
                {sites.length === 0 ? (
                    <ConsoleEmptyState title="当前没有可展示的站点配置" />
                ) : (
                    <div className="space-y-3">
                        {sites.map((site: any) => (
                            <div key={site.id} className="flex items-center justify-between rounded-xl border border-border bg-muted/15 p-4 transition-colors hover:bg-muted/25">
                                <div className="flex flex-col gap-1">
                                    <span className="text-sm font-medium text-foreground">{site.domain}</span>
                                    <span className="font-mono text-xs text-muted-foreground">{site.target}</span>
                                </div>
                                <div className="flex items-center gap-3">
                                    <span className={`rounded border px-2 py-1 text-xs ${site.status === 'secure' ? 'border-emerald-500/20 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' : 'border-amber-500/20 bg-amber-500/10 text-amber-600 dark:text-amber-400'}`}>{site.status?.toUpperCase() || 'UNKNOWN'}</span>
                                    <Link to={`/sites/${site.id}`} className="flex items-center gap-1 rounded-lg border border-border bg-card px-3 py-2 text-xs font-medium text-foreground hover:bg-muted/30">
                                        查看详情
                                        <ArrowRight size={12} />
                                    </Link>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </ConsolePanel>
        </ConsolePage>
    );
};

export default Sites;

import { useEffect, useMemo, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { AlertTriangle, Copy, Cpu, Download, FileSearch, HardDrive, Key, Plus, RefreshCw, ShieldCheck, Trash2, Users, Zap } from 'lucide-react';
import {
    createAdminApiKey,
    createAdminOversightExport,
    createAgentOnboardingCode,
    deleteAdminApiKey,
    fetchAdminApiKeys,
    fetchAdminData,
    fetchAdminOversightEvidence,
    fetchAdminOversightExport,
    fetchAdminOversightExports,
    fetchAdminOversightSummary,
    fetchAdminOversightTenants,
    fetchAdminOversightTimeline,
    fetchAdminOversightUserTimeline,
    fetchAdminUsersList,
    fetchAgentOnboardingCodes,
    fetchRegisteredAgents,
    isRequestAbortError,
    revokeAgentCredential,
    verifyAdminAuditLog,
} from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel, ConsoleStatCard } from '../components/ConsolePrimitives';
import StructuredDataView from '../components/StructuredDataView';

type Tab = 'overview' | 'timeline' | 'evidence' | 'exports';
type ApiKey = { id: string; name: string; prefix: string; created: string; lastUsed: string };
type CodeRow = { id: string; status: 'active' | 'used' | 'expired' | 'revoked'; expectedHostname: string | null; maxUses: number; usedCount: number; expiresAt: string; usedByAgentId: string | null };
type AgentRow = { agentId: string; hostname: string; platform: string; status: 'pending' | 'approved' | 'revoked' };

const parseTab = (value: string | null): Tab => (value === 'timeline' || value === 'evidence' || value === 'exports' ? value : 'overview');
const fmt = (value?: string | null) => {
    if (!value) return 'Not available';
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleString();
};
const statusLabel: Record<string, string> = { active: 'Active', used: 'Used', expired: 'Expired', revoked: 'Revoked', pending: 'Pending', approved: 'Approved' };
const oversightCategories = [['all', 'All events'], ['auth', 'Authentication'], ['system', 'System'], ['scanner', 'Scanning'], ['alert', 'Alerts'], ['action', 'Actions'], ['validation', 'Validation'], ['deployment', 'Deployment']] as const;
const rangeOptions = [['1', '24 hours'], ['7', '7 days'], ['30', '30 days'], ['90', '90 days']] as const;

const downloadText = (filename: string, content: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
};

const OversightDetailView = ({ item }: { item: any }) => {
    if (!item) {
        return null;
    }

    return (
        <div className="space-y-4" data-testid="oversight-detail-panel">
            <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
                <div className="rounded-lg border border-border bg-muted/10 p-3">
                    <div className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Time</div>
                    <div className="mt-2 text-sm text-foreground">{fmt(item.timestamp || item.requestedAt || item.createdAt)}</div>
                </div>
                <div className="rounded-lg border border-border bg-muted/10 p-3">
                    <div className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Status</div>
                    <div className="mt-2 text-sm text-foreground">{item.status || item.integrity || 'Not available'}</div>
                </div>
                <div className="rounded-lg border border-border bg-muted/10 p-3">
                    <div className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Category</div>
                    <div className="mt-2 text-sm text-foreground">{item.category || 'Not available'}</div>
                </div>
                <div className="rounded-lg border border-border bg-muted/10 p-3">
                    <div className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Action</div>
                    <div className="mt-2 text-sm text-foreground">{item.action || item.id || 'Not available'}</div>
                </div>
            </div>

            {item.actor ? (
                <div className="rounded-lg border border-border bg-muted/10 p-4">
                    <div className="mb-3 text-sm font-medium text-foreground">Actor</div>
                    <StructuredDataView value={item.actor} emptyLabel="Actor unavailable" />
                </div>
            ) : null}

            {item.target ? (
                <div className="rounded-lg border border-border bg-muted/10 p-4">
                    <div className="mb-3 text-sm font-medium text-foreground">Target</div>
                    <StructuredDataView value={item.target} emptyLabel="Target unavailable" />
                </div>
            ) : null}

            <div className="rounded-lg border border-border bg-muted/10 p-4">
                <div className="mb-3 text-sm font-medium text-foreground">Details</div>
                <StructuredDataView value={item.details || item} emptyLabel="No detail payload available" />
            </div>
        </div>
    );
};

export default function SuperAdmin() {
    const location = useLocation();
    const navigate = useNavigate();
    const searchParams = useMemo(() => new URLSearchParams(location.search), [location.search]);

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [data, setData] = useState<any>(null);
    const [keys, setKeys] = useState<ApiKey[]>([]);
    const [codes, setCodes] = useState<CodeRow[]>([]);
    const [agents, setAgents] = useState<AgentRow[]>([]);
    const [users, setUsers] = useState<any[]>([]);
    const [tenants, setTenants] = useState<any[]>([]);
    const [summary, setSummary] = useState<any>(null);
    const [timeline, setTimeline] = useState<any[]>([]);
    const [evidence, setEvidence] = useState<any[]>([]);
    const [exportsList, setExportsList] = useState<any[]>([]);
    const [integrity, setIntegrity] = useState<Record<string, string>>({});
    const [detail, setDetail] = useState<any>(null);

    const [tab, setTab] = useState<Tab>(() => parseTab(searchParams.get('tab')));
    const [tenantId, setTenantId] = useState(() => searchParams.get('tenant') || '');
    const [userId, setUserId] = useState(() => searchParams.get('user') || '');
    const [category, setCategory] = useState('all');
    const [range, setRange] = useState('7');
    const [keyName, setKeyName] = useState('Platform API Key');
    const [hostname, setHostname] = useState('protected-web-01');
    const [ttl, setTtl] = useState('10');
    const [maxUses, setMaxUses] = useState('1');
    const [createdCode, setCreatedCode] = useState<string | null>(null);
    const [createdCodeExpireAt, setCreatedCodeExpireAt] = useState<string | null>(null);

    const currentUsers = useMemo(() => users.filter((user) => !tenantId || user.tenant_id === tenantId), [users, tenantId]);

    const syncQuery = (nextTab = tab, nextTenant = tenantId, nextUser = userId) => {
        const params = new URLSearchParams(location.search);
        params.set('tab', nextTab);
        nextTenant ? params.set('tenant', nextTenant) : params.delete('tenant');
        nextUser ? params.set('user', nextUser) : params.delete('user');
        navigate({ pathname: location.pathname, search: params.toString() }, { replace: true });
    };

    const applyOversightView = (nextTab = tab, nextTenant = tenantId, nextUser = userId) => {
        setTab(nextTab);
        setTenantId(nextTenant);
        setUserId(nextUser);
        setDetail(null);
        syncQuery(nextTab, nextTenant, nextUser);
    };

    const loadStatic = async (signal?: AbortSignal) => {
        setLoading(true);
        setError(null);
        try {
            const [adminData, apiKeys, codeRows, agentRows, userRows, tenantRows] = await Promise.all([
                fetchAdminData(signal),
                fetchAdminApiKeys(signal),
                fetchAgentOnboardingCodes(undefined, 100, signal),
                fetchRegisteredAgents(signal),
                fetchAdminUsersList(signal),
                fetchAdminOversightTenants(signal),
            ]);

            if (signal?.aborted) {
                return;
            }

            const queryTenant = new URLSearchParams(location.search).get('tenant');
            const queryUser = new URLSearchParams(location.search).get('user');
            const resolvedTenant =
                queryTenant ||
                userRows?.users?.find((user: any) => user.id === queryUser)?.tenant_id ||
                tenantRows?.[0]?.tenantId ||
                userRows?.users?.[0]?.tenant_id ||
                '';

            setData(adminData);
            setKeys(apiKeys || []);
            setCodes(codeRows || []);
            setAgents(agentRows || []);
            setUsers(userRows?.users || []);
            setTenants(tenantRows || []);
            setTenantId(resolvedTenant);

            if (!queryTenant && resolvedTenant) {
                syncQuery(parseTab(new URLSearchParams(location.search).get('tab')), resolvedTenant, queryUser || '');
            }
        } catch (err: any) {
            if (!isRequestAbortError(err, signal)) {
                setError(err?.message || 'Failed to load admin console data');
            }
        } finally {
            if (!signal?.aborted) {
                setLoading(false);
            }
        }
    };

    const loadOversight = async (signal?: AbortSignal) => {
        if (!tenantId) {
            return;
        }

        try {
            const now = new Date();
            const from = new Date(now.getTime() - Number(range) * 24 * 60 * 60 * 1000).toISOString();
            const filters = { tenantId, userId: userId || undefined, category, from, to: now.toISOString(), limit: 200 };
            const [summaryData, timelineData, evidenceData, exportData] = await Promise.all([
                fetchAdminOversightSummary(tenantId, userId || undefined, signal),
                userId
                    ? fetchAdminOversightUserTimeline(userId, { tenantId, category, from, to: now.toISOString(), limit: 200 }, signal)
                    : fetchAdminOversightTimeline(filters, signal),
                fetchAdminOversightEvidence(filters, signal),
                fetchAdminOversightExports(tenantId, signal),
            ]);

            if (signal?.aborted) {
                return;
            }

            setSummary(summaryData);
            setTimeline(timelineData || []);
            setEvidence(evidenceData || []);
            setExportsList(exportData || []);
            setError(null);
        } catch (err: any) {
            if (!isRequestAbortError(err, signal)) {
                setError(err?.message || 'Failed to load oversight data');
            }
        }
    };

    useEffect(() => {
        const controller = new AbortController();
        void loadStatic(controller.signal);
        return () => controller.abort();
    }, []);
    useEffect(() => {
        const nextTab = parseTab(searchParams.get('tab'));
        const nextTenant = searchParams.get('tenant');
        const nextUser = searchParams.get('user') || '';
        const tabChanged = nextTab !== tab;
        const userChanged = nextUser !== userId;
        const tenantChanged = nextTenant !== null && nextTenant !== tenantId;
        if (tabChanged) setTab(nextTab);
        if (userChanged) setUserId(nextUser);
        if (tenantChanged) setTenantId(nextTenant || '');
        if (tabChanged || userChanged || tenantChanged) setDetail(null);
    }, [location.search]);
    useEffect(() => {
        const controller = new AbortController();
        void loadOversight(controller.signal);
        return () => controller.abort();
    }, [tenantId, userId, category, range, tab]);

    const copy = async (value: string) => navigator.clipboard.writeText(value).catch(() => setError('Failed to copy text'));
    const createKey = async () => { await createAdminApiKey(keyName); setKeys(await fetchAdminApiKeys()); };
    const removeKey = async (id: string) => { await deleteAdminApiKey(id); setKeys(await fetchAdminApiKeys()); };
    const createCode = async () => {
        const result = await createAgentOnboardingCode({ hostname, ttlMinutes: Number(ttl), maxUses: Number(maxUses) });
        setCreatedCode(result?.data?.onboardingCode || null);
        setCreatedCodeExpireAt(result?.data?.expiresAt || null);
        setCodes(await fetchAgentOnboardingCodes(undefined, 100));
    };
    const revoke = async (agentId: string) => { await revokeAgentCredential(agentId, 'revoked-from-super-admin'); setAgents(await fetchRegisteredAgents()); };
    const verify = async (logId: string) => {
        setIntegrity((state) => ({ ...state, [logId]: 'Verifying...' }));
        const result = await verifyAdminAuditLog(logId);
        setIntegrity((state) => ({ ...state, [logId]: result?.valid ? 'Valid' : 'Failed' }));
    };
    const buildExport = async (targetTenantId: string = tenantId, targetUserId: string = userId) => {
        const result = await createAdminOversightExport({ tenantId: targetTenantId, filters: { userId: targetUserId || undefined, category, range } });
        const record = result?.data || result;
        setExportsList((rows) => [record, ...rows.filter((item) => item.id !== record.id)]);
    };
    const downloadExport = async (record: any, format: 'json' | 'csv') => {
        if (!record) return;
        const detailed = record.jsonPayload && record.csvPayload ? record : await fetchAdminOversightExport(record.id);
        if (format === 'json' && detailed?.jsonPayload) downloadText(`tenant-${detailed.tenantId}.json`, detailed.jsonPayload, 'application/json;charset=utf-8');
        if (format === 'csv' && detailed?.csvPayload) downloadText(`tenant-${detailed.tenantId}.csv`, detailed.csvPayload, 'text/csv;charset=utf-8');
    };

    if (loading) return <div className="p-8 text-muted-foreground">Loading platform admin console...</div>;
    if (!data) return <div className="p-8 text-muted-foreground">Admin console is currently unavailable.</div>;

    const perf = data.performance || {};
    const errors = data.errors || [];

    return (
        <ConsolePage title="Platform Admin Console" subtitle="Tenant oversight, dispute evidence, onboarding credentials, and platform keys in one place.">
            {error && <div className="rounded-xl border border-rose-500/30 bg-rose-500/10 px-4 py-3 text-sm text-rose-300">{error}</div>}

            <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                <ConsoleStatCard icon={Cpu} label="Backend CPU" value={`${perf.server?.cpu?.toFixed?.(1) ?? 'N/A'}%`} hint="Current platform CPU usage" tone="primary" />
                <ConsoleStatCard icon={HardDrive} label="Backend Memory" value={`${perf.server?.memory?.toFixed?.(1) ?? 'N/A'}%`} hint="Current platform memory usage" tone="warning" />
                <ConsoleStatCard icon={Users} label="Online Agents" value={perf.clients?.total_agents ?? 0} hint="Agents currently connected to the control plane" tone="success" />
            </div>

            <ConsolePanel title="Tenant Oversight" subtitle="Admin viewing and exporting are audited for dispute handling." icon={FileSearch} iconTone="warning" headerAction={<button onClick={() => buildExport()} disabled={!tenantId} className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-xs font-medium text-primary-foreground disabled:opacity-50"><Download size={14} />Generate evidence pack</button>}>
                <div className="space-y-5">
                    <div className="grid grid-cols-1 gap-3 xl:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)_minmax(0,0.9fr)_160px_120px]">
                        <select value={tenantId} onChange={(event) => applyOversightView(tab, event.target.value, '')} className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground">{tenants.map((tenant) => <option key={tenant.tenantId} value={tenant.tenantId}>{tenant.tenantName} ({tenant.userCount})</option>)}</select>
                        <select value={userId} onChange={(event) => applyOversightView(tab, tenantId, event.target.value)} className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground"><option value="">All users</option>{currentUsers.map((user) => <option key={user.id} value={user.id}>{user.email}</option>)}</select>
                        <select value={category} onChange={(event) => setCategory(event.target.value)} className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground">{oversightCategories.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>
                        <select value={range} onChange={(event) => setRange(event.target.value)} className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground">{rangeOptions.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>
                        <div className="flex gap-2">
                            <button onClick={() => void loadOversight()} className="rounded-lg border border-border bg-card px-3 py-2 text-sm text-foreground hover:bg-muted/40">Refresh</button>
                            <Link data-testid="oversight-back-to-users" to="/super-admin" className="rounded-lg border border-border bg-card px-3 py-2 text-sm text-foreground hover:bg-muted/40">Users</Link>
                        </div>
                    </div>

                    <div className="flex flex-wrap gap-2">{([['overview', 'Tenant Overview'], ['timeline', 'Timeline'], ['evidence', 'Evidence'], ['exports', 'Exports']] as Array<[Tab, string]>).map(([value, label]) => <button key={value} data-testid={`oversight-tab-${value}`} onClick={() => applyOversightView(value, tenantId, userId)} className={`rounded-full px-3 py-1.5 text-xs font-medium ${tab === value ? 'bg-primary text-primary-foreground' : 'border border-border bg-card text-muted-foreground hover:text-foreground'}`}>{label}</button>)}</div>

                    {tab === 'overview' && <>
                        <div className="grid grid-cols-1 gap-4 lg:grid-cols-4">
                            <ConsoleStatCard icon={AlertTriangle} label="Active Alerts" value={summary?.metrics?.activeAlerts ?? 0} hint="Currently unresolved or in-progress alerts" tone="danger" />
                            <ConsoleStatCard icon={ShieldCheck} label="Pending Actions" value={summary?.metrics?.pendingActions ?? 0} hint="Actions still waiting for execution or review" tone="warning" />
                            <ConsoleStatCard icon={Zap} label="Failed Validations" value={summary?.metrics?.failedValidations ?? 0} hint="Recent missed validation outcomes" tone="danger" />
                            <ConsoleStatCard icon={Users} label="Tenant Users" value={summary?.tenant?.userCount ?? 0} hint={`Last activity: ${fmt(summary?.tenant?.lastActiveAt)}`} tone="primary" />
                        </div>
                        <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(0,1.1fr)]">
                            <ConsolePanel title="Tenant Directory" subtitle="Switch tenant context, open its timeline, or export a dispute pack.">
                                <div className="space-y-2">{tenants.map((tenant) => <div key={tenant.tenantId} className={`flex flex-col gap-3 rounded-xl border border-border px-4 py-3 md:flex-row md:items-center md:justify-between ${tenant.tenantId === tenantId ? 'bg-primary/5' : 'bg-muted/10'}`}><div><div className="text-sm font-medium text-foreground">{tenant.tenantName}</div><div className="text-xs text-muted-foreground">{tenant.tenantId} / High alerts {tenant.openHighAlerts} / Last active {fmt(tenant.lastActiveAt)}</div></div><div className="flex gap-2"><button data-testid={`oversight-tenant-timeline-${tenant.tenantId}`} onClick={() => applyOversightView('timeline', tenant.tenantId, '')} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">View timeline</button><button onClick={() => buildExport(tenant.tenantId, '')} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">Export evidence</button></div></div>)}</div>
                            </ConsolePanel>
                            <ConsolePanel title="User Activity Entry Points" subtitle="Drill down from a tenant into a concrete user's activity timeline.">
                                <div className="space-y-2">{currentUsers.length === 0 ? <ConsoleEmptyState title="No users in the selected tenant" description="Switch tenant or open a specific user from the user management page." /> : currentUsers.map((user) => <div key={user.id} className="flex flex-col gap-3 rounded-xl border border-border bg-muted/10 px-4 py-3 md:flex-row md:items-center md:justify-between"><div><div className="text-sm font-medium text-foreground">{user.email}</div><div className="text-xs text-muted-foreground">{user.role} / {user.plan} / {user.status} / Last login {fmt(user.last_login)}</div></div><div className="flex gap-2"><button data-testid={`oversight-user-activity-${user.id}`} onClick={() => applyOversightView('timeline', user.tenant_id, user.id)} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">View user activity</button><Link data-testid="oversight-back-to-users" to="/super-admin" className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">Back to user management</Link></div></div>)}</div>
                            </ConsolePanel>
                        </div>
                    </>}

                    {tab === 'timeline' && <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1.3fr)_minmax(0,0.9fr)]">
                        <ConsolePanel title={userId ? 'User Activity Timeline' : 'Tenant Activity Timeline'} subtitle="Authentication, scans, alerts, actions, validation, and deployment events in one ordered stream.">
                            <div className="overflow-x-auto"><table data-testid="oversight-timeline-table" className="w-full text-sm"><thead className="bg-muted/30 text-left text-xs text-muted-foreground"><tr><th className="px-3 py-2">Time</th><th className="px-3 py-2">Category</th><th className="px-3 py-2">Action</th><th className="px-3 py-2">Status</th><th className="px-3 py-2">Actor</th><th className="px-3 py-2">Details</th></tr></thead><tbody className="divide-y divide-border/50">{timeline.map((item) => <tr key={item.id}><td className="px-3 py-2 text-muted-foreground">{fmt(item.timestamp)}</td><td className="px-3 py-2 text-foreground">{item.category}</td><td className="px-3 py-2 text-foreground">{item.action}</td><td className="px-3 py-2 text-foreground">{item.status}</td><td className="px-3 py-2 text-muted-foreground">{item.actor?.email || item.actor?.id || 'system'}</td><td className="px-3 py-2"><button data-testid="oversight-timeline-detail" onClick={() => setDetail(item)} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">View detail</button></td></tr>)}</tbody></table></div>
                        </ConsolePanel>
                        <ConsolePanel title="Event Detail" subtitle="Use this side panel to inspect the selected timeline event.">
                            {detail ? <OversightDetailView item={detail} /> : <ConsoleEmptyState title="Select a timeline event" description="Pick any row from the left table to inspect its details." />}
                        </ConsolePanel>
                    </div>}

                    {tab === 'evidence' && <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1.3fr)_minmax(0,0.9fr)]">
                        <ConsolePanel title="Evidence and Audit Logs" subtitle="Signed audit logs, context objects, and integrity checks for dispute handling.">
                            <div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-muted/30 text-left text-xs text-muted-foreground"><tr><th className="px-3 py-2">Time</th><th className="px-3 py-2">Action</th><th className="px-3 py-2">Actor</th><th className="px-3 py-2">Status</th><th className="px-3 py-2">Integrity</th><th className="px-3 py-2">Actions</th></tr></thead><tbody className="divide-y divide-border/50">{evidence.map((item) => <tr key={item.logId}><td className="px-3 py-2 text-muted-foreground">{fmt(item.timestamp)}</td><td className="px-3 py-2 text-foreground">{item.action}</td><td className="px-3 py-2 text-muted-foreground">{item.actor?.email || item.actor?.id || 'system'}</td><td className="px-3 py-2 text-foreground">{item.status}</td><td className="px-3 py-2 text-foreground">{integrity[item.logId] || item.integrity}</td><td className="px-3 py-2"><div className="flex gap-2"><button onClick={() => verify(item.logId)} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">Verify</button><button onClick={() => setDetail(item)} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">View detail</button></div></td></tr>)}</tbody></table></div>
                        </ConsolePanel>
                        <ConsolePanel title="Evidence Detail" subtitle="Raw evidence and audit context for the selected entry.">
                            {detail ? <OversightDetailView item={detail} /> : <ConsoleEmptyState title="Select an evidence row" description="Use the left table to inspect the signed log payload." />}
                        </ConsolePanel>
                    </div>}

                    {tab === 'exports' && <ConsolePanel title="Export History" subtitle="Every export retains the operator, time window, and the active filters.">{exportsList.length === 0 ? <ConsoleEmptyState title="No exports yet" description="Use the evidence pack button above to generate a tenant dispute bundle." /> : <div className="space-y-3">{exportsList.map((record) => <div key={record.id} className="flex flex-col gap-3 rounded-xl border border-border bg-muted/10 px-4 py-4 lg:flex-row lg:items-center lg:justify-between"><div><div className="text-sm font-medium text-foreground">{record.id}</div><div className="mt-1 text-xs text-muted-foreground">Tenant {record.tenantId} / {record.requestedBy} / {fmt(record.requestedAt)}</div></div><div className="flex gap-2"><button onClick={() => downloadExport(record, 'json')} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">Download JSON</button><button onClick={() => downloadExport(record, 'csv')} className="rounded-md border border-border px-2 py-1 text-xs text-foreground hover:bg-muted/40">Download CSV</button></div></div>)}</div>}</ConsolePanel>}
                </div>
            </ConsolePanel>

            <div className="grid grid-cols-1 gap-6 xl:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
            <ConsolePanel title="Agent Onboarding" subtitle="Generate onboarding codes and keep registration and revocation history visible." icon={ShieldCheck} iconTone="primary" headerAction={<button onClick={() => void loadStatic()} className="flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-1.5 text-xs text-foreground hover:bg-muted/40"><RefreshCw size={14} />Refresh</button>}>
                    <div className="space-y-5">
                        <div className="grid grid-cols-1 gap-3 md:grid-cols-4"><input value={hostname} onChange={(event) => setHostname(event.target.value)} placeholder="Expected hostname" className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground" /><input value={ttl} onChange={(event) => setTtl(event.target.value)} placeholder="TTL (minutes)" className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground" /><input value={maxUses} onChange={(event) => setMaxUses(event.target.value)} placeholder="Max uses" className="rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground" /><button onClick={createCode} className="rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground">Generate code</button></div>
                        {createdCode && <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/10 p-4"><div className="text-xs text-emerald-300">One-time onboarding code</div><div className="mt-2 flex items-center gap-2"><code className="break-all text-sm text-emerald-200">{createdCode}</code><button onClick={() => copy(createdCode)} className="rounded-md p-1.5 text-emerald-200 hover:bg-emerald-500/20"><Copy size={14} /></button></div><div className="mt-2 text-[11px] text-emerald-300/80">Expires at {fmt(createdCodeExpireAt)}</div></div>}
                        <div className="overflow-x-auto rounded-xl border border-border"><table className="w-full text-sm"><thead className="bg-muted/30 text-left text-xs text-muted-foreground"><tr><th className="px-3 py-2">Status</th><th className="px-3 py-2">Hostname</th><th className="px-3 py-2">Uses</th><th className="px-3 py-2">Expires</th><th className="px-3 py-2">Agent</th></tr></thead><tbody className="divide-y divide-border/50">{codes.map((code) => <tr key={code.id}><td className="px-3 py-2 text-foreground">{statusLabel[code.status]}</td><td className="px-3 py-2 text-foreground">{code.expectedHostname || '-'}</td><td className="px-3 py-2 text-foreground">{code.usedCount}/{code.maxUses}</td><td className="px-3 py-2 text-muted-foreground">{fmt(code.expiresAt)}</td><td className="px-3 py-2 font-mono text-muted-foreground">{code.usedByAgentId || '-'}</td></tr>)}</tbody></table></div>
                        <div className="overflow-x-auto rounded-xl border border-border"><table className="w-full text-sm"><thead className="bg-muted/30 text-left text-xs text-muted-foreground"><tr><th className="px-3 py-2">Agent ID</th><th className="px-3 py-2">Hostname</th><th className="px-3 py-2">Platform</th><th className="px-3 py-2">Status</th><th className="px-3 py-2">Action</th></tr></thead><tbody className="divide-y divide-border/50">{agents.map((agent) => <tr key={agent.agentId}><td className="px-3 py-2 font-mono text-foreground">{agent.agentId}</td><td className="px-3 py-2 text-foreground">{agent.hostname}</td><td className="px-3 py-2 text-foreground">{agent.platform}</td><td className="px-3 py-2 text-foreground">{statusLabel[agent.status]}</td><td className="px-3 py-2"><button onClick={() => revoke(agent.agentId)} disabled={agent.status === 'revoked'} className="rounded-md bg-rose-600/90 px-2 py-1 text-xs text-white disabled:opacity-50">Revoke</button></td></tr>)}</tbody></table></div>
                    </div>
                </ConsolePanel>

                <div className="space-y-6">
                    <ConsolePanel title="Admin API Keys" subtitle="Platform automation and emergency operations credentials." icon={Key} iconTone="warning" headerAction={<button onClick={createKey} className="flex items-center gap-2 rounded-lg bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground"><Plus size={14} />Create key</button>}>
                        <div className="space-y-3"><input value={keyName} onChange={(event) => setKeyName(event.target.value)} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground" placeholder="Key name" />{keys.length === 0 ? <ConsoleEmptyState title="No admin API keys" description="Create a key to expose platform automation access." /> : keys.map((key) => <div key={key.id} className="flex flex-col gap-3 rounded-xl border border-border bg-muted/10 p-4"><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-medium text-foreground">{key.name}</div><div className="font-mono text-xs text-muted-foreground">{key.prefix}**************</div></div><div className="flex gap-1"><button onClick={() => copy(`${key.prefix}**************`)} className="rounded-md p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"><Copy size={14} /></button><button onClick={() => removeKey(key.id)} className="rounded-md p-1.5 text-muted-foreground hover:bg-rose-500/10 hover:text-rose-300"><Trash2 size={14} /></button></div></div><div className="text-xs text-muted-foreground">Created {fmt(key.created)} / Last used {key.lastUsed}</div></div>)}</div>
                    </ConsolePanel>
                    <ConsolePanel title="Recent Errors" subtitle="High-frequency failures help separate product disputes from platform instability." icon={AlertTriangle} iconTone="danger"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-muted/30 text-left text-xs text-muted-foreground"><tr><th className="px-3 py-2">User</th><th className="px-3 py-2">Error Code</th><th className="px-3 py-2">Message</th><th className="px-3 py-2">Time</th></tr></thead><tbody className="divide-y divide-border/50">{errors.map((item: any, index: number) => <tr key={`${item.userId}-${index}`}><td className="px-3 py-2 font-mono text-foreground">{item.userId}</td><td className="px-3 py-2"><span className="rounded-md border border-border bg-muted px-1.5 py-0.5 font-mono text-xs text-foreground">{item.errorCode}</span></td><td className="px-3 py-2 text-rose-300">{item.message}</td><td className="px-3 py-2 text-muted-foreground">{fmt(item.timestamp)}</td></tr>)}</tbody></table></div></ConsolePanel>
                    <ConsolePanel title="Endpoint Performance" subtitle="Use these numbers to separate policy issues from platform overhead." icon={Zap} iconTone="success"><div className="grid grid-cols-2 gap-4"><div className="rounded-xl border border-border bg-muted/10 p-4"><div className="text-xs text-muted-foreground">Average CPU overhead</div><div className="mt-2 text-2xl font-semibold text-foreground">{perf.clients?.avg_cpu_overhead ?? 'N/A'}%</div></div><div className="rounded-xl border border-border bg-muted/10 p-4"><div className="text-xs text-muted-foreground">Average added latency</div><div className="mt-2 text-2xl font-semibold text-foreground">{perf.clients?.avg_latency_added ?? 'N/A'}</div></div></div></ConsolePanel>
                </div>
            </div>
        </ConsolePage>
    );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import {
    Activity,
    Shield,
    ArrowUpRight,
    ArrowDownLeft,
    Globe,
    Zap,
    Clock,
    Database,
    RefreshCw,
    XCircle,
    CheckCircle,
    ShieldAlert,
} from 'lucide-react';
import {
    fetchTrafficStats,
    fetchActiveFlows,
    fetchProtocolDistribution,
    fetchThreatDetections,
} from '../services/api';
import type { TrafficStats, FlowInfo } from '../types/api';
import { useLiveMode } from '../context/LiveModeContext';
import { ConsoleEmptyState, ConsolePage, ConsolePanel, ConsoleStatCard } from '../components/ConsolePrimitives';

export default function TrafficInterceptor() {
    const { t } = useTranslation();
    const { liveModeEnabled } = useLiveMode();
    const [stats, setStats] = useState<TrafficStats | null>(null);
    const [flows, setFlows] = useState<FlowInfo[]>([]);
    const [protocols, setProtocols] = useState({ http: 0, https: 0, dns: 0, other: 0 });
    const [threats, setThreats] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [autoRefresh, setAutoRefresh] = useState(true);

    useEffect(() => {
        loadData();

        if (autoRefresh && liveModeEnabled) {
            const interval = setInterval(loadData, 3000);
            return () => clearInterval(interval);
        }
    }, [autoRefresh, liveModeEnabled]);

    const loadData = async () => {
        setLoading(true);
        try {
            const [statsData, flowsData, protocolsData, threatsData] = await Promise.all([
                fetchTrafficStats(),
                fetchActiveFlows(),
                fetchProtocolDistribution(),
                fetchThreatDetections(),
            ]);

            if (statsData) setStats(statsData);
            if (flowsData) setFlows(flowsData);
            if (protocolsData) setProtocols(protocolsData);
            if (threatsData) setThreats(threatsData);
        } catch (e) {
            console.error('Traffic fetch error', e);
        }
        setLoading(false);
    };

    const formatBytes = (bytes: number) => {
        if (bytes < 1024) return `${bytes} B`;
        if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
        if (bytes < 1024 * 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
        return `${(bytes / 1024 / 1024 / 1024).toFixed(2)} GB`;
    };

    const formatUptime = (seconds: number) => {
        const hours = Math.floor(seconds / 3600);
        const minutes = Math.floor((seconds % 3600) / 60);
        return `${hours}h ${minutes}m`;
    };

    const getProtocolPercentage = (value: number) => {
        const total = protocols.http + protocols.https + protocols.dns + protocols.other;
        if (total === 0) return 0;
        return ((value / total) * 100).toFixed(1);
    };

    const getSeverityText = (severity: string) => t(`trafficInterceptor.severities.${severity}`);

    return (
        <ConsolePage
            title={t('trafficInterceptor.title')}
            subtitle={t('trafficInterceptor.subtitle')}
            actions={
                <div className="flex items-center gap-4 rounded-lg border border-border bg-card p-2 shadow-sm">
                    <label className="flex cursor-pointer items-center gap-2 px-3 text-sm font-medium text-foreground">
                        <input
                            type="checkbox"
                            checked={autoRefresh}
                            onChange={(e) => setAutoRefresh(e.target.checked)}
                            className="h-4 w-4 rounded border-border bg-background text-primary focus:ring-primary/30"
                        />
                        {t('trafficInterceptor.autoRefresh')}
                    </label>
                    <button
                        onClick={loadData}
                        className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
                    >
                        <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                        {t('trafficInterceptor.refresh')}
                    </button>
                </div>
            }
        >
            <div className="grid grid-cols-2 gap-4 md:grid-cols-3 xl:grid-cols-6">
                <ConsoleStatCard icon={Activity} label={t('trafficInterceptor.packets')} value={stats?.packetsProcessed?.toLocaleString() || 0} hint="累计处理报文数" tone="primary" />
                <ConsoleStatCard icon={CheckCircle} label={t('trafficInterceptor.allowed')} value={stats?.packetsAllowed?.toLocaleString() || 0} hint="已通过检测链路" tone="success" />
                <ConsoleStatCard icon={XCircle} label={t('trafficInterceptor.blocked')} value={stats?.packetsBlocked?.toLocaleString() || 0} hint="已被主动拦截" tone="danger" />
                <ConsoleStatCard icon={Shield} label={t('trafficInterceptor.inspected')} value={stats?.packetsInspected?.toLocaleString() || 0} hint="已完成深度检查" tone="warning" />
                <ConsoleStatCard icon={Database} label={t('trafficInterceptor.bytes')} value={formatBytes(Number(stats?.bytesProcessed || 0))} hint="累计吞吐量" tone="neutral" />
                <ConsoleStatCard icon={Clock} label={t('trafficInterceptor.uptime')} value={formatUptime(stats?.uptime || 0)} hint="拦截器持续运行时长" tone="neutral" />
            </div>

            <div className="grid grid-cols-1 gap-6 lg:grid-cols-12">
                <div className="lg:col-span-5">
                    <ConsolePanel title={t('trafficInterceptor.protocolDistribution')} subtitle="当前观测流量的协议分布" icon={Globe} iconTone="primary">
                        <div className="space-y-4">
                            {[
                                { name: 'HTTP', value: protocols.http, color: 'bg-blue-500' },
                                { name: 'HTTPS', value: protocols.https, color: 'bg-emerald-500' },
                                { name: 'DNS', value: protocols.dns, color: 'bg-amber-500' },
                                { name: t('trafficInterceptor.other'), value: protocols.other, color: 'bg-muted-foreground' },
                            ].map((protocol, index) => (
                                <div key={protocol.name}>
                                    <div className="mb-1.5 flex items-center justify-between text-sm">
                                        <span className="font-medium uppercase tracking-wide text-muted-foreground">{protocol.name}</span>
                                        <span className="font-mono text-foreground">{getProtocolPercentage(protocol.value)}%</span>
                                    </div>
                                    <div className="h-2 overflow-hidden rounded-full bg-muted">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${getProtocolPercentage(protocol.value)}%` }}
                                            transition={{ duration: 0.8, delay: index * 0.08 }}
                                            className={`h-full ${protocol.color}`}
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </ConsolePanel>
                </div>

                <div className="lg:col-span-7">
                    <ConsolePanel title={t('trafficInterceptor.threatDetections')} subtitle="按风险等级汇总的最新检测计数" icon={ShieldAlert} iconTone="danger">
                        {threats.length > 0 ? (
                            <div className="space-y-2">
                                <AnimatePresence>
                                    {threats.slice(0, 5).map((threat, index) => (
                                        <motion.div
                                            key={`${threat.type}-${index}`}
                                            initial={{ opacity: 0, scale: 0.96 }}
                                            animate={{ opacity: 1, scale: 1 }}
                                            transition={{ delay: index * 0.05 }}
                                            className="flex items-center justify-between rounded-lg border border-border bg-muted/15 p-3"
                                        >
                                            <div className="flex items-center gap-3">
                                                <span
                                                    className={`rounded border px-2 py-0.5 text-xs font-semibold ${
                                                        threat.severity === 'critical'
                                                            ? 'border-rose-500/20 bg-rose-500/10 text-rose-600 dark:text-rose-400'
                                                            : threat.severity === 'high'
                                                              ? 'border-orange-500/20 bg-orange-500/10 text-orange-600 dark:text-orange-400'
                                                              : threat.severity === 'medium'
                                                                ? 'border-amber-500/20 bg-amber-500/10 text-amber-600 dark:text-amber-400'
                                                                : 'border-blue-500/20 bg-blue-500/10 text-blue-600 dark:text-blue-400'
                                                    }`}
                                                >
                                                    {getSeverityText(threat.severity).toUpperCase()}
                                                </span>
                                                <span className="text-sm font-medium text-foreground">{threat.type}</span>
                                            </div>
                                            <span className="font-mono text-sm font-semibold text-foreground">{threat.count}</span>
                                        </motion.div>
                                    ))}
                                </AnimatePresence>
                            </div>
                        ) : (
                            <ConsoleEmptyState title={t('trafficInterceptor.noThreats')} description="当前没有待处理的威胁检测结果。" />
                        )}
                    </ConsolePanel>
                </div>
            </div>

            <ConsolePanel
                title={t('trafficInterceptor.activeFlows')}
                subtitle="当前已纳入检测的连接"
                icon={Zap}
                iconTone="primary"
                headerAction={
                    <span className="rounded-md bg-muted px-2.5 py-1 text-xs font-medium text-muted-foreground">
                        {stats?.currentFlows || 0} {t('trafficInterceptor.connections')}
                    </span>
                }
            >
                {flows.length > 0 ? (
                    <div className="overflow-x-auto">
                        <table className="w-full whitespace-nowrap text-left text-sm">
                            <thead>
                                <tr className="border-b border-border bg-muted/20 text-xs font-semibold text-muted-foreground">
                                    <th className="px-4 py-3">{t('trafficInterceptor.source')}</th>
                                    <th className="px-4 py-3">{t('trafficInterceptor.destination')}</th>
                                    <th className="px-4 py-3">{t('trafficInterceptor.protocol')}</th>
                                    <th className="px-4 py-3">{t('trafficInterceptor.state')}</th>
                                    <th className="px-4 py-3 text-right">{t('trafficInterceptor.packets')}</th>
                                    <th className="px-4 py-3 text-right">{t('trafficInterceptor.bytes')}</th>
                                    <th className="px-4 py-3 text-right">详情</th>
                                </tr>
                            </thead>
                            <tbody>
                                <AnimatePresence>
                                    {flows.slice(0, 10).map((flow, index) => (
                                        <motion.tr
                                            key={flow.id}
                                            initial={{ opacity: 0, x: -10 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            transition={{ delay: 0.03 * index }}
                                            className="border-b border-border transition-colors hover:bg-muted/20"
                                        >
                                            <td className="px-4 py-3">
                                                <div className="flex items-center gap-2">
                                                    <div className="flex h-5 w-5 items-center justify-center rounded bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
                                                        <ArrowUpRight className="h-3 w-3" />
                                                    </div>
                                                    <span className="font-mono text-sm text-foreground">
                                                        {flow.sourceIP}
                                                        <span className="text-muted-foreground">:{flow.sourcePort}</span>
                                                    </span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3">
                                                <div className="flex items-center gap-2">
                                                    <div className="flex h-5 w-5 items-center justify-center rounded bg-blue-500/10 text-blue-600 dark:text-blue-400">
                                                        <ArrowDownLeft className="h-3 w-3" />
                                                    </div>
                                                    <span className="font-mono text-sm text-foreground">
                                                        {flow.destIP}
                                                        <span className="text-muted-foreground">:{flow.destPort}</span>
                                                    </span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3">
                                                <span
                                                    className={`rounded-md border px-2.5 py-1 text-[10px] font-bold tracking-widest ${
                                                        flow.protocol === 'tcp'
                                                            ? 'border-blue-500/20 bg-blue-500/10 text-blue-600 dark:text-blue-400'
                                                            : flow.protocol === 'udp'
                                                              ? 'border-cyan-500/20 bg-cyan-500/10 text-cyan-600 dark:text-cyan-400'
                                                              : 'border-border bg-muted/40 text-muted-foreground'
                                                    }`}
                                                >
                                                    {flow.protocol.toUpperCase()}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3">
                                                <span className="font-mono text-xs font-semibold text-muted-foreground">{flow.state}</span>
                                            </td>
                                            <td className="px-4 py-3 text-right font-mono font-bold text-foreground">{(flow.packetCount ?? 0).toLocaleString()}</td>
                                            <td className="px-4 py-3 text-right font-mono font-bold text-muted-foreground">{formatBytes(flow.byteCount ?? 0)}</td>
                                            <td className="px-4 py-3 text-right">
                                                <Link to={`/traffic/sessions/${flow.id}`} className="rounded-lg border border-border bg-card px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted/30">
                                                    查看
                                                </Link>
                                            </td>
                                        </motion.tr>
                                    ))}
                                </AnimatePresence>
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <ConsoleEmptyState title={t('trafficInterceptor.noFlows')} description="当前没有可供查看的活动连接。" />
                )}
            </ConsolePanel>

            <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
                <ConsoleStatCard
                    icon={Clock}
                    label={t('trafficInterceptor.avgProcessingTime')}
                    value={
                        <>
                            {(stats?.avgProcessingTime || 0).toFixed(2)}
                            <span className="ml-1 text-base text-muted-foreground">ms</span>
                        </>
                    }
                    tone="neutral"
                />
                <ConsoleStatCard icon={XCircle} label={t('trafficInterceptor.droppedPackets')} value={stats?.droppedPackets?.toLocaleString() || 0} tone="danger" />
                <ConsoleStatCard icon={ShieldAlert} label={t('trafficInterceptor.bufferOverflows')} value={stats?.bufferOverflows?.toLocaleString() || 0} tone="warning" />
                <ConsoleStatCard
                    icon={Activity}
                    label={t('trafficInterceptor.cpuUsage')}
                    value={
                        <>
                            {(stats?.cpuUsage || 0).toFixed(1)}
                            <span className="ml-1 text-base text-muted-foreground">%</span>
                        </>
                    }
                    tone="success"
                />
            </div>
        </ConsolePage>
    );
}

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { Activity, ArrowLeft, Network, Shield } from 'lucide-react';
import { fetchTrafficSessionDetail } from '../services/api';
import { ConsoleEmptyState, ConsolePage, ConsolePanel } from '../components/ConsolePrimitives';

const TrafficSessionDetail = () => {
    const { id = '' } = useParams();
    const [detail, setDetail] = useState<any>(null);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        fetchTrafficSessionDetail(id)
