export const fetchCurrentUserSession = async (signal?: AbortSignal): Promise<CurrentUserSession | null> => {
    const response = await fetchWithCredentials(`${API_BASE_URL}/auth/me`, { signal });
    if (!response.ok) {
        setSessionUserIdentity(null);
        return null;
    }

    const payload = await response.json().catch(() => null) as unknown;
    const payloadRecord = asRecord(payload);
    const data = unwrapApiEnvelope<{ user?: CurrentUserSession }>(payload);
    const user = data?.user || (payloadRecord?.user as CurrentUserSession | undefined) || null;
    setSessionUserIdentity(user);
    return user;
};

const extractErrorMessage = (payload: unknown, fallback: string): string => {
    const record = asRecord(payload);
    const error = record?.error;

    if (typeof error === 'string') {
        return error;
    }

    const errorRecord = asRecord(error);
    if (typeof errorRecord?.message === 'string') {
        return errorRecord.message;
    }

    if (typeof record?.message === 'string') {
        return record.message;
    }

    return fallback;
};

export const login = async (
    credentials: { email: string; password: string },
    signal?: AbortSignal
): Promise<LoginResponse> => {
    const response = await fetchWithCredentials(`${API_BASE_URL}/auth/login`, {
        method: 'POST',
        signal,
        body: JSON.stringify(credentials)
    });

    const payload = await response.json().catch(() => null) as unknown;
    const payloadRecord = asRecord(payload);
    const data = unwrapApiEnvelope<Partial<LoginResponse>>(payload);

    if (!response.ok) {
        setSessionUserIdentity(null);
        throw new Error(extractErrorMessage(payload, `FG-AUTH-LOGIN-${response.status}`));
    }

    const user = data?.user || (payloadRecord?.user as CurrentUserSession | undefined);
    if (!user) {
        throw new Error('FG-AUTH-LOGIN-USER-MISSING');
    }

    setSessionUserIdentity(user);
    return {
        message: data?.message || (typeof payloadRecord?.message === 'string' ? payloadRecord.message : undefined),
        user,
        accessToken: data?.accessToken || (typeof payloadRecord?.accessToken === 'string' ? payloadRecord.accessToken : undefined),
        refreshToken: data?.refreshToken || (typeof payloadRecord?.refreshToken === 'string' ? payloadRecord.refreshToken : undefined),
        expiresIn: data?.expiresIn || (typeof payloadRecord?.expiresIn === 'number' ? payloadRecord.expiresIn : undefined)
    };
};

