const normalizeDashboardRuleSummary = (payload: unknown) => {
    const record = asRecord(payload);
    const topRules = Array.isArray(record?.topRules) ? record.topRules : [];
    return {
        totalRules: Number(record?.totalRules || 0),
        activeRules: Number(record?.activeRules || 0),
        topRules: topRules.map((rule) => {
            const ruleRecord = asRecord(rule);
            return {
                id: typeof ruleRecord?.id === 'string' ? ruleRecord.id : typeof ruleRecord?.ruleId === 'string' ? ruleRecord.ruleId : '',
                name: typeof ruleRecord?.name === 'string'
                    ? ruleRecord.name
                    : typeof ruleRecord?.id === 'string'
                        ? ruleRecord.id
                        : typeof ruleRecord?.ruleId === 'string'
                            ? ruleRecord.ruleId
                            : 'Unnamed rule',
                severity: typeof ruleRecord?.severity === 'string' ? ruleRecord.severity : 'medium',
                count: Number(ruleRecord?.count ?? ruleRecord?.hitCount ?? 0),
                source: typeof ruleRecord?.source === 'string' ? ruleRecord.source : 'event'
            };
        })
    };
};

