const progressDemoScanTasks = () => {
    const now = Date.now();
    demoScanTasksStore = demoScanTasksStore.map((task) => {
        if (task.status !== 'pending' && task.status !== 'running') {
            return task;
        }

        const ageMs = now - new Date(task.createdAt).getTime();
        if (ageMs > 7_000) {
            return {
                ...task,
                status: 'completed',
                phase: 'done',
                progress: 100,
                completedAt: new Date().toISOString()
            };
        }

        if (ageMs > 4_000) {
            return {
                ...task,
                status: 'running',
                phase: 'nuclei-scan',
                progress: 82
            };
        }

        return {
            ...task,
            status: 'running',
            phase: 'host-scan',
            progress: 46
        };
    });
};

